INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(2701, 76, 'What is a process in an operating system?', 'A program in execution', 'A hardware device', 'A file stored on disk', 'A programming language', 'A', 'A process is an instance of a program that is currently being executed by the CPU, including its code, data and resources.', 'BEGINNER', 1, 'MCQ', 1),
(2702, 76, 'Which is the smallest unit of CPU utilization that can be independently scheduled?', 'Process Control Block', 'Thread', 'Device driver', 'System call', 'B', 'A thread is the smallest unit of execution that the operating system scheduler assigns to the CPU.', 'BEGINNER', 1, 'MCQ', 1),
(2703, 76, 'Which data structure holds the state, registers and scheduling information of a process?', 'Page table', 'File allocation table', 'Process Control Block', 'System call table', 'C', 'The Process Control Block stores all metadata about a process, including its identifier, state, registers and scheduling information.', 'BEGINNER', 1, 'MCQ', 1),
(2704, 76, 'A process that is waiting for an I/O event to complete is in which state?', 'Ready', 'Running', 'New', 'Waiting', 'D', 'A process moves to the waiting (blocked) state when it needs an event such as I/O completion before it can continue.', 'BEGINNER', 1, 'MCQ', 1),
(2705, 76, 'What does the abbreviation PCB stand for?', 'Process Control Block', 'Processor Cache Buffer', 'Program Compile Block', 'Process Code Base', 'A', 'PCB is the Process Control Block, the kernel data structure that represents a process and holds its state and resources.', 'BEGINNER', 1, 'MCQ', 1),
(2706, 76, 'Which system call is used to create a new process in a Unix-like operating system?', 'exec', 'fork', 'clone', 'spawn', 'B', 'fork creates a nearly identical copy of the calling process, from which the new child process begins execution.', 'BEGINNER', 1, 'MCQ', 1),
(2707, 76, 'Which of the following is NOT a typical process state?', 'Ready', 'Running', 'Registered', 'Terminated', 'C', 'Typical process states are new, ready, running, waiting and terminated, and Registered is not among them.', 'BEGINNER', 1, 'MCQ', 1),
(2708, 76, 'What is a context switch?', 'Rebooting the system', 'Switching keyboard layouts', 'Copying files between directories', 'Saving the current process state and loading the state of another', 'D', 'A context switch saves the state of the currently running process and loads the saved state of another so the CPU can resume it.', 'BEGINNER', 1, 'MCQ', 1),
(2709, 76, 'Threads belonging to the same process share which of the following?', 'The code and data sections', 'Individual register sets', 'Separate address spaces', 'Their own page tables', 'A', 'Threads share the code, data and heap of their parent process while keeping their own registers and stacks.', 'BEGINNER', 1, 'MCQ', 1),
(2710, 76, 'Which of the following is often called a light-weight process?', 'A child process', 'A thread', 'A daemon', 'A zombie process', 'B', 'Threads are called light-weight processes because they share the address space of their parent and are cheaper to create and switch than full processes.', 'BEGINNER', 1, 'MCQ', 1),
(2711, 76, 'A process calls fork() and the child immediately calls exec(). What is the effect of exec()?', 'The child continues from the fork point', 'The child''s memory image is replaced by a new program', 'The parent terminates', 'A second fork is created', 'B', 'exec replaces the calling process''s memory image with a new program, so the child begins executing a different program.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2712, 76, 'Which scenario best describes a zombie process?', 'A process that uses all CPU time', 'A process waiting for I/O', 'A terminated process whose exit status has not yet been collected by its parent', 'A process with no memory', 'C', 'A zombie (defunct) process has terminated but still holds an entry in the process table until its parent calls wait() to collect its exit status.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2713, 76, 'Which statement best describes an orphan process?', 'A process that runs in the background', 'A process holding no resources', 'A process that cannot be killed', 'A process whose parent terminated before the child', 'D', 'An orphan process is adopted by the init process after its original parent dies, so its parent-child link is reassigned.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2714, 76, 'Which event moves a process from the Ready queue to the Running state?', 'The scheduler dispatches it to the CPU', 'It finishes its I/O', 'It calls exit()', 'It is first created', 'A', 'A ready process is dispatched by the CPU scheduler, which assigns it the processor and transitions it to the running state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2715, 76, 'A process with three threads calls fork() on Linux. What is the result?', 'One new process with one thread', 'Three new processes', 'Two processes, each with three threads', 'One process with six threads', 'C', 'fork duplicates the entire process including all of its threads, so the result is two processes each with three threads.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2716, 76, 'Which of the following is an advantage of threads over processes?', 'Threads have isolated address spaces', 'Threads are more secure', 'Threads cannot crash', 'Threads share memory and are cheaper to create', 'D', 'Threads share the address space of their process, making inter-thread communication and thread creation faster than separate processes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2717, 76, 'A web server handles many clients by assigning one thread per client. This model is called:', 'Thread-per-request', 'One process per client', 'Single-threaded polling', 'Event-free execution', 'A', 'The thread-per-request model handles each client with its own thread, allowing concurrent service while threads share server data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2718, 76, 'Which of the following is stored in a thread control block (TCB) rather than shared with other threads?', 'Open file table', 'Program counter and register set', 'Memory limits', 'Signal handlers', 'B', 'The program counter and register set are per-thread and kept in the TCB, while resources such as files and memory belong to the process.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2719, 76, 'When does a very small time quantum combined with frequent context switching hurt performance?', 'Never', 'Only at boot time', 'When no processes are ready', 'When so much time is spent switching that useful work is reduced', 'D', 'Frequent context switching with a tiny quantum wastes CPU time saving and restoring state instead of doing useful work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2720, 76, 'After a process calls fork(), how does the child know it is the child?', 'The parent sends a message', 'The child reads its PID', 'fork() returns 0 to the child and the child''s PID to the parent', 'The child checks the parent''s state', 'C', 'fork returns the child''s PID to the parent and returns 0 to the child, which is how the two code paths are distinguished.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2721, 76, 'In a copy-on-write system, when is a page actually duplicated after fork()?', 'Immediately at fork', 'At the child''s termination', 'When either parent or child writes to the shared page', 'Never', 'C', 'With copy-on-write, pages are shared read-only after fork and duplicated only when a process attempts a write.', 'ADVANCED', 3, 'MCQ', 1),
(2722, 76, 'Which thread model keeps all scheduling in a user-space library, giving very low context-switch cost?', 'One-to-one', 'Many-to-many', 'Kernel threads only', 'User-level threads (many-to-one)', 'D', 'User-level threads are managed entirely by a library in user space without kernel involvement, so their switches are very cheap.', 'ADVANCED', 3, 'MCQ', 1),
(2723, 76, 'In the one-to-one thread model, what is a major disadvantage?', 'Every thread operation needs a kernel system call, adding overhead', 'Threads cannot share data', 'Only one thread can run', 'Threads cannot access files', 'A', 'The one-to-one model gives good parallelism but each thread creation and switch requires a kernel call, which is expensive.', 'ADVANCED', 3, 'MCQ', 1),
(2724, 76, 'How is a real-time thread typically scheduled differently from a normal thread?', 'It has lower priority', 'It is scheduled by priority or deadline rather than a fair time slice', 'It never blocks', 'It always stays on one core', 'B', 'Real-time scheduling uses priorities or deadlines so time-critical threads meet their timing requirements instead of sharing equal time slices.', 'ADVANCED', 3, 'MCQ', 1),
(2725, 76, 'Which statement correctly describes the relationship between a process and its threads?', 'A process is always single-threaded', 'Threads are independent processes', 'Threads cannot be terminated', 'Threads are execution streams within a process sharing its resources', 'D', 'Threads are execution streams that run within a process, sharing its resources while having individual program counters and stacks.', 'ADVANCED', 3, 'MCQ', 1),
(2726, 76, 'Why does a server use a thread pool instead of creating a new thread per request?', 'Creating and destroying threads is expensive, so reusing threads reduces overhead', 'Thread pools increase disk usage', 'Thread pools remove concurrency', 'A pool forces single-threading', 'A', 'Reusing idle threads from a pool avoids the cost of repeatedly creating and destroying threads for each request.', 'ADVANCED', 3, 'MCQ', 1),
(2727, 76, 'What does gang scheduling do for cooperating threads on multicore systems?', 'Runs them on random cores', 'Schedules all threads of a group simultaneously on different cores', 'Runs only one thread at a time', 'Prevents preemption entirely', 'B', 'Gang scheduling runs all threads of a cooperating group at the same time on different processors, helping parallel applications progress together.', 'ADVANCED', 3, 'MCQ', 1),
(2728, 76, 'Which condition describes a process suffering from CPU starvation?', 'It is always running', 'It never enters the ready queue', 'It is ready but the scheduler never dispatches it', 'It holds the CPU forever', 'C', 'A ready process that is never selected by the scheduler suffers starvation when the scheduler keeps choosing other processes.', 'ADVANCED', 3, 'MCQ', 1),
(2729, 76, 'Why is fork() nearly free for a large parent process with copy-on-write?', 'Pages are shared read-only and duplicated only on first write', 'The whole memory is copied instantly', 'The process table is emptied', 'The TLB is flushed only', 'A', 'Copy-on-write defers actual page duplication until a write occurs, making fork fast even for very large address spaces.', 'ADVANCED', 3, 'MCQ', 1),
(2730, 76, 'How does a multithreaded process terminate all of its threads?', 'Kill only the main thread', 'Exit when the first thread finishes', 'Suspend the process', 'Exit the process; all its threads end with it', 'D', 'Terminating a process terminates all of its threads; individual threads cannot continue once the owning process exits.', 'ADVANCED', 3, 'MCQ', 1),
(2731, 77, 'Which scheduling algorithm serves processes in the order in which they arrive?', 'First-Come, First-Served (FCFS)', 'Shortest Job First', 'Round Robin', 'Priority', 'A', 'FCFS dispatches the process that arrived earliest, using a simple FIFO queue.', 'BEGINNER', 1, 'MCQ', 1),
(2732, 77, 'Which algorithm gives each ready process an equal time slice called a quantum?', 'FCFS', 'Round Robin', 'Shortest Job First', 'Priority', 'B', 'Round Robin cycles through the ready queue, granting each process one time quantum before preempting it.', 'BEGINNER', 1, 'MCQ', 1),
(2733, 77, 'When the running process blocks on I/O, what does the scheduler do?', 'Nothing', 'Suspends all processes', 'Selects another ready process to run', 'Kills the blocked process', 'C', 'When the running process blocks, the dispatcher picks the next ready process so the CPU remains busy.', 'BEGINNER', 1, 'MCQ', 1),
(2734, 77, 'Which of the following is a scheduling decision?', 'Choosing a process to run', 'Deciding whether to preempt', 'Tuning the time quantum', 'All of the above', 'D', 'Scheduling involves selecting which process runs, deciding when to preempt and tuning the time quantum.', 'BEGINNER', 1, 'MCQ', 1),
(2735, 77, 'What is the turnaround time of a process?', 'Completion time minus arrival time', 'Waiting time minus arrival', 'Burst time minus waiting', 'Arrival time minus completion', 'A', 'Turnaround time measures the total time from a process''s arrival until its completion.', 'BEGINNER', 1, 'MCQ', 1),
(2736, 77, 'What is the waiting time of a process?', 'Only the time from arrival to first dispatch', 'Total time the process spends in the ready queue', 'The burst time', 'Completion time', 'B', 'Waiting time is the total time a process spends in the ready queue, excluding time spent executing.', 'BEGINNER', 1, 'MCQ', 1),
(2737, 77, 'Which algorithm is theoretically optimal for average waiting time?', 'FCFS', 'Round Robin', 'Shortest Job First (SJF)', 'None of them', 'C', 'SJF provably gives the minimum average waiting time for a given set of burst times.', 'BEGINNER', 1, 'MCQ', 1),
(2738, 77, 'What is preemption in CPU scheduling?', 'Never interrupting a process', 'Waiting for user input', 'Letting a process run forever', 'Forcibly removing the CPU from a running process', 'D', 'Preemption lets the scheduler take the CPU away from a running process to give it to another.', 'BEGINNER', 1, 'MCQ', 1),
(2739, 77, 'Which criterion measures the time from submission until the first response?', 'Throughput', 'Response time', 'Turnaround time', 'Burst time', 'B', 'Response time is the time from submission of a request until the first response is produced.', 'BEGINNER', 1, 'MCQ', 1),
(2740, 77, 'What is throughput in CPU scheduling?', 'Processes completed per unit time', 'Time for one process', 'CPU utilization percent', 'Ready queue length', 'A', 'Throughput counts how many processes are completed in a given time interval.', 'BEGINNER', 1, 'MCQ', 1),
(2741, 77, 'Processes P1(3), P2(6), P3(4), P4(7) arrive at time 0 and run under FCFS in that order. What is the average waiting time?', '5.5', '6.25', '7.0', '6.75', 'B', 'FCFS waiting times are 0, 3, 9 and 13, summing to 25, which averages to 6.25.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2742, 77, 'Under non-preemptive SJF with P1(6), P2(8), P3(7), P4(3), what is the average turnaround time?', '14', '12.5', '13', '15', 'C', 'SJF runs jobs in ascending burst order giving completion times 3, 9, 16 and 24, which average to 13.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2743, 77, 'With Round Robin, quantum 4, and bursts P1(6), P2(8), P3(7), P4(3), what is P1''s waiting time?', '7', '9', '13', '11', 'D', 'P1 runs at 0-4 and again at 15-17, completing at 17, so its waiting time is 17 - 6 = 11.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2744, 77, 'Which is a major drawback of FCFS in time-sharing systems?', 'The convoy effect and poor response for short jobs', 'It is too complex', 'It cannot preempt at all', 'It needs a quantum', 'A', 'FCFS lets long jobs block short ones behind them (the convoy effect) and gives poor response times.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2745, 77, 'In priority scheduling, what does aging do?', 'Decreases priority', 'Keeps priority fixed', 'Gradually increases priority to prevent starvation', 'Resets priority to zero', 'C', 'Aging gradually raises the priority of waiting processes so that low-priority ones eventually get the CPU.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2746, 77, 'Which scheduling algorithm can suffer from starvation?', 'Round Robin', 'FCFS', 'Highest Response Ratio Next', 'Priority scheduling', 'D', 'In pure priority scheduling, low-priority processes may wait indefinitely if higher-priority work keeps arriving.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2747, 77, 'A process arrives at time 0 with burst 10 and completes at time 10. Its waiting time is:', '0', '5', '10', '20', 'A', 'Waiting time is completion minus arrival minus burst, which is 10 - 0 - 10 = 0.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2748, 77, 'Which statement about non-preemptive SJF is correct?', 'It always gives optimal response', 'A short job that arrives while a long job runs can be delayed', 'It never causes delay', 'It cannot be implemented', 'B', 'Non-preemptive SJF can delay a short job that arrives while a long job is running, so it is not always optimal.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2749, 77, 'In Round Robin, a very small time quantum causes:', 'Less context switching', 'Higher throughput', 'Lower overhead', 'Excessive context-switch overhead', 'D', 'A tiny quantum forces the scheduler to switch processes too often, wasting CPU time on context switches.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2750, 77, 'How does Highest Response Ratio Next (HRRN) choose the next process?', 'Picks the shortest job', 'Picks the lowest priority job', 'Picks the job with the highest (waiting + service) / service ratio', 'Uses a fixed quantum', 'C', 'HRRN computes a response ratio of (wait + service) / service and runs the job with the highest ratio, balancing SJF and FCFS.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2751, 77, 'Which mechanism is required to enforce preemptive Round Robin?', 'A non-preemptive scheduler', 'A batch dispatcher', 'A timer interrupt that returns control to the scheduler each quantum', 'A user-level lock', 'C', 'Preemption relies on the timer interrupt firing each quantum so the scheduler can take the CPU back from the running process.', 'ADVANCED', 3, 'MCQ', 1),
(2752, 77, 'Why is SJF usually unsuitable for hard real-time systems?', 'It uses too much memory', 'It ignores priorities', 'It cannot run on modern CPUs', 'It optimizes average time instead of meeting deadlines', 'D', 'SJF minimizes average waiting time but does not guarantee that each task meets its deadline, so real-time schedulers like EDF are preferred.', 'ADVANCED', 3, 'MCQ', 1),
(2753, 77, 'With Round Robin (quantum 4) and bursts P1(9), P2(4), P3(9), what is the average turnaround time?', '15', '16', '17', '14', 'A', 'Round Robin gives completion times P2=8, P1=16 and P3=21, so the average turnaround time is (8 + 16 + 21) / 3 = 15.', 'ADVANCED', 3, 'MCQ', 1),
(2754, 77, 'In a multilevel feedback queue, what happens to a CPU-bound process?', 'It stays in the highest queue', 'It sinks to lower-priority queues over time', 'It is never preempted', 'It is terminated', 'B', 'Multilevel feedback queues move processes down to lower-priority queues when they use their full quantum, so CPU-bound jobs sink over time.', 'ADVANCED', 3, 'MCQ', 1),
(2755, 77, 'Which combination gives near-optimal average waiting time without starvation?', 'FCFS alone', 'Round Robin with quantum 100', 'Random scheduling', 'SJF with aging', 'D', 'Aging added to SJF keeps the optimal average waiting time while guaranteeing that every process eventually runs.', 'ADVANCED', 3, 'MCQ', 1),
(2756, 77, 'Why is mixing CPU-bound and I/O-bound processes beneficial?', 'It keeps both the CPU and devices busy, improving utilization', 'It simplifies the scheduler', 'It avoids context switches', 'It prevents all waiting', 'A', 'Interleaving CPU-bound and I/O-bound processes keeps both the CPU and I/O devices busy, improving overall utilization.', 'ADVANCED', 3, 'MCQ', 1),
(2757, 77, 'What is the specific job of the dispatcher?', 'Sorting the ready queue', 'Performing the context switch to start the selected process', 'Handling page faults', 'Updating the process table', 'B', 'The dispatcher is the module that switches context and hands control of the CPU to the process selected by the scheduler.', 'ADVANCED', 3, 'MCQ', 1),
(2758, 77, 'Which setting makes Round Robin feel most responsive to interactive users?', 'A very large quantum', 'No preemption', 'A small quantum that gives every process a quick turn', 'FCFS ordering', 'C', 'A small quantum lets every process get the CPU quickly, giving fast first responses to interactive users despite more overhead.', 'ADVANCED', 3, 'MCQ', 1),
(2759, 77, 'In periodic scheduling, if a task''s worst-case execution time exceeds its period, what follows?', 'The task cannot be feasibly scheduled and deadlines will be missed', 'It runs twice per period', 'It is automatically migrated', 'It never runs', 'A', 'If the worst-case execution time of a periodic task is greater than its period, even a perfect scheduler cannot meet every deadline.', 'ADVANCED', 3, 'MCQ', 1),
(2760, 77, 'What does guaranteed scheduling do?', 'Uses SJF ordering', 'Uses a random quantum', 'Prevents context switches', 'Tracks actual CPU use and gives the next quantum to the process furthest below its guaranteed share', 'D', 'Guaranteed scheduling monitors how much CPU each process has consumed and allocates the next quantum to the one furthest below its guaranteed share.', 'ADVANCED', 3, 'MCQ', 1),
(2761, 78, 'What is a race condition?', 'Two processes reading different files', 'Concurrent access to shared data whose outcome depends on timing', 'A hardware failure', 'A slow-running program', 'A', 'A race condition occurs when concurrent access to shared data makes the outcome depend on the unpredictable timing of the operations.', 'BEGINNER', 1, 'MCQ', 1),
(2762, 78, 'Which section of code accesses shared resources and must not be entered by two processes at once?', 'Entry section', 'Critical section', 'Exit section', 'Remainder section', 'B', 'The critical section is the code segment where a process accesses shared variables and mutual exclusion must be enforced.', 'BEGINNER', 1, 'MCQ', 1),
(2763, 78, 'What does mutual exclusion guarantee?', 'All processes run at once', 'No process ever runs', 'At most one process is in its critical section at a time', 'Processes always run in order', 'C', 'Mutual exclusion means at most one process may execute in its critical section at any given moment.', 'BEGINNER', 1, 'MCQ', 1),
(2764, 78, 'Which of the following is a synchronization primitive for controlling access to shared resources?', 'Compiler', 'Scheduler queue', 'Page table', 'Semaphore', 'D', 'A semaphore is a synchronization primitive whose wait and signal operations control access to shared resources.', 'BEGINNER', 1, 'MCQ', 1),
(2765, 78, 'What does the wait() (P) operation do on a semaphore?', 'Decrements the value and blocks the caller when it becomes negative', 'Increments the value', 'Resets it to zero', 'Never changes it', 'A', 'wait() decrements the semaphore and blocks the caller when the value becomes negative, enforcing mutual exclusion.', 'BEGINNER', 1, 'MCQ', 1),
(2766, 78, 'What does the signal() (V) operation do on a semaphore?', 'Decrements the value', 'Increments the value and may wake a waiting process', 'Deletes the semaphore', 'Blocks the caller', 'B', 'signal() increments the semaphore and wakes one waiting process if any, allowing it to proceed.', 'BEGINNER', 1, 'MCQ', 1),
(2767, 78, 'What is a mutex lock?', 'A file lock', 'A page table entry', 'A lock providing mutual exclusion for a critical section', 'A scheduling queue', 'C', 'A mutex is a lock that a process acquires before entering the critical section and releases after leaving, giving mutual exclusion.', 'BEGINNER', 1, 'MCQ', 1),
(2768, 78, 'What is busy waiting?', 'Sleeping for a long time', 'Waiting for I/O', 'Using the CPU for real work', 'Spinning in a loop while checking a condition instead of blocking', 'D', 'Busy waiting wastes CPU cycles by spinning and repeatedly testing a condition instead of yielding the processor.', 'BEGINNER', 1, 'MCQ', 1),
(2769, 78, 'Which classic problem involves producers and consumers sharing a bounded buffer?', 'Dining philosophers', 'Producer-consumer', 'Readers-writers', 'Banker''s algorithm', 'B', 'The producer-consumer problem requires producers and consumers to cooperate on a bounded buffer without overfilling or underreading it.', 'BEGINNER', 1, 'MCQ', 1),
(2770, 78, 'Which requirement ensures that when the critical section is free and some processes want to enter, one is chosen in finite time?', 'Progress', 'Mutual exclusion', 'Bounded waiting', 'Atomicity', 'A', 'Progress guarantees that when the critical section is free, one of the processes requesting entry will be selected within a finite time.', 'BEGINNER', 1, 'MCQ', 1),
(2771, 78, 'Two threads both execute counter = counter + 1 after reading counter as 10. What can the final value be?', '12', '11', '20', '9', 'B', 'Both threads read 10 and write back 11, losing one increment; this is a classic race condition.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2772, 78, 'Peterson''s algorithm is correct for two processes under which assumption?', 'Round Robin scheduling', 'Strict alternation required', 'Strictly interleaved execution with no simultaneous writes to shared variables', 'A time quantum', 'C', 'Peterson''s algorithm assumes strictly interleaved execution, so simultaneous writes to shared variables must not occur.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2773, 78, 'In the bounded buffer problem, why does the producer call wait(empty) before adding an item?', 'To enlarge the buffer', 'To ensure mutual exclusion', 'To sleep forever', 'To block when no free slot remains, preventing overflow', 'D', 'The producer decrements the empty semaphore first so it blocks when the buffer has no free slots, preventing overflow.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2774, 78, 'A binary semaphore starts at 1. Two processes both call wait(). What happens?', 'The first enters and the second blocks', 'Both enter', 'Both block', 'The system crashes', 'A', 'The first wait() makes the value 0 and the process enters; the second wait() makes it -1 and that process blocks until signal() is called.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2775, 78, 'Which problem shows how grabbing two resources at once can deadlock?', 'Producer-consumer', 'Bounded buffer', 'Dining philosophers', 'Readers-writers', 'C', 'The dining philosophers problem demonstrates how picking up both forks can lead to deadlock when every philosopher waits for a neighbour.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2776, 78, 'In the readers-writers solution, why is the readcount variable protected by a mutex?', 'So readers can write', 'To speed up readers', 'To block all writers', 'Because multiple readers must update it atomically', 'D', 'The readcount variable is shared by all readers, so a mutex is needed to update it atomically and avoid a race.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2777, 78, 'A counting semaphore starts at 3 and five processes call wait(). What is its final value?', '-2', '2', '5', '-5', 'A', 'Each wait() decrements the semaphore, so 3 - 5 = -2, meaning two processes are waiting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2778, 78, 'Which primitive avoids busy waiting?', 'Spinlock', 'A blocking semaphore that suspends processes in a wait queue', 'Test-and-set lock', 'Compare-and-swap lock', 'B', 'A blocking semaphore suspends the process and places it in a wait queue instead of spinning in a loop.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2779, 78, 'What does the test-and-set instruction do?', 'Sets the value to the new one only', 'Returns nothing', 'Returns a random number', 'Atomically reads the old value and sets the target to true', 'D', 'Test-and-set atomically reads the old value and writes 1, returning the old value so locks can be acquired safely.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2780, 78, 'Why does the producer-consumer solution need a mutex in addition to the semaphores?', 'To count empty slots', 'To count full items', 'To protect the buffer and its pointers from concurrent modification', 'To prevent deadlock', 'C', 'The mutex ensures only one process modifies the buffer and its pointers at a time, while the semaphores manage capacity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2781, 78, 'When is a spinlock preferable to a blocking mutex?', 'When the critical section is held for a long time', 'When waiting processes should sleep', 'When the critical section is very short on a multicore system', 'When there is a single CPU', 'C', 'If the lock is held briefly, spinning wastes less time than a context switch, so spinlocks fit short critical sections on multicore systems.', 'ADVANCED', 3, 'MCQ', 1),
(2782, 78, 'Why can Peterson''s algorithm fail on modern hardware?', 'It is too slow', 'It needs three processes', 'It requires preemption', 'Compilers and CPUs reorder memory operations, breaking its ordering assumptions', 'D', 'Compilers and CPUs reorder loads and stores, so Peterson''s ordering assumptions fail without memory barriers.', 'ADVANCED', 3, 'MCQ', 1),
(2783, 78, 'Which guarantee does a monitor provide?', 'Mutual exclusion plus condition variables for synchronization', 'Only mutual exclusion', 'Only bounded waiting', 'Faster execution', 'A', 'A monitor encapsulates shared data and procedures, guaranteeing mutual exclusion and offering condition variables for waiting and signaling.', 'ADVANCED', 3, 'MCQ', 1),
(2784, 78, 'In a monitor, what does wait() on a condition variable do?', 'Continues executing', 'Atomically releases the monitor lock and sleeps until signaled', 'Raises the process priority', 'Restarts the process', 'B', 'wait() atomically releases the monitor lock and suspends the caller until another procedure calls signal() on the same condition.', 'ADVANCED', 3, 'MCQ', 1),
(2785, 78, 'Which condition makes a blocking bounded-buffer solution correct?', 'The producer never blocks', 'The buffer is infinite', 'Only one producer exists', 'The producer blocks when the buffer is full and the consumer blocks when it is empty', 'D', 'Blocking on the empty and full semaphores prevents overflow and underflow when the buffer is bounded.', 'ADVANCED', 3, 'MCQ', 1),
(2786, 78, 'Which software-only algorithm solves mutual exclusion for two processes?', 'Peterson''s algorithm', 'Round Robin', 'Banker''s algorithm', 'Optimal replacement', 'A', 'Peterson''s algorithm uses shared turn and flag variables to achieve mutual exclusion, progress and bounded waiting for two processes in software.', 'ADVANCED', 3, 'MCQ', 1),
(2787, 78, 'What is a lock-free data structure?', 'One that disables interrupts', 'One whose operations guarantee progress using atomic instructions without blocking locks', 'One with no elements', 'One used only by the kernel', 'B', 'Lock-free algorithms use atomic instructions like compare-and-swap so that at least one thread always makes progress without acquiring locks.', 'ADVANCED', 3, 'MCQ', 1),
(2788, 78, 'Which design avoids both busy waiting and the convoy effect on multicore systems?', 'Pure spinlocks', 'Pure mutexes', 'Spinning briefly, then blocking if the lock is still held', 'Disabling interrupts', 'C', 'Spinning briefly and then blocking balances low latency for short holds with no wasted CPU for long holds.', 'ADVANCED', 3, 'MCQ', 1),
(2789, 78, 'Why can disabling interrupts cause priority inversion in real-time systems?', 'It delays high-priority work and a low-priority task holding a lock can block higher-priority ones', 'It uses too much memory', 'It cannot be implemented', 'It always causes deadlock', 'A', 'Disabling interrupts blocks important events, and without priority inheritance, a low-priority task holding a lock can invert priorities.', 'ADVANCED', 3, 'MCQ', 1),
(2790, 78, 'Which statement about priority inversion is correct?', 'It never happens with mutexes', 'It affects only batch systems', 'It makes high-priority tasks faster', 'A low-priority task holding a lock delays a high-priority task that needs it', 'D', 'Priority inversion is the situation where a high-priority task is blocked by a low-priority task holding a resource; priority inheritance reduces its impact.', 'ADVANCED', 3, 'MCQ', 1),
(2791, 79, 'What is a deadlock?', 'A set of processes each waiting for an event only another process in the set can cause', 'A process that runs forever', 'A hardware failure', 'A slow I/O operation', 'A', 'Deadlock occurs when every process in a set waits for a resource held by another, so none can proceed.', 'BEGINNER', 1, 'MCQ', 1),
(2792, 79, 'Which of the following is NOT one of the four necessary conditions for deadlock?', 'Mutual exclusion', 'Preemption', 'Hold and wait', 'Circular wait', 'B', 'No preemption (resources cannot be forcibly taken) is a necessary condition; preemption actually helps break deadlock.', 'BEGINNER', 1, 'MCQ', 1),
(2793, 79, 'Which necessary condition requires a process to hold a resource while waiting for another?', 'Mutual exclusion', 'Circular wait', 'Hold and wait', 'No preemption', 'C', 'Hold and wait means a process already holds resources while requesting additional ones.', 'BEGINNER', 1, 'MCQ', 1),
(2794, 79, 'What does a resource allocation graph represent?', 'CPU usage over time', 'Memory layout', 'File sizes', 'Which processes hold and request which resources', 'D', 'The resource allocation graph shows processes and resources as nodes, with request and assignment edges depicting their relationships.', 'BEGINNER', 1, 'MCQ', 1),
(2795, 79, 'Which of the following is a deadlock prevention strategy?', 'Breaking one of the four necessary conditions', 'Ignoring deadlocks', 'Overheating the CPU', 'Increasing context switches', 'A', 'Deadlock prevention eliminates at least one necessary condition, such as allowing preemption of resources.', 'BEGINNER', 1, 'MCQ', 1),
(2796, 79, 'Which algorithm determines whether a system is in a safe state?', 'Round Robin', 'Banker''s algorithm', 'First-Come, First-Served', 'Shortest Job First', 'B', 'The Banker''s algorithm simulates resource allocation to see if all processes can complete without deadlock.', 'BEGINNER', 1, 'MCQ', 1),
(2797, 79, 'What is a safe state?', 'A state with no processes', 'A state where the CPU is idle', 'A state from which resources can be allocated so every process can finish without deadlock', 'A state with unlimited memory', 'C', 'A safe state has a sequence of allocations allowing every process to finish, guaranteeing no deadlock occurs.', 'BEGINNER', 1, 'MCQ', 1),
(2798, 79, 'Which is a valid deadlock recovery method?', 'Adding more RAM', 'Speeding up the CPU', 'Rebooting only the display', 'Preempting resources or terminating a process', 'D', 'Recovery from deadlock can involve preempting resources from some process or terminating processes to release their resources.', 'BEGINNER', 1, 'MCQ', 1),
(2799, 79, 'Which condition states that each resource instance can be held by only one process at a time?', 'Hold and wait', 'Mutual exclusion', 'Circular wait', 'No preemption', 'B', 'Mutual exclusion means each resource instance can be used by only one process at a time.', 'BEGINNER', 1, 'MCQ', 1),
(2800, 79, 'What does a wait-for graph show?', 'Only which processes are waiting on which other processes', 'All resource assignments', 'The scheduling order', 'Memory allocations', 'A', 'The wait-for graph condenses the resource allocation graph by showing only which processes are waiting on which other processes.', 'BEGINNER', 1, 'MCQ', 1),
(2801, 79, 'Total resources are 10 units. A holds 4 (max 7) and B holds 4 (max 7). A requests 2 more. What happens?', 'Granted and still safe', 'Granted but the state becomes unsafe', 'The request is ignored', 'B is terminated', 'B', 'After the grant, available becomes 0 while A still needs 1 and B needs 3, so neither process can finish and the system enters an unsafe state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2802, 79, 'Requiring a process to release its held resources before requesting more breaks which condition?', 'Mutual exclusion', 'Circular wait', 'Hold and wait', 'No preemption', 'C', 'Requiring a process to release its held resources before requesting more removes the hold-and-wait condition.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2803, 79, 'In a resource allocation graph, an edge from resource R to process P means:', 'P requests R', 'R is being deleted', 'R is free', 'R is allocated to P', 'D', 'An assignment edge from a resource node to a process node means that resource is currently held by that process.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2804, 79, 'Requesting all resources in a fixed global order prevents deadlock by eliminating which condition?', 'Circular wait', 'Mutual exclusion', 'Hold and wait', 'No preemption', 'A', 'If every process requests resources in a fixed global order, a circular chain of waiting becomes impossible.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2805, 79, 'In the Banker''s algorithm, what does the Need matrix contain?', 'Total system resources', 'Resources currently allocated', 'Resources each process may still need to reach its maximum', 'Resources released', 'C', 'Need equals Maximum minus Allocation, the additional units each process may still request.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2806, 79, 'With a single instance of each resource type, which statement is correct?', 'Both waiting processes proceed', 'The system crashes', 'Resources duplicate', 'Deadlock is impossible because a cycle cannot form', 'D', 'With one instance per resource type, the wait-for graph is a chain and can never contain a cycle, so deadlock cannot happen.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2807, 79, 'How is deadlock detected with a wait-for graph?', 'A cycle in the graph indicates deadlock', 'The number of processes indicates it', 'RAM usage indicates it', 'CPU load indicates it', 'A', 'If the wait-for graph contains a cycle, the processes on that cycle are deadlocked.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2808, 79, 'What is the main advantage of deadlock avoidance over prevention?', 'It is always optimal', 'It is less restrictive while still preventing deadlock', 'It ignores worst cases', 'It never rejects requests', 'B', 'Avoidance permits requests that keep the system in a safe state, so it is less restrictive than prevention while guaranteeing no deadlock.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2809, 79, 'When recovering from deadlock by preemption, which process should be rolled back?', 'The first to finish', 'The one with the shortest code', 'The one holding the fewest resources', 'The one whose rollback costs the least', 'D', 'Choosing the process with the lowest rollback cost minimizes the expense of breaking the deadlock.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2810, 79, 'Which everyday scenario is a classic deadlock?', 'Two students sharing one printer at different times', 'A full mailbox blocking its sender', 'Two cars on a narrow bridge, each waiting for the other to move', 'A process waiting for user input', 'C', 'Each car holds one side of the bridge and waits for the other to move, creating a circular wait that is a classic deadlock.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2811, 79, 'Which statement correctly contrasts starvation and deadlock?', 'They are identical', 'Deadlock resolves itself', 'Starvation can occur without deadlock and a starved process may eventually run', 'Starvation requires all four conditions', 'C', 'Starvation is indefinite postponement of a ready process, which can happen without a circular wait, while deadlock is a permanent blocked state.', 'ADVANCED', 3, 'MCQ', 1),
(2812, 79, 'In a database, what is the most reasonable first deadlock recovery action?', 'Reboot the whole machine', 'Add memory', 'Terminate all user processes', 'Roll back the cheapest transaction in the cycle', 'D', 'Rolling back the least-expensive transaction breaks the cycle with minimal loss of work and is the standard recovery step.', 'ADVANCED', 3, 'MCQ', 1),
(2813, 79, 'Why is a cycle in a resource allocation graph not always fatal when resources have multiple instances?', 'The remaining free instances may satisfy the outstanding requests in the cycle', 'Cycles are impossible', 'Resources preempt automatically', 'Only one process can wait', 'A', 'With multiple instances per resource type, a cycle in the graph does not guarantee deadlock, so the detection algorithm must check availability.', 'ADVANCED', 3, 'MCQ', 1),
(2814, 79, 'What is the main practical limitation of the Banker''s algorithm?', 'It is too slow', 'Each process must declare its maximum resource need in advance', 'It cannot detect deadlock', 'It uses too much memory', 'B', 'Banker''s needs a priori knowledge of each process''s maximum claim, which is rarely available in practice.', 'ADVANCED', 3, 'MCQ', 1),
(2815, 79, 'Granting a request only if the resulting state stays safe is known as:', 'Deadlock prevention', 'Deadlock detection', 'The ostrich approach', 'Deadlock avoidance', 'D', 'Deadlock avoidance, the Banker''s approach, checks each request against safety and only grants it if the state remains safe.', 'ADVANCED', 3, 'MCQ', 1),
(2816, 79, 'Ordering resources and requiring increasing-order requests prevents deadlock by breaking:', 'Circular wait', 'Mutual exclusion', 'Hold and wait', 'Preemption', 'A', 'A total ordering of resource types with strictly increasing request order makes circular waiting impossible.', 'ADVANCED', 3, 'MCQ', 1),
(2817, 79, 'With one instance per resource type, which wait-for graph indicates deadlock?', 'Only cycles including multi-instance resources', 'Any cycle, because each edge is a wait on a held resource', 'Only self-loops', 'No cycles', 'B', 'With one instance per type, every edge in the cycle is a wait on a held resource, so any cycle means deadlock.', 'ADVANCED', 3, 'MCQ', 1),
(2818, 79, 'Preempting a resource from a holding process directly violates which condition?', 'Mutual exclusion', 'Circular wait', 'No preemption', 'Hold and wait', 'C', 'Preempting a resource from a holding process violates the no-preemption condition, which is how the deadlock is resolved.', 'ADVANCED', 3, 'MCQ', 1),
(2819, 79, 'Why do many operating systems prefer the ostrich approach to deadlocks?', 'Deadlocks are rare and handling them is often more costly than occasional restarts', 'Deadlocks never occur', 'It is the only option', 'It improves CPU speed', 'A', 'Because deadlocks occur rarely and cost little to fix manually, many systems prefer the simple ostrich approach over expensive avoidance or detection.', 'ADVANCED', 3, 'MCQ', 1),
(2820, 79, 'Which request can lead to a deadlock the Banker''s algorithm did not anticipate?', 'A request within the declared maximum', 'A process that never requests resources', 'A system with no resources', 'A process requesting more than its declared maximum', 'D', 'The Banker''s algorithm assumes processes never exceed their declared maximums; a request above the maximum breaks that assumption and can cause deadlock.', 'ADVANCED', 3, 'MCQ', 1),
(2821, 80, 'What is the main purpose of memory management?', 'Allocating and tracking memory for processes and the kernel', 'Compiling programs', 'Scheduling the CPU', 'Handling network packets', 'A', 'Memory management tracks and allocates memory so processes and the kernel get the space they need.', 'BEGINNER', 1, 'MCQ', 1),
(2822, 80, 'What is a page fault?', 'A hardware crash', 'An access to a page not currently in main memory', 'A CPU error', 'A disk error', 'B', 'A page fault occurs when a program references a page that is not resident in physical memory.', 'BEGINNER', 1, 'MCQ', 1),
(2823, 80, 'Which technique maps virtual addresses to physical addresses using fixed-size blocks?', 'Segmentation', 'Contiguous allocation', 'Paging', 'Fragmentation', 'C', 'Paging divides memory into fixed-size pages and frames and maps virtual pages to physical frames.', 'BEGINNER', 1, 'MCQ', 1),
(2824, 80, 'What does virtual memory allow a program to do?', 'Run without a CPU', 'Use memory as if it were far larger than physical RAM', 'Skip disk access', 'Share nothing', 'D', 'Virtual memory lets programs address more space than physical RAM by swapping pages between RAM and disk.', 'BEGINNER', 1, 'MCQ', 1),
(2825, 80, 'In a paged system, what is the smallest unit of allocation?', 'A page (frame)', 'A byte', 'A bit', 'A segment', 'A', 'Memory is divided into fixed-size pages in virtual space and frames in physical space, the smallest allocation unit.', 'BEGINNER', 1, 'MCQ', 1),
(2826, 80, 'What is a TLB?', 'A disk buffer', 'A fast cache of recent page table entries', 'A CPU register', 'A memory compiler', 'B', 'The translation look-aside buffer caches recent virtual-to-physical mappings to speed up address translation.', 'BEGINNER', 1, 'MCQ', 1),
(2827, 80, 'Which of the following causes external fragmentation?', 'Paging', 'Contiguous fixed partitions', 'Segmentation without paging', 'TLB caching', 'C', 'Segmentation allocates variable-sized segments that leave small unusable holes between them, causing external fragmentation.', 'BEGINNER', 1, 'MCQ', 1),
(2828, 80, 'What is internal fragmentation?', 'Holes between segments', 'Unused space inside an allocated block or page', 'A memory leak', 'Slow paging', 'B', 'Internal fragmentation is unused space inside an allocated region, such as leftover bytes at the end of a frame.', 'BEGINNER', 1, 'MCQ', 1),
(2829, 80, 'Which page replacement policy evicts the page unused for the longest time?', 'FIFO', 'LRU', 'Random', 'Second chance', 'B', 'Least Recently Used (LRU) evicts the page whose last use is furthest in the past.', 'BEGINNER', 1, 'MCQ', 1),
(2830, 80, 'What is thrashing?', 'Excessive paging that consumes more time than useful work', 'Very fast execution', 'A disk failure', 'A short process', 'A', 'Thrashing occurs when a system spends more time swapping pages in and out than executing instructions.', 'BEGINNER', 1, 'MCQ', 1),
(2831, 80, 'A 32-bit virtual address uses 4 KB pages. How many bits form the page number?', '10', '20', '12', '32', 'B', 'The offset uses log2(4096) = 12 bits, so the page number uses 32 - 12 = 20 bits.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2832, 80, 'With 16 KB pages and a 20-bit virtual address, how many page table entries are possible?', '128', '32', '64', '256', 'C', 'With a 16 KB page the offset needs 14 bits, leaving 6 bits for the page number, so at most 2^6 = 64 pages.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2833, 80, 'How many page faults does FIFO (3 frames) produce for reference string 1,2,3,4,1,2,5,1,2,3,4,5?', '7', '8', '9', '10', 'D', 'FIFO produces 10 page faults for this reference string with 3 frames, evicting pages in arrival order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2834, 80, 'A page table maps virtual pages to what?', 'Physical frames', 'Files', 'Threads', 'Segments', 'A', 'The page table translates each virtual page number into the physical frame where it currently resides.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2835, 80, 'What happens on a page fault, in correct order?', 'The CPU continues and the page loads later', 'The process is terminated', 'The kernel traps, loads the page from disk, updates the page table, and resumes the process', 'The TLB is cleared and nothing else happens', 'C', 'A page fault traps into the kernel, which fetches the missing page, updates the page table, and restarts the instruction.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2836, 80, 'Which of the following best reduces the cost of page faults?', 'A larger TLB only', 'A faster CPU', 'More registers', 'Fast storage or enough frames so few faults occur', 'D', 'Page faults are slow because of disk I/O, so faster storage or keeping pages in memory reduces the penalty.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2837, 80, 'If a page table entry has a valid bit of 0, what does it mean?', 'The page is not in memory and a reference causes a page fault', 'The page is in the TLB', 'The page is valid', 'The page is cached', 'A', 'A zero valid bit means the mapping is not current, so the hardware triggers a page fault to load the page.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2838, 80, 'Belady''s anomaly shows that:', 'More frames always reduce faults', 'Adding frames can increase page faults under FIFO', 'LRU can increase faults', 'Frames have no effect', 'B', 'Belady''s anomaly demonstrates that, with FIFO, adding more frames can paradoxically increase the number of page faults.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2839, 80, 'What is the working set of a process?', 'Its page table size', 'Its stack size', 'Its code size', 'The pages it is actively using in a recent window', 'D', 'The working set is the collection of pages referenced during a recent time window; it guides how many frames a process needs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2840, 80, 'Which statement about segmentation is correct?', 'All segments are equal in size', 'Segments cannot be shared', 'Segments are variable-sized logical units that can cause external fragmentation', 'Segmentation replaces paging', 'C', 'Segmentation uses variable-sized logical units that fit the program''s structure but leaves external fragmentation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2841, 80, 'Why do modern systems combine paging with segmentation?', 'To save disk space', 'To remove virtual memory', 'To get paging''s fixed-size management with segmentation''s protection and sharing', 'To simplify the TLB', 'C', 'Combined schemes page each segment, giving protection and sharing with paging''s fixed-size management.', 'ADVANCED', 3, 'MCQ', 1),
(2842, 80, 'A 64-bit virtual space cannot keep a full flat page table in memory. What solves this?', 'Adding RAM', 'Larger pages only', 'Faster CPUs', 'Multilevel page tables that keep only used portions resident', 'D', 'Multilevel (hierarchical) page tables page the page table itself, so only the portions in use need to be in memory.', 'ADVANCED', 3, 'MCQ', 1),
(2843, 80, 'Which algorithm is the practical approximation of LRU used in real systems?', 'Clock (second chance) with a reference bit', 'Optimal', 'Random', 'Pure FIFO', 'A', 'The clock algorithm uses a reference bit and a circular pointer to approximate LRU with low overhead, making it practical.', 'ADVANCED', 3, 'MCQ', 1),
(2844, 80, 'What limits the Optimal page replacement algorithm to benchmark use?', 'It is too slow', 'It requires future knowledge of the reference string', 'It needs too many frames', 'It cannot handle FIFO', 'B', 'Optimal replacement evicts the page used furthest in the future, which requires knowing future references, so it serves only as a comparison standard.', 'ADVANCED', 3, 'MCQ', 1),
(2845, 80, 'On a TLB miss, what happens next?', 'The instruction resumes', 'The system reboots', 'A disk swap occurs', 'The translation is found by walking the page table, then loaded into the TLB', 'D', 'On a TLB miss the translation must be located by walking the page table, then inserted into the TLB before the instruction resumes.', 'ADVANCED', 3, 'MCQ', 1),
(2846, 80, 'Which scenario is thrashing, and what is the best remedy?', 'The working set exceeds the frames allocated, so increase frames or reduce multiprogramming', 'Too many files are open', 'The TLB is full with no remedy', 'The disk is slow with no remedy', 'A', 'When the working set does not fit in the frames given, the process faults continuously; giving it enough frames or reducing multiprogramming stops the thrashing.', 'ADVANCED', 3, 'MCQ', 1),
(2847, 80, 'Which allocation strategy uses the smallest hole large enough for a process?', 'First fit', 'Best fit', 'Worst fit', 'Random fit', 'B', 'Best fit searches all holes and uses the smallest one large enough, leaving the smallest leftover gap.', 'ADVANCED', 3, 'MCQ', 1),
(2848, 80, 'Where does internal fragmentation most often appear in a paged system?', 'Inside variable segments', 'Across TLB entries', 'In the partially filled last page of a process', 'In the page table', 'C', 'Internal fragmentation occurs in the final page of a process, which is rarely fully utilized.', 'ADVANCED', 3, 'MCQ', 1),
(2849, 80, 'What is the main benefit of copy-on-write during fork()?', 'Read-only pages are shared and copied only on first write, making fork fast and memory-efficient', 'Everything is copied immediately', 'Paging is disabled', 'The TLB shrinks', 'A', 'Copy-on-write shares pages read-only and only copies on first write, making fork fast and memory-efficient.', 'ADVANCED', 3, 'MCQ', 1),
(2850, 80, 'How does page size relate to TLB coverage?', 'Larger pages increase needed entries', 'Smaller pages cover more memory per entry', 'Page size does not matter', 'Larger pages give each TLB entry more coverage, improving hit rates', 'D', 'A single TLB entry maps one full page, so larger pages mean each entry covers more memory, raising the hit ratio.', 'ADVANCED', 3, 'MCQ', 1),
(2851, 81, 'What is the purpose of virtual memory?', 'To let processes use more memory than physically exists by moving pages between RAM and secondary storage', 'To double the CPU speed', 'To compress files', 'To remove the need for RAM', 'A', 'Virtual memory extends the apparent size of memory by keeping parts of the address space on disk and swapping them in as needed.', 'BEGINNER', 1, 'MCQ', 1),
(2852, 81, 'What is a page in the context of paging?', 'A fixed-size block of physical memory', 'A fixed-size block of virtual address space', 'A variable-length chunk of a program', 'A sector of the hard disk', 'B', 'A page is a fixed-size unit of virtual memory that can be mapped to an equal-sized physical frame.', 'BEGINNER', 1, 'MCQ', 1),
(2853, 81, 'What event occurs when a program references a virtual address that is not currently in physical memory?', 'cache hit', 'deadlock', 'page fault', 'segmentation fault', 'C', 'A page fault happens when the referenced page is not resident in physical memory and must be brought in from disk.', 'BEGINNER', 1, 'MCQ', 1),
(2854, 81, 'What is a frame in a paging system?', 'A fixed-size block of virtual memory', 'A unit of file storage', 'A page table entry', 'A fixed-size block of physical memory', 'D', 'A frame is a fixed-size block of physical memory that a page can be loaded into.', 'BEGINNER', 1, 'MCQ', 1),
(2855, 81, 'What is the purpose of a page table?', 'It maps virtual page numbers to physical frame numbers', 'It stores the contents of every page', 'It schedules processes for the CPU', 'It allocates space on the disk', 'A', 'The page table holds one entry per virtual page, recording which frame (if any) each page currently maps to.', 'BEGINNER', 1, 'MCQ', 1),
(2856, 81, 'What does the abbreviation MMU stand for?', 'Main Memory Utility', 'Memory Management Unit', 'Multiple Memory Unit', 'Modular Memory Update', 'B', 'The MMU is the hardware component that translates virtual addresses to physical addresses during every memory reference.', 'BEGINNER', 1, 'MCQ', 1),
(2857, 81, 'Which of the following is an example of secondary storage?', 'RAM', 'CPU register', 'hard disk', 'L2 cache', 'C', 'A hard disk is secondary storage, which is slower and larger than primary memory and is used to back the virtual address space.', 'BEGINNER', 1, 'MCQ', 1),
(2858, 81, 'What does demand paging mean?', 'All pages are loaded when a process starts', 'Pages are prefetched in large batches', 'Pages are never loaded from disk', 'Pages are loaded only when they are first referenced', 'D', 'Demand paging brings a page into memory only when it is actually referenced, reducing initial load time and memory use.', 'BEGINNER', 1, 'MCQ', 1),
(2859, 81, 'What is a typical page size in modern operating systems?', '4 kilobytes', '4 bytes', '4 megabytes', '512 bytes', 'A', 'Most modern systems use a page size of 4 KB, although larger sizes such as 2 MB are also available for huge pages.', 'BEGINNER', 1, 'MCQ', 1),
(2860, 81, 'What happens during a TLB miss?', 'The page table is consulted to obtain the correct address translation', 'The CPU stops permanently', 'The entire disk is scanned', 'The process is terminated', 'A', 'On a TLB miss the MMU must walk the page table to find the mapping, because the needed translation was not found in the cache.', 'BEGINNER', 1, 'MCQ', 1),
(2861, 81, 'A system uses 4 KB pages and a logical address of 12292. Which page number does this address belong to?', '2', '3', '1', '4', 'B', 'Dividing 12292 by the 4096-byte page size gives 3 pages, with the remainder 4 being the offset within page 3.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2862, 81, 'A page table maps page 2 to frame 7. With 4 KB pages, what is the physical address for a virtual address of 2 pages plus offset 100?', '28868', '28676', '28772', '29204', 'C', 'The physical address is the frame number times the page size plus the offset, so 7 * 4096 + 100 = 28772.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2863, 81, 'Three page frames hold pages 1, 2, 3 initially. Reference order is 4, 2, 3, 1. How many page faults occur with FIFO replacement?', '3', '4', '2', '5', 'D', 'Page 4 faults and evicts page 1, pages 2 and 3 are already present, then page 1 faults and evicts page 2, giving 2 faults.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2864, 81, 'Three frames contain pages 1, 2, 3 and references arrive as 1, 3, 2, 4. Using LRU replacement, which page is evicted when page 4 arrives?', 'page 1', 'page 3', 'page 2', 'page 4', 'A', 'After referencing 1, 3 and 2, page 1 has the oldest access time, so LRU evicts page 1 when page 4 arrives.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2865, 81, 'A system has 8 KB pages. How many bits are needed to represent the offset within a page?', '10', '13', '12', '8', 'B', 'An 8 KB page holds 8192 bytes and 8192 = 2^13, so 13 bits are required for the offset.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2866, 81, 'Memory access takes 100 ns and a page fault takes 8 ms. If the page fault rate is 0.1 percent, what is the approximate effective access time?', '100 ns', '8000 ns', '8100 ns', '900 ns', 'C', 'Effective access time is 0.999 * 100 ns plus 0.001 * 8000000 ns, which is roughly 8100 ns.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2867, 81, 'Which page replacement algorithm suffers from Belady''s anomaly, where more frames can cause more faults?', 'LRU', 'Optimal', 'Clock', 'FIFO', 'D', 'FIFO is known to exhibit Belady''s anomaly, where increasing the number of frames can increase the number of page faults.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2868, 81, 'A process has a virtual address space of 4 GB and uses 4 KB pages. How many page table entries does its address space require?', '1,048,576', '1024', '4,194,304', '262,144', 'A', '4 GB divided by 4 KB equals 1,048,576 pages, so that many page table entries are needed for the full address space.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2869, 81, 'What does the valid-invalid bit in a page table entry indicate?', 'whether the page is executable', 'whether the page is present in physical memory', 'whether the page is shared', 'whether the page is clean', 'B', 'The valid-invalid bit tells whether the entry maps to a real frame; a cleared bit causes a page fault on access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2870, 81, 'Why are multi-level page tables used for large address spaces?', 'to speed up memory access', 'to make pages smaller', 'to avoid allocating the full page table when most of the address space is unused', 'to store page contents in the table', 'C', 'Multi-level tables are sparse, so only the portions of the hierarchy actually needed are allocated, saving a great deal of memory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2871, 81, 'A TLB has a hit ratio of 99 percent, TLB lookup costs 2 ns and memory access costs 100 ns. What is the effective address translation time?', '4 ns', '2 ns', '3 ns', '100 ns', 'C', 'The effective time is 0.99 * 2 ns plus 0.01 * 102 ns, which equals about 3 ns.', 'ADVANCED', 3, 'MCQ', 1),
(2872, 81, 'Which mechanism does a fork system call commonly use to avoid copying the entire parent address space?', 'eager copying', 'memory compaction', 'swap prefetching', 'copy-on-write', 'D', 'Copy-on-write lets the child and parent share pages and copies a page only when one of them tries to write to it.', 'ADVANCED', 3, 'MCQ', 1),
(2873, 81, 'The working set model of a process is the set of pages it currently needs. What does tracking the working set enable an OS to do?', 'decide how many frames to allocate to avoid thrashing', 'shrink the page size', 'eliminate the TLB', 'remove the need for swapping', 'A', 'If the working set of all processes exceeds physical memory, the OS knows thrashing will occur and can suspend a process.', 'ADVANCED', 3, 'MCQ', 1),
(2874, 81, 'What is the main benefit of using large (huge) pages on modern systems?', 'smaller physical memory frames', 'fewer TLB misses for large contiguous memory regions', 'faster page fault handling', 'reduced swap space usage', 'B', 'Huge pages let a single TLB entry cover a much larger region, dramatically cutting TLB misses for big workloads.', 'ADVANCED', 3, 'MCQ', 1),
(2875, 81, 'What is a memory-mapped file?', 'a file stored entirely in RAM', 'a file that can only be read once', 'a file whose contents are mapped into a process virtual address space so reads and writes use normal memory instructions', 'a compressed image of a disk', 'C', 'Memory-mapped files allow a file to be accessed through the virtual memory system, so paging handles moving data to and from the disk.', 'ADVANCED', 3, 'MCQ', 1),
(2876, 81, 'Which page replacement algorithm uses a reference bit plus a second chance hand to approximate LRU cheaply?', 'Optimal', 'FIFO with no bits', 'Second-in-first-out', 'clock algorithm', 'D', 'The clock algorithm walks the frames in a circular list and uses the reference bit to give pages a second chance before eviction.', 'ADVANCED', 3, 'MCQ', 1),
(2877, 81, 'What is the key advantage of a reverse (inverted) page table?', 'it needs only one entry per physical frame, so its size scales with physical memory instead of virtual address space', 'it stores pages in reverse order on disk', 'it eliminates page faults', 'it speeds up disk writes', 'A', 'An inverted page table has one entry per frame, keeping it compact even for huge virtual address spaces, at the cost of slower lookup.', 'ADVANCED', 3, 'MCQ', 1),
(2878, 81, 'Why must the TLB be flushed when switching between processes that do not share an address space?', 'the TLB would overflow', 'stale mappings from the previous process would translate the new process''s virtual addresses incorrectly', 'the new process needs more frames', 'the MMU would be powered off', 'B', 'Because TLB entries map to the previous process''s frames, they must be invalidated so the new process does not reuse wrong translations.', 'ADVANCED', 3, 'MCQ', 1),
(2879, 81, 'Which situation makes demand paging most beneficial?', 'a program that touches every page immediately', 'a program with no disk access', 'a program that uses only a small fraction of its address space during a run', 'a program that fits entirely in the cache', 'C', 'Demand paging shines when much of a program''s address space is rarely touched, so only the used pages are ever brought in.', 'ADVANCED', 3, 'MCQ', 1),
(2880, 81, 'Which of the following is a reason to use swap space that is separate from regular file storage?', 'swap space holds user documents', 'swap space backs up the hard disk', 'swap space removes the need for RAM', 'swap files can be allocated as raw blocks with no file system overhead, giving faster paging', 'D', 'Raw swap partitions or preallocated swap files avoid file system metadata overhead, making page-out and page-in faster.', 'ADVANCED', 3, 'MCQ', 1),
(2881, 82, 'What is a segment in segmentation-based memory management?', 'a variable-sized logical unit of a program such as code, data or stack', 'a fixed-size block of memory', 'a physical disk partition', 'a type of cache line', 'A', 'Segmentation divides a program into variable-sized logical units that correspond to natural parts like functions, data or the stack.', 'BEGINNER', 1, 'MCQ', 1),
(2882, 82, 'A logical address in a segmented system consists of which two parts?', 'page number and frame', 'segment number and offset', 'base and limit register', 'track and sector', 'B', 'A segmented logical address is a pair containing a segment selector and an offset within that segment.', 'BEGINNER', 1, 'MCQ', 1),
(2883, 82, 'What does a segment table entry primarily contain?', 'the contents of the segment', 'the disk block number', 'the base address and limit of the segment', 'the process priority', 'C', 'Each segment table entry stores the starting (base) address of the segment in memory and its length (limit).', 'BEGINNER', 1, 'MCQ', 1),
(2884, 82, 'What is the purpose of the segment limit field?', 'to record the segment name', 'to store the segment contents', 'to count page faults', 'to detect when an offset exceeds the segment size, preventing illegal access', 'D', 'The limit defines the maximum valid offset; an offset beyond it causes a trap, preventing access outside the segment.', 'BEGINNER', 1, 'MCQ', 1),
(2885, 82, 'Which memory management scheme allocates memory in variable-sized chunks and suffers from external fragmentation?', 'segmentation', 'paging', 'caching', 'segmented paging', 'A', 'Because segments have variable sizes, holes of odd sizes accumulate between them, causing external fragmentation.', 'BEGINNER', 1, 'MCQ', 1),
(2886, 82, 'Which field in a segment descriptor restricts what operations a process may perform on a segment?', 'base address', 'protection bits', 'limit', 'segment number', 'B', 'Protection bits such as read, write and execute permissions control what access is allowed to the segment.', 'BEGINNER', 1, 'MCQ', 1),
(2887, 82, 'What does the base address of a segment represent?', 'the end of the segment', 'the segment number', 'the starting physical address where the segment is placed in memory', 'the size of the segment', 'C', 'The base address is the physical location where the segment begins, and the offset is added to it to form a physical address.', 'BEGINNER', 1, 'MCQ', 1),
(2888, 82, 'In an x86 system, which table holds descriptors that describe the segments visible to a process?', 'the page table', 'the file allocation table', 'the interrupt vector table', 'the Global Descriptor Table or Local Descriptor Table', 'D', 'Segments are described by descriptors stored in the GDT (global) and LDT (local per-process) tables.', 'BEGINNER', 1, 'MCQ', 1),
(2889, 82, 'Which statement about segments is true?', 'segments can be different sizes and represent logical program units', 'all segments must be the same size', 'segments are stored on the stack', 'segments never share memory', 'A', 'Segments are variable-sized and correspond to logical units, which is the defining idea of segmentation.', 'BEGINNER', 1, 'MCQ', 1),
(2890, 82, 'What is external fragmentation?', 'memory wasted inside pages', 'memory wasted because the leftover free spaces are too small and scattered to be useful', 'memory used by the kernel', 'memory lost during a reboot', 'B', 'External fragmentation occurs when many small non-contiguous holes exist, none large enough to satisfy a request even though total free memory is sufficient.', 'BEGINNER', 1, 'MCQ', 1),
(2891, 82, 'A segment has a base of 8000 and a limit of 500. An access to offset 200 is requested. What is the resulting physical address?', '8500', '8200', '7800', '8000', 'B', 'The offset 200 is within the limit of 500, so the physical address is base 8000 plus offset 200, which is 8200.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2892, 82, 'A segment has a base of 4000 and a limit of 300. What happens when an access with offset 400 is attempted?', 'the access proceeds normally', 'the segment grows automatically', 'a trap is raised because the offset exceeds the limit', 'the offset is truncated to 300', 'C', 'Since 400 exceeds the limit of 300, the hardware raises a protection trap (segment fault) rather than allowing the access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2893, 82, 'Which property of segmentation makes it easier than paging to share code libraries between processes?', 'segments are fixed size', 'segments are copied on write', 'segments are always private', 'segments are logical units that can be shared at segment granularity with protection', 'D', 'Code segments can be shared whole with read-only protection, whereas paging shares at a coarser and less meaningful page granularity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2894, 82, 'A segment table maps segment 1 to base 5000 with limit 2000. What is the physical address for logical address (1, 1500)?', '6500', '5000', '3500', '8000', 'A', 'Offset 1500 is within the limit of 2000, so the address is base 5000 plus 1500, which equals 6500.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2895, 82, 'Which scheme combines the protection and sharing of segmentation with the non-fragmented memory allocation of paging?', 'pure segmentation', 'segmented paging', 'pure paging', 'contiguous allocation', 'B', 'Segmented paging divides segments into pages, so segment-level sharing is kept while memory is allocated in fixed-size pages.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2896, 82, 'Which kind of fragmentation is segmentation vulnerable to?', 'internal fragmentation', 'TLB fragmentation', 'external fragmentation', 'frame fragmentation', 'C', 'Variable-size segments create scattered holes, i.e. external fragmentation, rather than wasted space inside fixed blocks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2897, 82, 'Two processes want to share the same read-only code. In a segmented system, what is the cleanest way to support this?', 'copy the code into each process', 'store the code on the swap disk', 'allocate the code on the stack', 'map both segment tables to the same base and limit with read-only protection', 'D', 'Pointing both processes'' segment table entries at the same physical base with read-only protection gives safe shared code.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2898, 82, 'A stack segment grows downward from its limit toward its base. What happens to the offset compared with the limit as the stack grows?', 'the offset decreases while the limit stays fixed', 'the offset increases past the limit', 'the base changes', 'the segment disappears', 'A', 'For a growing-downward segment, the hardware compares the offset to the limit and traps when the offset crosses it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2899, 82, 'In segmented paging, what does the segment table entry hold?', 'the physical contents of the segment', 'the base address and length of the page table for that segment', 'the disk block of the segment', 'the segment name', 'B', 'Each segment in segmented paging points to its own page table, described by a base and length in the segment table.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2900, 82, 'Which component performs the base-plus-offset check and raises a trap on violation in a segmented system?', 'the file system', 'the scheduler', 'the memory management unit (MMU)', 'the device controller', 'C', 'The MMU compares the offset against the limit and traps if the offset is out of range, giving hardware protection.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2901, 82, 'Which design combines segmentation''s logical view with paging''s physical allocation while adding only modest hardware complexity?', 'pure segmentation', 'pure paging', 'segmented paging where segments are divided into pages', 'relocation registers only', 'C', 'Segmented paging keeps segment-level sharing and protection while allocating memory in fixed pages, avoiding external fragmentation.', 'ADVANCED', 3, 'MCQ', 1),
(2902, 82, 'Which protection configuration is appropriate for a shared read-only code segment?', 'write permission only', 'read and execute permission, no write permission', 'no permissions', 'read, write and execute', 'B', 'Read and execute without write prevents any process from corrupting the shared code while still allowing it to run.', 'ADVANCED', 3, 'MCQ', 1),
(2903, 82, 'How can an OS eliminate external fragmentation in a pure segmentation system?', 'compaction by moving segments together during idle time', 'increasing the page size', 'disabling the MMU', 'using only the stack segment', 'A', 'Compaction relocates segments so all free space is contiguous, but it is costly because segments must be moved and bases updated.', 'ADVANCED', 3, 'MCQ', 1),
(2904, 82, 'Why does a flat memory model simplify system software compared with a segmented model?', 'segments are larger', 'the TLB is not needed', 'compilation is impossible in segmented models', 'all addresses refer to a single linear address space, removing the need to manage segment boundaries', 'D', 'A flat model treats the whole address space as one linear range, so compilers and linkers do not have to manage segment relocation.', 'ADVANCED', 3, 'MCQ', 1),
(2905, 82, 'In x86 protected mode, what do privilege levels (rings) in segment descriptors control?', 'which operations and resources code running at that level may access', 'the segment''s size', 'the disk block used', 'the process priority', 'A', 'The 2-bit privilege field gives four rings; higher rings protect the OS from less privileged application code.', 'ADVANCED', 3, 'MCQ', 1),
(2906, 82, 'Which statement best describes why segmented addressing fell out of favor in most general-purpose OSes?', 'segments cannot be shared', 'paging with protection provides similar benefits with fixed-size allocation and simpler management', 'segments are too large', 'the hardware does not support segments', 'B', 'Pure segmentation''s variable sizes cause external fragmentation, while paging achieves protection and sharing with far simpler management.', 'ADVANCED', 3, 'MCQ', 1),
(2907, 82, 'For a process that reserves a huge virtual address space but touches little of it, which scheme is more memory-efficient?', 'pure segmentation', 'contiguous allocation', 'paging with sparse multi-level page tables', 'fixed partitions', 'C', 'Sparse paging only allocates the page table levels that are actually used, so a large but mostly empty address space costs little memory.', 'ADVANCED', 3, 'MCQ', 1),
(2908, 82, 'Which hardware feature is minimally required for a system to implement segmentation protection?', 'a second CPU core', 'a large cache', 'a hardware interrupt timer', 'registers or table entries holding base and limit that the MMU checks on every access', 'D', 'Base and limit values plus hardware checks allow every memory access to be validated against the segment bounds.', 'ADVANCED', 3, 'MCQ', 1),
(2909, 82, 'Two processes share a segment, then one writes to it. If the segment descriptor only allows read access, what occurs?', 'the write traps with a protection fault', 'the write silently succeeds', 'the segment is duplicated', 'the process is paused', 'A', 'The read-only protection bit causes the hardware to raise a protection fault on the attempted write, preventing corruption.', 'ADVANCED', 3, 'MCQ', 1),
(2910, 82, 'What is the main trade-off of using an LDT per process in addition to the GDT?', 'it doubles the RAM size', 'it isolates each process''s segment descriptors, but adds context-switch and lookup overhead', 'it removes the need for paging', 'it makes segments unwritable', 'B', 'An LDT gives each process its own descriptor table for isolation, but must be loaded and validated on every context switch.', 'ADVANCED', 3, 'MCQ', 1),
(2911, 83, 'What is a file in an operating system?', 'a named collection of related data stored on secondary storage', 'a running program', 'a hardware device', 'a segment of memory', 'A', 'A file is a named, addressable collection of data that the OS stores persistently on secondary storage.', 'BEGINNER', 1, 'MCQ', 1),
(2912, 83, 'What is a directory in a file system?', 'a type of memory', 'a structure that organizes and names files', 'a disk sector', 'a hardware cache', 'B', 'A directory maps file names to their file metadata, giving the file system a hierarchical naming structure.', 'BEGINNER', 1, 'MCQ', 1),
(2913, 83, 'What is file metadata?', 'the data contained in the file', 'the name of the disk', 'information about a file such as size, owner and timestamps', 'a copy of the file', 'C', 'Metadata describes the file itself, including its size, owner, permissions and creation and modification times.', 'BEGINNER', 1, 'MCQ', 1),
(2914, 83, 'What is the root directory in a hierarchical file system?', 'the first file created on a disk', 'a directory that holds deleted files', 'a hidden system file', 'the top-level directory from which all paths begin', 'D', 'The root is the highest-level directory, and every absolute path starts from it.', 'BEGINNER', 1, 'MCQ', 1),
(2915, 83, 'What is an absolute path?', 'a path that begins at the root directory', 'a path relative to the current directory', 'a path that never changes', 'a path containing no directories', 'A', 'An absolute path starts from the root directory and identifies a file unambiguously regardless of the current directory.', 'BEGINNER', 1, 'MCQ', 1),
(2916, 83, 'What is a relative path?', 'a path from the root directory', 'a path interpreted from the current working directory', 'a path that cannot fail', 'a path on a different disk', 'B', 'A relative path locates a file by starting from the current working directory rather than the root.', 'BEGINNER', 1, 'MCQ', 1),
(2917, 83, 'Which system call is used to remove a file from the file system?', 'write', 'mount', 'unlink', 'sync', 'C', 'The unlink call removes a file''s directory entry and, when the last link is gone, frees its blocks.', 'BEGINNER', 1, 'MCQ', 1),
(2918, 83, 'What does a file name extension such as .txt typically indicate?', 'the file''s size', 'the disk the file is stored on', 'the owner of the file', 'the type or intended format of the file contents', 'D', 'Extensions are a convention used to hint at a file''s format, although the OS itself may not rely on them.', 'BEGINNER', 1, 'MCQ', 1),
(2919, 83, 'What is a file system?', 'A set of structures and rules that organizes how files are named, stored and retrieved on a storage device', 'A physical hard disk', 'A type of memory', 'A program that edits files', 'A', 'A file system imposes naming and layout rules so the operating system can persistently store, locate and manage files.', 'BEGINNER', 1, 'MCQ', 1),
(2920, 83, 'What does a directory entry mainly contain?', 'the complete file contents', 'a file name and a reference to the file''s metadata', 'the file''s permissions only', 'a backup of the file', 'B', 'A directory entry binds a name to an inode or similar metadata record, not to the file''s data itself.', 'BEGINNER', 1, 'MCQ', 1),
(2921, 83, 'In an inode-based file system, which of the following is stored in the inode?', 'the full file contents', 'the file''s size and pointers to its data blocks', 'the directory listing', 'the file name', 'B', 'The inode holds metadata such as size and block pointers, while the file name lives in a directory entry.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2922, 83, 'Which allocation method suffers from external fragmentation and requires files to be placed in contiguous runs?', 'linked allocation', 'contiguous allocation', 'indexed allocation', 'extent allocation', 'C', 'Contiguous allocation needs a single continuous run of blocks per file, leaving scattered holes and requiring compaction.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2923, 83, 'What is the main drawback of linked (chained) allocation for files?', 'it wastes disk space', 'it cannot share files', 'it corrupts metadata', 'random access is slow because blocks must be followed one by one', 'D', 'In linked allocation, reaching block n requires walking the pointers from the start, so random access is inefficient.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2924, 83, 'What is the primary advantage of indexed allocation?', 'it supports fast random access without external fragmentation', 'it needs no disk space for indexes', 'it cannot grow files', 'it stores all data contiguously', 'A', 'An index block holds all the file''s block pointers, so any block can be located directly while blocks can be scattered freely.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2925, 83, 'What does the File Allocation Table (FAT) store for a FAT file system?', 'the contents of each file', 'the next block in the chain for every block on the disk', 'the file names', 'the user passwords', 'B', 'FAT keeps a per-block entry that points to the next block in a file''s chain, so there is no scattered pointer per block.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2926, 83, 'Two hard links to the same file share what property?', 'the same file name', 'the same creation time only', 'the same inode number', 'the same directory', 'C', 'Hard links are additional directory entries pointing to the same inode, so they share the inode number and data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2927, 83, 'If the target of a symbolic link is deleted, what happens to the symbolic link?', 'it is updated automatically', 'it keeps a copy of the data', 'it becomes a hard link', 'it becomes a dangling link that no longer resolves', 'D', 'A symbolic link stores the target''s path, so when the target is removed the link still exists but cannot be followed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2928, 83, 'Which structure is commonly used to track free blocks so new blocks can be found quickly?', 'a bitmap or free list', 'the root directory', 'the superblock copy', 'the journal', 'A', 'A bitmap marks each block as free or used, allowing the allocator to locate free blocks in constant search time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2929, 83, 'Which allocation method provides fast random access and eliminates external fragmentation while using one extra block per file?', 'contiguous allocation', 'indexed allocation', 'linked allocation', 'none of these', 'B', 'Indexed allocation puts all block pointers in an index block, enabling direct access to any block with no fragmentation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2930, 83, 'In a typical Unix-like file system, what does a directory actually contain?', 'the data of every file', 'a copy of the disk bitmap', 'name-to-inode mappings for the files in it', 'the free block list', 'C', 'Directories store pairs of file names and inode numbers, while all data and metadata live elsewhere.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2931, 83, 'What is the purpose of journaling in a file system?', 'to compress file contents', 'to encrypt the disk', 'to keep the file system consistent by logging metadata updates before they are applied', 'to speed up disk reads', 'C', 'A journal records pending metadata changes so that after a crash the file system can replay or discard them and remain consistent.', 'ADVANCED', 3, 'MCQ', 1),
(2932, 83, 'Which of these is a journaling file system?', 'FAT32', 'ISO 9660', 'UDF', 'ext4', 'D', 'ext4 is a journaling file system, whereas FAT32 has no journal and relies on scandisk-style repair.', 'ADVANCED', 3, 'MCQ', 1),
(2933, 83, 'Why do log-structured file systems perform well for many small writes?', 'writes are batched into large sequential segments instead of scattered small updates', 'they never write to disk', 'they use a smaller block size', 'they keep data only in RAM', 'A', 'Log-structured designs accumulate writes into large contiguous segments, turning many random small I/Os into efficient sequential ones.', 'ADVANCED', 3, 'MCQ', 1),
(2934, 83, 'What does a copy-on-write file system such as ZFS or Btrfs gain from never overwriting live data in place?', 'a smaller disk footprint', 'cheap snapshots and crash safety because old versions of blocks remain intact', 'faster random reads', 'no need for a directory', 'B', 'Since blocks are written to new locations, prior versions remain valid, enabling snapshots and robust recovery after crashes.', 'ADVANCED', 3, 'MCQ', 1),
(2935, 83, 'After an unclean shutdown, what is the purpose of a file system check (fsck)?', 'to delete user files', 'to defragment the disk', 'to detect and repair inconsistencies in metadata such as block counts and links', 'to reset user passwords', 'C', 'fsck scans metadata structures and fixes inconsistencies like lost blocks or wrong link counts left by a crash.', 'ADVANCED', 3, 'MCQ', 1),
(2936, 83, 'What is an extent in modern file systems like ext4?', 'a single 4 KB block', 'a directory entry', 'a disk partition', 'a contiguous run of blocks allocated as a unit and recorded with just start and length', 'D', 'An extent records a starting block and its length, so large contiguous allocations need only one entry instead of many.', 'ADVANCED', 3, 'MCQ', 1),
(2937, 83, 'Why do flash-based file systems and log-structured designs favor large sequential writes?', 'flash erases in large blocks, so sequential writes reduce write amplification and wear', 'flash reads are slow', 'flash cannot be overwritten', 'flash stores data on tape', 'A', 'Because erasing flash happens in large units, aligning writes into large sequential segments minimizes erase overhead and wear.', 'ADVANCED', 3, 'MCQ', 1),
(2938, 83, 'What does the FUSE framework allow a developer to do?', 'overclock the CPU', 'implement a custom file system in user space without modifying the kernel', 'encrypt the disk permanently', 'replace the boot loader', 'B', 'FUSE exports file system calls to a user-space daemon, letting custom file systems run as ordinary processes.', 'ADVANCED', 3, 'MCQ', 1),
(2939, 83, 'Which file system feature is most important for avoiding long fsck times on very large disks?', 'a larger block size', 'a bigger directory cache', 'journaling so only recent updates need replaying after a crash', 'more disk partitions', 'C', 'With a journal, recovery after a crash only replays a bounded log of recent updates instead of scanning the whole disk.', 'ADVANCED', 3, 'MCQ', 1),
(2940, 83, 'For an SSD, why is it beneficial to leave free space in a partition?', 'the disk becomes faster with age', 'it improves read speed', 'it creates larger files', 'the controller needs spare blocks for garbage collection and wear leveling', 'D', 'Free (over-provisioned) blocks give the flash controller room to relocate data during garbage collection without stalling writes.', 'ADVANCED', 3, 'MCQ', 1),
(2941, 84, 'What is a track on a magnetic hard disk?', 'a concentric ring of sectors on a platter surface', 'a single sector', 'a group of platters', 'a cache line', 'A', 'A track is one circular ring of recorded data on a platter, subdivided into sectors.', 'BEGINNER', 1, 'MCQ', 1),
(2942, 84, 'What is seek time?', 'the time to transfer a sector', 'the time to move the read-write head to the required track', 'the time the disk spins', 'the time to power on the disk', 'B', 'Seek time is the time spent positioning the disk arm at the cylinder holding the desired track.', 'BEGINNER', 1, 'MCQ', 1),
(2943, 84, 'What is rotational latency?', 'the time to move the arm', 'the time to format the disk', 'the time for the disk to rotate so the desired sector reaches the head', 'the time to boot the system', 'C', 'Rotational latency is the delay while the platter rotates until the requested sector arrives under the head.', 'BEGINNER', 1, 'MCQ', 1),
(2944, 84, 'What is a sector on a disk?', 'a whole platter', 'a cache block', 'a cylinder', 'the smallest addressable unit of storage on a disk', 'D', 'A sector is the fixed-size, smallest addressable unit of a disk, traditionally 512 bytes.', 'BEGINNER', 1, 'MCQ', 1),
(2945, 84, 'What does FCFS stand for in disk scheduling?', 'First Come, First Served', 'Fastest Cylinder First Served', 'First Cylinder, First Seek', 'Full Cycle First Serve', 'A', 'FCFS serves requests in the exact order they arrive, without reordering to reduce head movement.', 'BEGINNER', 1, 'MCQ', 1),
(2946, 84, 'What is the disk arm?', 'the motor that spins the platters', 'the mechanical assembly that moves the read-write heads across the platters', 'the disk controller chip', 'a cache buffer', 'B', 'The disk arm carries the read-write heads and moves radially to position them over the requested track.', 'BEGINNER', 1, 'MCQ', 1),
(2947, 84, 'What is a cylinder on a hard disk?', 'a single sector', 'the whole disk', 'the set of tracks at the same radial position across all platters', 'a cache line', 'C', 'A cylinder consists of all tracks with the same radius on every platter, so the arm reaches them together.', 'BEGINNER', 1, 'MCQ', 1),
(2948, 84, 'What does transfer time measure?', 'the time to move the arm', 'the time between requests', 'the disk spin-up time', 'the time to read or write the actual data once the head is positioned', 'D', 'Transfer time is how long it takes to move the data between the disk surface and the host once positioned.', 'BEGINNER', 1, 'MCQ', 1),
(2949, 84, 'What is average access time for a disk made up of?', 'average seek time plus average rotational latency plus transfer time', 'only the transfer time', 'only the seek time', 'the power-up time', 'A', 'Access time is the total of seek, rotational latency and transfer, and its average is reported as the disk''s access time.', 'BEGINNER', 1, 'MCQ', 1),
(2950, 84, 'Which disk scheduling algorithm serves requests strictly in the order they arrive?', 'SSTF', 'FCFS', 'SCAN', 'C-SCAN', 'B', 'FCFS is the simplest scheduler, processing requests in arrival order with no reordering.', 'BEGINNER', 1, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(2951, 84, 'Requests arrive for tracks 30, 70, 10, 50 and the head starts at 40. In which order does SSTF serve them?', '10, 30, 50, 70', '30, 50, 10, 70', '30, 10, 70, 50', '50, 70, 30, 10', 'B', 'From 40 the nearest is 30, then 50, then 10, then 70, so SSTF picks 30, 50, 10, 70.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2952, 84, 'Requests at tracks 55, 20, 90 and the head starts at 50 moving upward. In what order does SCAN serve them?', '20, 55, 90', '55, 20, 90', '55, 90, 20', '90, 55, 20', 'C', 'SCAN keeps moving in one direction until it reaches the end, serving 55 then 90 on the way up, then reverses and serves 20.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2953, 84, 'With C-SCAN the head starts at 50 moving upward toward track 200 and requests are 55, 20, 90. What is the service order?', '20, 55, 90', '90, 55, 20', '55, 20, 90', '55, 90, 20', 'D', 'C-SCAN sweeps to the outermost track, serving 55 then 90, then jumps back to the innermost track and serves 20.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2954, 84, 'With LOOK, the head starts at 50 moving upward and requests are 20, 90, 55. What is the service order?', '55, 90, 20', '20, 55, 90', '90, 55, 20', '55, 20, 90', 'A', 'LOOK reverses at the last request in the direction rather than at the end of the disk, so it serves 55 and 90 upward, then 20.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2955, 84, 'The head starts at track 30 and FCFS requests arrive as 50, 20, 70. What is the total head movement?', '120', '100', '90', '70', 'B', 'The head moves 30 to 50 (20), back to 20 (30), then to 70 (50), totaling 20 + 30 + 50 = 100.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2956, 84, 'Which disk scheduling algorithm can cause starvation of requests that are far from the head?', 'FCFS', 'C-SCAN', 'SSTF', 'LOOK', 'C', 'SSTF always picks the nearest request, so distant requests may wait forever while closer ones keep arriving.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2957, 84, 'A disk spins at 6000 RPM. What is the average rotational latency in milliseconds?', '10 ms', '2 ms', '1 ms', '5 ms', 'D', 'One full rotation takes 60 / 6000 = 10 ms, and average rotational latency is half a rotation, so 5 ms.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2958, 84, 'Which of the following best describes SCAN (elevator) disk scheduling?', 'the head moves back and forth across the disk serving requests along the way', 'requests are served in arrival order', 'the head serves the nearest request first', 'the head never changes direction', 'A', 'SCAN sweeps the arm from one end of the disk to the other and back, servicing all requests encountered on each pass.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2959, 84, 'With C-LOOK the head starts at 40 moving upward and requests are 30, 90, 60. What is the service order?', '30, 60, 90', '60, 90, 30', '90, 60, 30', '30, 90, 60', 'B', 'Moving upward it serves 60 then 90, then wraps directly to the lowest outstanding request 30, giving 60, 90, 30.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2960, 84, 'The head is at track 10 and must serve tracks 20, 50, 100 with SCAN moving upward. What is the total seek distance?', '120', '140', '90', '160', 'C', 'Moving upward SCAN serves 20, 50 and 100, covering (20-10) + (50-20) + (100-50) = 10 + 30 + 50 = 90 tracks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2961, 84, 'Which disk scheduling policy gives the most uniform waiting time to all pending requests?', 'SSTF', 'FCFS', 'C-SCAN', 'none of these', 'C', 'C-SCAN treats all cylinders equally on each sweep and resets after the high end, so wait times are far more uniform than SSTF or FCFS.', 'ADVANCED', 3, 'MCQ', 1),
(2962, 84, 'The head is at track 40 moving upward toward 200; requests are 60, 20, 180. What is the total movement for C-SCAN up to track 200 and back to track 0?', '440', '300', '360', '380', 'D', 'C-SCAN moves from 40 up to 200 (160), then jumps from 200 back to 0 (200), then serves 20 (20), for a total of 160 + 200 + 20 = 380.', 'ADVANCED', 3, 'MCQ', 1),
(2963, 84, 'Why do modern SSDs usually not need classical seek-optimizing schedulers like SCAN?', 'SSDs have no moving head and access any block in similar time', 'SSDs are slower at seek', 'SSD controllers never reorder', 'SSDs store data on magnetic platters', 'A', 'Without mechanical seek, access time is nearly uniform, so reordering for head movement is unnecessary; wear-leveling and write scheduling matter instead.', 'ADVANCED', 3, 'MCQ', 1),
(2964, 84, 'What is the purpose of Native Command Queuing (NCQ) in modern storage?', 'to prevent the drive from overheating', 'to let the drive reorder and pipeline queued commands to improve performance', 'to reduce disk capacity', 'to encrypt all data', 'B', 'NCQ allows the drive to reorder outstanding commands and pipeline transfers, maximizing utilization and reducing overall latency.', 'ADVANCED', 3, 'MCQ', 1),
(2965, 84, 'What does the Linux deadline I/O scheduler guarantee to each request?', 'the shortest possible seek', 'zero latency', 'a bounded service deadline, so no request is starved indefinitely', 'a fixed queue depth', 'C', 'Deadline keeps both read and write queues with expiration times, guaranteeing starvation-free service while still reordering for throughput.', 'ADVANCED', 3, 'MCQ', 1),
(2966, 84, 'What is the main idea of anticipatory scheduling?', 'the scheduler never waits', 'the scheduler only serves writes', 'the scheduler favors far cylinders', 'the scheduler briefly pauses after a read in expectation of a nearby next request from the same process', 'D', 'Anticipatory scheduling inserts a short idle wait after a read to catch the process''s next nearby request, improving locality.', 'ADVANCED', 3, 'MCQ', 1),
(2967, 84, 'Which term is another name for the SCAN disk scheduling algorithm?', 'elevator algorithm', 'round robin', 'shortest job first', 'priority queue', 'A', 'SCAN behaves like an elevator moving up and down, so it is commonly called the elevator algorithm.', 'ADVANCED', 3, 'MCQ', 1),
(2968, 84, 'For a workload mixing a few urgent reads with many bulk writes, which scheduler property is most desirable?', 'always maximizing seek distance', 'strict priority for reads to bound their latency', 'never reordering requests', 'serving all writes before reads', 'B', 'Reads block the requesting process, so schedulers like deadline prioritize reads while still batching writes efficiently.', 'ADVANCED', 3, 'MCQ', 1),
(2969, 84, 'How does the flash translation layer (FTL) change how scheduling and addressing work on an SSD?', 'the FTL removes the need for a file system', 'the FTL makes access times vary with cylinder', 'the FTL maps logical blocks to physical pages internally, so the OS sees a normal block device', 'the FTL ignores wear leveling', 'C', 'The FTL hides flash''s erase/write constraints by mapping logical addresses to physical pages and performing garbage collection.', 'ADVANCED', 3, 'MCQ', 1),
(2970, 84, 'In which workload is plain FCFS disk scheduling actually a reasonable choice?', 'a heavily loaded database', 'a continuous video recorder writing at full speed', 'a system with constant request queues', 'a light, low-utilization system where seeking overhead is small and fairness matters', 'D', 'When the disk is lightly loaded and queues rarely build, FCFS provides simple fairness without meaningful performance loss.', 'ADVANCED', 3, 'MCQ', 1),
(2971, 85, 'What is an I/O device?', 'Hardware such as a keyboard, monitor or disk that exchanges data with the computer', 'A type of CPU instruction', 'A software library', 'A memory cell', 'A', 'An I/O device is hardware that transfers data between the computer and the outside world, such as input, output or storage peripherals.', 'BEGINNER', 1, 'MCQ', 1),
(2972, 85, 'What is an input/output port?', 'A dedicated address used by the CPU to communicate with a device', 'A type of memory module', 'A file on the hard disk', 'A scheduling algorithm', 'A', 'An I/O port is a special address the CPU uses to exchange data and control signals with a specific device.', 'BEGINNER', 1, 'MCQ', 1),
(2973, 85, 'What is polling in device communication?', 'the device sends an interrupt', 'the CPU transfers data in a burst', 'the CPU repeatedly checks a device status register until it signals readiness', 'the device ignores the CPU', 'C', 'Polling has the CPU actively check a device''s status register in a loop until the device reports it is ready.', 'BEGINNER', 1, 'MCQ', 1),
(2974, 85, 'What is programmed I/O (PIO)?', 'the device transfers data alone', 'the DMA controller copies memory', 'the CPU sleeps during I/O', 'the CPU transfers each piece of data to or from the device by executing instructions', 'D', 'In PIO the CPU is fully responsible for moving every byte or word between memory and the device.', 'BEGINNER', 1, 'MCQ', 1),
(2975, 85, 'Which component transfers data between memory and devices without using the CPU for each byte?', 'the DMA controller', 'the ALU', 'the scheduler', 'the file system', 'A', 'The DMA controller moves data directly between a device and memory, interrupting the CPU only when done.', 'BEGINNER', 1, 'MCQ', 1),
(2976, 85, 'What is a device controller?', 'a software program for users', 'hardware that manages the operation of a device and exchanges data with the CPU', 'a type of memory', 'a file system driver only', 'B', 'A device controller is hardware between the CPU and the device that handles low-level operation and status.', 'BEGINNER', 1, 'MCQ', 1),
(2977, 85, 'What is an interrupt service routine (ISR)?', 'a device driver install script', 'a type of system call', 'the code the OS runs to handle a particular interrupt', 'a DMA transfer', 'C', 'An ISR is the handler function invoked by the OS when the matching interrupt is delivered.', 'BEGINNER', 1, 'MCQ', 1),
(2978, 85, 'What is a peripheral device?', 'A device such as a printer, keyboard or scanner that attaches to the computer', 'The main CPU', 'The power supply', 'A software program', 'A', 'A peripheral device is external hardware attached to the computer that provides input, output or auxiliary storage.', 'BEGINNER', 1, 'MCQ', 1),
(2979, 85, 'What is the main purpose of a buffer between a device and the CPU?', 'to hold data temporarily so the CPU and device can work at different speeds', 'to make the device faster', 'to increase memory size', 'to compress data', 'A', 'Buffers smooth the speed mismatch between fast CPUs and slower devices by staging data temporarily.', 'BEGINNER', 1, 'MCQ', 1),
(2980, 85, 'What is a bus in a computer system?', 'a type of disk', 'a shared communication path that transfers data between components', 'a memory cell', 'a scheduling algorithm', 'B', 'A bus is the shared electrical and protocol pathway used to move data between the CPU, memory and devices.', 'BEGINNER', 1, 'MCQ', 1),
(2981, 85, 'Which technique is best for transferring large blocks of data such as a disk read, to keep the CPU free?', 'programmed I/O', 'DMA', 'polling', 'interrupt-driven byte transfer', 'B', 'DMA moves entire blocks with minimal CPU work, making it ideal for bulk transfers like disk reads.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2982, 85, 'What does an interrupt vector contain?', 'the data being transferred', 'the device status', 'the address of the interrupt handler for a given interrupt number', 'the DMA channel number', 'C', 'An interrupt vector table maps each interrupt number to the address of its corresponding ISR.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2983, 85, 'What is cycle stealing in the context of DMA?', 'the CPU steals data from the device', 'the DMA controller crashes the system', 'the device refuses transfers', 'the DMA controller borrows bus cycles from the CPU one at a time to transfer data', 'D', 'Cycle stealing lets DMA transfer a word using a bus cycle now and then, slightly slowing the CPU but avoiding large block transfers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2984, 85, 'What is interrupt latency?', 'The delay between an interrupt request and the CPU beginning to execute its handler', 'The time a device spends transferring data', 'The speed of the memory bus', 'The number of devices on a system', 'A', 'Interrupt latency measures the time from when an interrupt is raised until the CPU saves state and starts running the corresponding handler.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2985, 85, 'What is spooling used for in a print system?', 'printing without a printer', 'queuing output to a disk file so the printer and applications run at their own speeds', 'compressing documents', 'encrypting print jobs', 'B', 'Spooling writes jobs to a queue on disk so the slow printer can drain the queue while applications continue.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2986, 85, 'What does double buffering achieve?', 'two copies of all data', 'slower processing', 'one buffer fills while the other is processed, overlapping I/O and computation', 'less memory usage', 'C', 'With two buffers the producer fills one while the consumer processes the other, hiding transfer latency.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2987, 85, 'Which I/O model returns control to the calling process immediately even though the operation is not finished?', 'blocking I/O', 'synchronous I/O', 'spooled I/O', 'non-blocking I/O', 'D', 'Non-blocking I/O lets a process issue the request and continue, checking later for completion.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2988, 85, 'For reading a 4 MB file from disk into memory, which transfer method is most efficient?', 'DMA with a single interrupt at completion', 'byte-by-byte programmed I/O', 'continuous polling', 'interrupt per byte', 'A', 'DMA handles the whole block and interrupts once when done, whereas per-byte interrupt or PIO would consume enormous CPU time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2989, 85, 'What handshake must occur before a DMA controller can move data?', 'the CPU stops permanently', 'the controller requests and is granted the bus, then transfers and signals completion', 'the device writes a file', 'the kernel is rebooted', 'B', 'The DMA controller requests the bus, gains ownership, transfers the data, then interrupts the CPU when finished.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2990, 85, 'For a device that produces data only rarely, which method wastes the least CPU time while waiting?', 'busy-wait polling', 'continuous polling', 'interrupt-driven I/O', 'polling every nanosecond', 'C', 'Interrupts let the CPU do useful work until the device signals, avoiding the waste of constant polling.', 'INTERMEDIATE', 2, 'MCQ', 1),
(2991, 85, 'What cache coherency problem can DMA introduce?', 'DMA deletes cache lines', 'DMA corrupts the cache tags', 'the CPU''s cache may hold stale data if DMA writes to memory behind its back', 'cache makes DMA slower', 'C', 'If the CPU caches a location that DMA updates in main memory, the cache can become stale unless it is invalidated.', 'ADVANCED', 3, 'MCQ', 1),
(2992, 85, 'What is scatter-gather DMA?', 'DMA that copies files', 'DMA that uses no memory', 'a single contiguous transfer', 'a DMA transfer that reads or writes a list of non-contiguous memory regions with one request', 'D', 'Scatter-gather DMA uses a descriptor list of addresses and lengths, letting one transfer span many scattered buffers.', 'ADVANCED', 3, 'MCQ', 1),
(2993, 85, 'What is the purpose of interrupt coalescing in high-speed networking?', 'it batches interrupts so the CPU is not overwhelmed by millions of interrupts per second', 'it delays all interrupts forever', 'it increases interrupt frequency', 'it disables the NIC', 'A', 'Under heavy load, coalescing groups many completed packets into a few interrupts, drastically cutting CPU overhead.', 'ADVANCED', 3, 'MCQ', 1),
(2994, 85, 'What does a zero-copy I/O path achieve?', 'no data is ever copied', 'data is transferred between kernel buffers and the network without redundant copying through user space', 'the CPU is bypassed entirely', 'memory is compressed', 'B', 'Zero-copy lets DMA move data directly between devices or kernel buffers, avoiding extra copies through user space.', 'ADVANCED', 3, 'MCQ', 1),
(2995, 85, 'Why does the kernel typically buffer small writes before sending them to a device?', 'buffers delete the data', 'buffering compresses files', 'batching small writes reduces per-request overhead and lets the device handle larger efficient transfers', 'the kernel must delay all writes', 'C', 'Aggregating small writes into larger ones cuts the fixed cost per I/O and improves device efficiency.', 'ADVANCED', 3, 'MCQ', 1),
(2996, 85, 'What is the benefit of mmap-based file I/O over explicit read and write calls?', 'it requires no memory', 'it is always faster', 'it cannot fail', 'pages are paged in on demand and the kernel manages the transfer automatically', 'D', 'With mmap, the virtual memory system fetches and writes pages lazily, removing explicit system calls and copies.', 'ADVANCED', 3, 'MCQ', 1),
(2997, 85, 'Why do NVMe SSDs outperform SATA SSDs by a wide margin?', 'NVMe uses PCIe with many high-speed queues and low latency, unlike SATA''s older narrower bus', 'NVMe has more mechanical parts', 'SATA is encrypted', 'NVMe is larger', 'A', 'NVMe exploits PCIe lanes with thousands of deep queues and lower latency, far exceeding the single-queue SATA interface.', 'ADVANCED', 3, 'MCQ', 1),
(2998, 85, 'What does IRQ affinity (pinning an interrupt to a specific CPU) achieve in a multicore system?', 'it disables the interrupt', 'it keeps the interrupt handler and the data it touches on the same CPU, improving cache locality and reducing contention', 'it spreads the kernel across all CPUs', 'it slows the device', 'B', 'Pinning an IRQ to a CPU lets its handler reuse warm caches and avoids the cost of bouncing interrupts between cores.', 'ADVANCED', 3, 'MCQ', 1),
(2999, 85, 'What is the trade-off of using direct (unbuffered) I/O with the O_DIRECT flag?', 'it is always faster', 'it encrypts data', 'it bypasses the page cache, avoiding double buffering but losing the benefit of caching and read-ahead', 'it disables DMA', 'C', 'O_DIRECT transfers straight to user buffers, avoiding cache copies, but forfeits kernel caching and prefetching that help many workloads.', 'ADVANCED', 3, 'MCQ', 1),
(3000, 85, 'In which condition does polling beat interrupts for a device?', 'when events are very rare', 'when the device is off', 'when the CPU is idle', 'when the device produces events at an extremely high rate and interrupt cost dominates', 'D', 'If events arrive so frequently that interrupt handling itself overwhelms the CPU, polling the device at fixed intervals is more efficient.', 'ADVANCED', 3, 'MCQ', 1),
(3001, 86, 'Which command prints the current working directory?', 'pwd', 'ls', 'cd', 'cat', 'A', 'pwd (print working directory) displays the absolute path of the directory you are currently in.', 'BEGINNER', 1, 'MCQ', 1),
(3002, 86, 'Which command lists the files and directories in the current directory?', 'ls', 'cp', 'mv', 'mkdir', 'B', 'The ls command lists the contents of a directory, showing files and subdirectories.', 'BEGINNER', 1, 'MCQ', 1),
(3003, 86, 'Which command creates a new directory?', 'rmdir', 'rm', 'mkdir', 'touch', 'C', 'mkdir creates a new directory, and the -p option lets you create nested paths at once.', 'BEGINNER', 1, 'MCQ', 1),
(3004, 86, 'Which command is used to copy files or directories?', 'mv', 'cp', 'rm', 'ln', 'D', 'cp copies a source file or directory to a destination, leaving the original in place.', 'BEGINNER', 1, 'MCQ', 1),
(3005, 86, 'Which command moves or renames a file?', 'mv', 'cp', 'find', 'grep', 'A', 'mv both moves a file to a new location and renames it by giving a new name in the same directory.', 'BEGINNER', 1, 'MCQ', 1),
(3006, 86, 'Which command permanently deletes a file?', 'cat', 'rm', 'touch', 'cp', 'B', 'rm removes files, or directories with -r, and the data is not placed in a trash folder.', 'BEGINNER', 1, 'MCQ', 1),
(3007, 86, 'Which command opens the online manual page for another command?', 'help', 'man', 'whatis', 'apropos', 'C', 'man displays the manual pages that describe a command''s options and usage.', 'BEGINNER', 1, 'MCQ', 1),
(3008, 86, 'Which command displays the contents of a file on the terminal?', 'mkdir', 'rm', 'grep', 'cat', 'D', 'cat writes the full contents of a file to standard output.', 'BEGINNER', 1, 'MCQ', 1),
(3009, 86, 'Which command searches for matching lines of text inside files?', 'grep', 'find', 'sort', 'sed', 'A', 'grep scans files for lines that match a given pattern and prints the lines that match.', 'BEGINNER', 1, 'MCQ', 1),
(3010, 86, 'Which command changes the current working directory?', 'ls', 'cd', 'pwd', 'mv', 'B', 'cd changes the shell''s working directory to the specified path.', 'BEGINNER', 1, 'MCQ', 1),
(3011, 86, 'What additional information does ls -l show for each file?', 'permissions, owner, group, size and modification time', 'only the file size', 'the full file contents', 'the file checksum', 'A', 'The long listing format displays metadata such as permissions, owner, group, size and modification time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3012, 86, 'Which command finds files by name or other attributes inside a directory tree?', 'grep', 'find', 'diff', 'which', 'B', 'find walks a directory tree and matches files by name, type, size and other criteria.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3013, 86, 'What does the command rm -r do?', 'removes an empty directory', 'removes a file without confirmation', 'removes directories and their contents recursively', 'renames a directory', 'C', 'The -r option makes rm delete a directory together with everything inside it, recursively.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3014, 86, 'Which command prints only the first 10 lines of a file?', 'tail', 'sed', 'wc', 'head', 'D', 'head outputs the beginning of a file, 10 lines by default.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3015, 86, 'Which command prints only the last 10 lines of a file?', 'tail', 'head', 'more', 'less', 'A', 'tail outputs the end of a file, and the -f option makes it follow a growing file such as a log.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3016, 86, 'What does the pipe symbol | do between two commands?', 'runs them at exactly the same time', 'sends the output of the first command as input to the second', 'compares their outputs', 'joins their arguments into one list', 'B', 'A pipe connects the standard output of one command to the standard input of the next.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3017, 86, 'Which command counts lines, words and characters in a file?', 'sort', 'uniq', 'wc', 'awk', 'C', 'wc (word count) reports the number of lines, words and bytes in its input.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3018, 86, 'Which command shows how much disk space each file or directory uses?', 'df', 'free', 'du', 'mount', 'D', 'du reports the disk usage of files and directories, whereas df shows space on whole filesystems.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3019, 86, 'Which command creates an empty file or updates the timestamp of an existing one?', 'touch', 'mkdir', 'newfile', 'create', 'A', 'touch creates a new empty file if it does not exist, or updates the access and modification times.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3020, 86, 'Which command sorts the lines of text in a file into order?', 'grep', 'sort', 'uniq', 'cut', 'B', 'sort orders lines alphabetically or numerically, and uniq then removes adjacent duplicates.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3021, 86, 'Which command lists every regular file larger than 100 megabytes under /var/log?', 'find /var/log -type f -size +100M', 'ls -R /var/log | grep 100M', 'du -h /var/log', 'locate /var/log 100M', 'A', 'find with -type f and -size +100M locates regular files over 100 MB anywhere in the tree.', 'ADVANCED', 3, 'MCQ', 1),
(3022, 86, 'What is the difference between > and >> when redirecting output?', '> overwrites the file while >> appends to it', '> appends while >> overwrites', '> redirects errors while >> redirects normal output', 'they behave identically', 'B', 'The > operator truncates the file and writes fresh output, whereas >> adds to the existing contents.', 'ADVANCED', 3, 'MCQ', 1),
(3023, 86, 'Which command prints all current environment variables and their values?', 'alias', 'set-only', 'env', 'export-all', 'C', 'env, like printenv, lists every environment variable with its value in the current session.', 'ADVANCED', 3, 'MCQ', 1),
(3024, 86, 'What happens when a command is followed by an ampersand & ?', 'it waits for completion before returning to the prompt', 'it runs the command in the background and returns to the prompt immediately', 'it cancels the command', 'it repeats the command', 'D', 'A trailing & starts the command as a background job, so the shell returns to the prompt right away.', 'ADVANCED', 3, 'MCQ', 1),
(3025, 86, 'How do you substitute the output of a command into another command''s arguments?', 'wrap it in $(command)', 'prefix it with a dollar sign like $command', 'pipe it to echo', 'use a here-document', 'A', 'Command substitution with $(command) runs the command and places its output into the surrounding line.', 'ADVANCED', 3, 'MCQ', 1),
(3026, 86, 'Which command identifies the actual type of a file regardless of its extension?', 'type', 'file', 'stat-name', 'info', 'B', 'file inspects the content''s magic bytes and reports whether it is text, an image, an archive and so on.', 'ADVANCED', 3, 'MCQ', 1),
(3027, 86, 'Which shell feature lets you recall and re-run commands you typed earlier?', 'alias', 'auto-complete', 'history', 'prompt', 'C', 'The history mechanism stores prior commands so you can view and re-run them without retyping.', 'ADVANCED', 3, 'MCQ', 1),
(3028, 86, 'How do you copy an entire directory tree while preserving permissions and timestamps?', 'cp --links', 'cp -R -l', 'cp -r only', 'cp -r -p', 'D', 'cp -r -p recursively copies while preserving mode, ownership and timestamps, and cp -a does even more.', 'ADVANCED', 3, 'MCQ', 1),
(3029, 86, 'Which redirection directs both standard output and standard error into the same file?', 'cmd > file 2>&1', 'cmd 2> file', 'cmd < file 2>&1', 'cmd >> file 2<&1', 'A', 'The 2>&1 suffix makes file descriptor 2 follow descriptor 1, so stderr goes to the same file as stdout.', 'ADVANCED', 3, 'MCQ', 1),
(3030, 86, 'Which command shows the path of the executable a command name would run?', 'where', 'which', 'locate', 'type-builtin', 'B', 'which searches the PATH and prints the absolute path of the executable for a command name.', 'ADVANCED', 3, 'MCQ', 1),
(3031, 87, 'In an ls -l listing, what does the leading character d indicate?', 'a directory', 'a regular file', 'a symbolic link', 'a block device', 'A', 'The first character of the permission string shows the file type, and d stands for directory.', 'BEGINNER', 1, 'MCQ', 1),
(3032, 87, 'Which permission letter allows reading a file''s contents?', 'w', 'r', 'x', 's', 'B', 'The r (read) permission grants the ability to open and view the contents of a file.', 'BEGINNER', 1, 'MCQ', 1),
(3033, 87, 'Which permission letter allows modifying a file?', 'x', 'r', 'w', 't', 'C', 'The w (write) permission grants the ability to change or delete a file''s contents.', 'BEGINNER', 1, 'MCQ', 1),
(3034, 87, 'Which permission letter allows running a file as a program?', 'r', 'w', 'd', 'x', 'D', 'The x (execute) permission is required to run a file as a command or program.', 'BEGINNER', 1, 'MCQ', 1),
(3035, 87, 'Which command changes the permission bits of a file?', 'chmod', 'chown', 'chgrp', 'umask', 'A', 'chmod (change mode) modifies the read, write and execute permissions of a file or directory.', 'BEGINNER', 1, 'MCQ', 1),
(3036, 87, 'Which command changes the owner of a file?', 'chmod', 'chown', 'chgrp', 'chattr', 'B', 'chown (change owner) transfers ownership of a file to a specified user.', 'BEGINNER', 1, 'MCQ', 1),
(3037, 87, 'Which command changes the group associated with a file?', 'chown', 'chmod', 'chgrp', 'usermod', 'C', 'chgrp (change group) changes the group ownership of a file.', 'BEGINNER', 1, 'MCQ', 1),
(3038, 87, 'In numeric permissions, what value does read permission have?', '1', '2', '8', '4', 'D', 'Read maps to the numeric value 4 in the octal permission scheme.', 'BEGINNER', 1, 'MCQ', 1),
(3039, 87, 'In numeric permissions, what value does write permission have?', '2', '1', '4', '8', 'A', 'Write maps to the numeric value 2 in the octal permission scheme.', 'BEGINNER', 1, 'MCQ', 1),
(3040, 87, 'In numeric permissions, what value does execute permission have?', '4', '1', '2', '8', 'B', 'Execute maps to the numeric value 1 in the octal permission scheme.', 'BEGINNER', 1, 'MCQ', 1),
(3041, 87, 'What permissions result from chmod 755 on a regular file?', 'rwxr-xr-x', 'rw-r--r--', 'r-xr-x---', 'rwxrwxrwx', 'A', '755 sets rwx for the owner and r-x for the group and others.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3042, 87, 'What permissions result from chmod 644 on a regular file?', 'rwxr--r--', 'rw-r--r--', 'rw-rw-r--', 'r--r--r--', 'B', '644 sets rw- for the owner and r-- for group and others, typical for ordinary text files.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3043, 87, 'What does chmod u+x script.sh do?', 'adds execute permission for everyone', 'adds execute permission for the group', 'adds execute permission for the file owner', 'removes execute permission for the owner', 'C', 'The u target refers to the user (owner), and +x adds the execute bit for them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3044, 87, 'What does chmod o-w file do?', 'removes write for the owner', 'adds write for others', 'removes write for the group', 'removes write permission for others', 'D', 'The o target refers to others, and -w removes the write bit for them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3045, 87, 'What does chmod a+r file do?', 'adds read permission for everyone', 'adds read permission for the owner only', 'removes read for everyone', 'adds write for everyone', 'A', 'The a target stands for all users, so +r grants read to the user, the group and others.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3046, 87, 'In the permission string rwxr-xr--, which three classes are shown in order?', 'owner, group, others', 'root, admin, users', 'read, write, execute', 'primary, secondary, tertiary', 'B', 'The nine characters are three triples representing the user, group and others in that order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3047, 87, 'What does chown alice:dev file do?', 'changes only the group to alice', 'changes only the owner to dev', 'changes the owner to alice and the group to dev', 'removes ownership entirely', 'C', 'A user:group argument sets both the owner and the group in a single chown command.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3048, 87, 'What does chmod +x file do when no target letter is given?', 'adds execute for the owner only', 'adds execute for the group only', 'removes execute for everyone', 'adds execute for the user, group and others', 'D', 'Without a target letter the change applies to all classes, so +x grants execute to everyone.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3049, 87, 'What does the -R option do when used with chmod?', 'applies the change recursively through subdirectories', 'removes the file', 'runs read-only', 'reverts to default permissions', 'A', 'chmod -R recurses into subdirectories and applies the same permission change to everything inside.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3050, 87, 'Which numeric mode represents the permissions rw------- ?', '700', '600', '644', '640', 'B', '600 grants read and write only to the owner and nothing to the group or others.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3051, 87, 'What does the setuid bit do when set on an executable file?', 'runs the program with the file owner''s privileges', 'makes the file read-only', 'locks the file from deletion', 'hides the file from ls', 'A', 'The setuid bit makes the process run with the effective user ID of the file owner, as with /usr/bin/passwd.', 'ADVANCED', 3, 'MCQ', 1),
(3052, 87, 'With a typical umask of 022, what permissions are newly created directories given?', 'rw-r--r--', 'rwxr-xr-x', 'rwxrwxrwx', 'r--r--r--', 'B', 'umask 022 strips write from the group and others, so directories get rwxr-xr-x (755).', 'ADVANCED', 3, 'MCQ', 1),
(3053, 87, 'What is the effect of the sticky bit on a shared directory such as /tmp?', 'only root can read files there', 'all files inside are encrypted', 'a user can only delete files they own even when others can write the directory', 'files inside expire automatically', 'C', 'The sticky bit on a world-writable directory prevents users from deleting files owned by others.', 'ADVANCED', 3, 'MCQ', 1),
(3054, 87, 'What is the numeric value used to set the setuid bit, as in chmod 4755?', '1000', '2000', '6000', '4000', 'D', 'Setuid is encoded as 4000, so chmod 4755 combines the setuid bit with the normal 755 permissions.', 'ADVANCED', 3, 'MCQ', 1),
(3055, 87, 'Why does /etc/shadow normally have no read or write permission for normal users?', 'it stores hashed password data that must not be readable by ordinary users', 'it is a temporary cache', 'it contains only boot configuration', 'it must be kept empty for security', 'A', 'The shadow file holds password hashes, so restricting access prevents offline password cracking.', 'ADVANCED', 3, 'MCQ', 1),
(3056, 87, 'What happens when the setgid bit is set on a directory?', 'new files inherit the directory''s group instead of the creator''s', 'new files become world-writable', 'only the owner can create files', 'files are deleted automatically after use', 'B', 'With setgid on a directory, files created inside it belong to the directory''s group, which helps team directories.', 'ADVANCED', 3, 'MCQ', 1),
(3057, 87, 'What can a user do in a directory where they have only execute (x) permission?', 'list the directory contents', 'read every file inside', 'traverse into it if they know a filename, but not list its entries', 'delete files inside it', 'C', 'Execute-only on a directory allows entering it by name but blocks listing its entries.', 'ADVANCED', 3, 'MCQ', 1),
(3058, 87, 'Which command sets the default permission mask applied to every file a user creates?', 'chmod', 'chattr', 'chown', 'umask', 'D', 'umask sets the default permissions for new files by subtracting its bits from the base mode.', 'ADVANCED', 3, 'MCQ', 1),
(3059, 87, 'What does chattr +i config.conf do?', 'makes the file immutable so even the owner cannot modify or delete it', 'marks the file as index-only', 'adds interactive mode', 'sets read-only for others only', 'A', 'The immutable attribute prevents any modification, deletion or renaming until it is removed with chattr -i.', 'ADVANCED', 3, 'MCQ', 1),
(3060, 87, 'Why would an administrator use POSIX ACLs on a file instead of only chmod?', 'to compress the file', 'to grant different permissions to many named users and groups beyond owner/group/others', 'to speed up disk access', 'to hide the file from ls', 'B', 'ACLs extend the three-class model by assigning specific permissions to many named users and groups.', 'ADVANCED', 3, 'MCQ', 1),
(3061, 88, 'Which line at the top of a script tells the kernel to run it with the Bash interpreter?', '#!/bin/bash', '#include bash', '%bash', 'declare bash', 'A', 'The shebang #!/bin/bash instructs the kernel to execute the script using /bin/bash.', 'BEGINNER', 1, 'MCQ', 1),
(3062, 88, 'What must you do before you can run a script by name?', 'rename it to end in .sh', 'make it executable with chmod +x', 'compile it', 'move it to /tmp', 'B', 'chmod +x adds the execute bit so the kernel permits the file to be run directly.', 'BEGINNER', 1, 'MCQ', 1),
(3063, 88, 'What does a line beginning with # mean inside a shell script?', 'an error', 'a command to execute', 'a comment that is ignored by the shell', 'a variable declaration', 'C', 'Lines starting with # are comments and are ignored when the script runs.', 'BEGINNER', 1, 'MCQ', 1),
(3064, 88, 'Which of the following correctly declares a variable in Bash?', 'set x = 5', 'int x = 5', 'var x 5', 'x=5', 'D', 'A variable is assigned with name=value and no spaces around the equals sign.', 'BEGINNER', 1, 'MCQ', 1),
(3065, 88, 'How do you read the value of a variable named count inside a script?', 'echo $count', 'echo count', 'read count', 'print count', 'A', 'Prefixing the variable name with a dollar sign expands it to its current value.', 'BEGINNER', 1, 'MCQ', 1),
(3066, 88, 'Which builtin command prints text to the terminal?', 'print', 'echo', 'printf-only', 'output', 'B', 'echo writes its arguments to standard output, usually followed by a newline.', 'BEGINNER', 1, 'MCQ', 1),
(3067, 88, 'Which builtin command reads a line of input from the user into a variable?', 'input', 'get', 'read', 'scan', 'C', 'read captures a line from standard input and stores it in the named variable.', 'BEGINNER', 1, 'MCQ', 1),
(3068, 88, 'Which comparison operator inside a [ ] test checks whether two strings are equal?', '-eq', '-ne', '-f', '=', 'D', 'Within test brackets, = compares strings for equality, while -eq compares numbers.', 'BEGINNER', 1, 'MCQ', 1),
(3069, 88, 'Which loop repeats a block once for each item in a list such as 1 2 3?', 'for', 'while', 'until', 'repeat', 'A', 'A for loop iterates over each word in the given list, running its body for every item.', 'BEGINNER', 1, 'MCQ', 1),
(3070, 88, 'Which builtin ends a script immediately and returns a status code?', 'return', 'exit', 'stop', 'quit', 'B', 'exit terminates the script and passes its numeric argument back as the exit status.', 'BEGINNER', 1, 'MCQ', 1),
(3071, 88, 'Which special variable holds the exit status of the last executed command?', '$?', '$#', '$!', '$*', 'A', '$? expands to the exit code of the most recent command, with 0 usually meaning success.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3072, 88, 'Which special variable contains the number of positional parameters passed to a script?', '$@', '$#', '$?', '$$', 'B', '$# holds the count of command-line arguments passed to the script or function.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3073, 88, 'Which special variable refers to all of the positional parameters of a script?', '$0', '$@', '$!', '$?', 'C', '$@ expands to all positional parameters, each treated as a separately quoted argument.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3074, 88, 'How does $@ differ from $* when arguments contain spaces?', 'they are identical', '$* is invalid syntax', '$@ only counts arguments', '$@ preserves each argument separately while $* joins them into one string', 'D', '$@ keeps every argument distinct, whereas $* merges all arguments into a single word.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3075, 88, 'What does the construct $(ls) do inside a script?', 'runs ls and substitutes its output into the command line', 'lists files in the background', 'defines a function named ls', 'prints the variable ls', 'A', 'Command substitution executes the command and replaces the whole construct with its output.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3076, 88, 'Which loop keeps running as long as its condition remains true?', 'for', 'while', 'case', 'select', 'B', 'A while loop repeats its body while the test command exits successfully.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3077, 88, 'What effect does set -e at the top of a script have?', 'makes the script echo every command', 'disables comments', 'exits the script immediately if any command returns a non-zero status', 'ignores all arguments', 'C', 'set -e turns on errexit, so the script aborts on the first failing command instead of continuing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3078, 88, 'Which test option checks whether a given path is a regular file?', 'test -d', 'test -x', 'test -r', 'test -f', 'D', 'test -f returns true only when the argument exists and is a regular file, not a directory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3079, 88, 'Which test option checks whether a given path is a directory?', 'test -d', 'test -f', 'test -s', 'test -e', 'A', 'test -d succeeds only when the argument exists and is a directory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3080, 88, 'Which syntax correctly defines a function named greet in Bash?', 'function = greet()', 'greet() { echo hi; }', 'def greet:', 'greet => { }', 'B', 'A function is defined with the name, parentheses and a brace-delimited body, such as greet() { ... }.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3081, 88, 'What does a case statement do in a shell script?', 'matches a value against multiple patterns and runs the first matching branch', 'loops over a range of numbers', 'defines a new variable', 'sorts a list of arguments', 'A', 'case compares a word to several patterns and executes the statements of the first pattern that matches.', 'ADVANCED', 3, 'MCQ', 1),
(3082, 88, 'What does trap ''cleanup'' EXIT do in a script?', 'runs the cleanup command every second', 'runs cleanup whenever the script exits', 'prevents the script from exiting', 'renames the script', 'B', 'trap registers a handler that runs when the named signal or the EXIT event occurs.', 'ADVANCED', 3, 'MCQ', 1),
(3083, 88, 'How do you run a long command so it keeps running after the terminal session closes?', 'nohup command', 'fg command', 'kill -TERM command', 'background it with disown only', 'C', 'nohup ignores the hangup signal so the command survives the terminal closing.', 'ADVANCED', 3, 'MCQ', 1),
(3084, 88, 'What does the special variable $RANDOM provide in Bash?', 'the current process id', 'the last exit status', 'the number of arguments', 'a random integer between 0 and 32767', 'D', '$RANDOM expands to a pseudo-random integer in the range 0 through 32767.', 'ADVANCED', 3, 'MCQ', 1),
(3085, 88, 'What does exec replace the current shell process with a new command mean?', 'it is a syntax error', 'the shell is replaced by the given program and control never returns', 'the command runs in a subshell', 'input is read from a file', 'B', 'exec replaces the current shell process image with the specified program, so control never returns.', 'ADVANCED', 3, 'MCQ', 1),
(3086, 88, 'Which command marks an existing variable so it can no longer be changed?', 'export var', 'readonly var', 'declare -i var', 'local var', 'B', 'readonly makes a variable immutable, so any later attempt to assign it fails.', 'ADVANCED', 3, 'MCQ', 1),
(3087, 88, 'What does ${var:-default} expand to when var is unset or empty?', 'an error', 'nothing at all', 'the word default', 'the value of var regardless of whether it is set', 'C', 'The :- operator substitutes the fallback text only when the variable is unset or empty.', 'ADVANCED', 3, 'MCQ', 1),
(3088, 88, 'What does ${path##*/} produce from the path /home/user/report.txt ?', '/home/user', 'report.txt', '/home/user/report.txt', 'home', 'D', 'The ##*/ pattern strips the longest prefix ending in a slash, leaving only the final component.', 'ADVANCED', 3, 'MCQ', 1),
(3089, 88, 'Why is set -u recommended in robust scripts?', 'it makes the script fail when an unset variable is referenced', 'it uppercases all output', 'it prevents background jobs', 'it disables filename globbing', 'A', 'set -u (nounset) aborts the script if a referenced variable has not been defined, catching typos.', 'ADVANCED', 3, 'MCQ', 1),
(3090, 88, 'Which feature does the [[ ]] test offer that the single-bracket [ ] does not?', 'only numeric comparisons', 'regular-expression matching with =~ and && || operators', 'automatic backgrounding', 'variable assignment', 'B', 'The extended [[ ]] supports regex matching with =~ and boolean && and || logic.', 'ADVANCED', 3, 'MCQ', 1),
(3091, 89, 'Which command prints a snapshot of the currently running processes?', 'ps', 'ls', 'mkdir', 'du', 'A', 'ps reports the current processes and their PIDs, CPU and memory usage at the moment it runs.', 'BEGINNER', 1, 'MCQ', 1),
(3092, 89, 'What does PID stand for?', 'program installation date', 'process identifier', 'primary input device', 'physical interface driver', 'B', 'PID is the process identifier, a unique number assigned to each running process.', 'BEGINNER', 1, 'MCQ', 1),
(3093, 89, 'Which command shows processes updating continuously in real time?', 'ps', 'cat', 'top', 'tree', 'C', 'top refreshes its process display every few seconds so you can watch activity as it changes.', 'BEGINNER', 1, 'MCQ', 1),
(3094, 89, 'Which command sends a signal to a process using its PID?', 'kill', 'chmod', 'mv', 'echo', 'D', 'kill delivers a signal, by default SIGTERM, to the process identified by its PID.', 'BEGINNER', 1, 'MCQ', 1),
(3095, 89, 'Which signal forcefully kills a process and cannot be caught or ignored?', 'SIGKILL (9)', 'SIGTERM (15)', 'SIGHUP (1)', 'SIGINT (2)', 'A', 'SIGKILL is handled directly by the kernel and terminates the process immediately without cleanup.', 'BEGINNER', 1, 'MCQ', 1),
(3096, 89, 'Which signal requests a process to terminate gracefully so it can clean up?', 'SIGKILL', 'SIGTERM', 'SIGCHLD', 'SIGSTOP', 'B', 'SIGTERM asks the process to exit cleanly so it can close files and release resources.', 'BEGINNER', 1, 'MCQ', 1),
(3097, 89, 'What does appending & to a command do?', 'runs it in the foreground', 'deletes it', 'runs it as a background job', 'locks it', 'C', 'A trailing ampersand launches the command in the background, freeing the terminal for other work.', 'BEGINNER', 1, 'MCQ', 1),
(3098, 89, 'Which builtin lists the background jobs of the current shell?', 'jobs', 'list', 'ps bg', 'tasks', 'D', 'jobs shows the running and suspended background jobs belonging to the current shell session.', 'BEGINNER', 1, 'MCQ', 1),
(3099, 89, 'What is a daemon process?', 'a background service that runs without user interaction', 'a computer virus', 'an error log file', 'a temporary cache file', 'A', 'Daemons are long-lived background processes that provide services such as web serving or logging.', 'BEGINNER', 1, 'MCQ', 1),
(3100, 89, 'Which process is normally the first started at boot and becomes the parent of all other processes?', 'bash', 'systemd (or init)', 'cron', 'login', 'B', 'On modern Linux systems systemd is PID 1, the ancestor of all other processes.', 'BEGINNER', 1, 'MCQ', 1),
(3101, 89, 'What does kill -9 1234 do?', 'sends SIGKILL to PID 1234, terminating it immediately', 'pauses PID 1234', 'renames PID 1234', 'prints PID 1234', 'A', 'The -9 option sends SIGKILL, which force-terminates the process without giving it a chance to clean up.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3102, 89, 'What does ps aux display?', 'only the current user''s foreground jobs', 'all processes from all users with detailed columns', 'only systemd services', 'a live updating screen', 'B', 'With the a, u and x options, ps shows every user''s processes in a detailed format including CPU and memory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3103, 89, 'How does SIGTERM differ from SIGKILL?', 'SIGTERM is uncatchable', 'they are identical', 'SIGTERM allows cleanup while SIGKILL forces immediate termination', 'SIGKILL pauses the process', 'C', 'SIGTERM can be caught so a program can save state, whereas SIGKILL ends the process at once.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3104, 89, 'What does the command kill %2 do?', 'kills the process with PID 2', 'sends a signal to job number 2', 'lists job 2', 'reloads job 2', 'D', 'The %n form refers to the nth job of the shell, so kill %2 signals that job.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3105, 89, 'What does kill -STOP 1234 do?', 'pauses the process while keeping its memory intact', 'deletes the process', 'restarts the process', 'changes its priority', 'A', 'SIGSTOP suspends execution of the process, which can later be resumed with SIGCONT.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3106, 89, 'What does jobs -l show that plain jobs does not?', 'the exit statuses', 'the PID of each background job', 'the command history', 'the memory usage', 'B', 'jobs -l adds the process IDs to the usual job listings.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3107, 89, 'What does the builtin fg do?', 'forgets a job', 'sends a job to the background', 'brings a background job into the foreground', 'terminates a job', 'C', 'fg resumes a suspended or background job so it runs interactively in the foreground.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3108, 89, 'What is a zombie process?', 'a process that is running slowly', 'a process that cannot be killed', 'a process that has terminated but whose parent has not yet collected its exit status', 'a process waiting for input', 'D', 'A zombie is a finished process whose entry stays in the process table until its parent calls wait() to reap it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3109, 89, 'What does the nice command do?', 'starts a program with an adjusted CPU priority', 'polishes the terminal output', 'cleans up zombie processes', 'counts processes', 'A', 'nice launches a process with a lower priority (higher niceness) so it yields the CPU to others.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3110, 89, 'What does renice do?', 'deletes a running process', 'changes the priority of a process that is already running', 'renames a process', 'restarts a process', 'B', 'renice adjusts the niceness of a running process, and lowering it requires appropriate privileges.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3111, 89, 'In top output, what does the load average indicate?', 'the average number of processes ready to run or waiting to run over 1, 5 and 15 minutes', 'the total memory in megabytes', 'the number of zombies', 'the disk input rate', 'A', 'Load average counts runnable and uninterruptible processes, averaged over one, five and fifteen minutes.', 'ADVANCED', 3, 'MCQ', 1),
(3112, 89, 'What does sending SIGHUP (kill -HUP) to a daemon commonly achieve?', 'forces it to crash', 'tells it to reload its configuration and keep running', 'reboots the machine', 'logs the current user out', 'B', 'Many daemons treat SIGHUP as a request to reread configuration files and reopen log files.', 'ADVANCED', 3, 'MCQ', 1),
(3113, 89, 'What is a process group in Linux?', 'a group of processes all sharing one priority', 'a collection of processes that can be signaled together, such as a pipeline', 'a set of systemd unit files', 'a list of daemons', 'C', 'A process group lets the kernel and the shell send signals to every member at once, as a pipeline does.', 'ADVANCED', 3, 'MCQ', 1),
(3114, 89, 'Which command finds the PID of a process purely by its name?', 'ps find', 'pgrep', 'pid', 'top -n', 'D', 'pgrep searches the process table and prints the PIDs of processes matching the given name.', 'ADVANCED', 3, 'MCQ', 1),
(3115, 89, 'What does ps -ef provide?', 'a full listing of every process including its parent PID and command line', 'a live refresh of processes', 'only foreground jobs', 'a process tree for one user', 'A', 'The -e and -f options show every process with a detailed column set including PPID and the full command.', 'ADVANCED', 3, 'MCQ', 1),
(3116, 89, 'A script launches several jobs with & and then runs wait. What does wait do?', 'terminates all the jobs', 'blocks until all background jobs finish before continuing', 'pauses the script forever', 'prints the job numbers', 'B', 'wait pauses the script until every launched background job has completed, collecting their exit statuses.', 'ADVANCED', 3, 'MCQ', 1),
(3117, 89, 'What is a fork bomb?', 'a script that restarts itself slowly', 'a process that repeatedly forks copies of itself until the system runs out of processes', 'a program that fills the disk with files', 'a network attack on port 22', 'C', 'A fork bomb rapidly creates child processes, exhausting the process table and making the system unusable.', 'ADVANCED', 3, 'MCQ', 1),
(3118, 89, 'What does htop provide that plain top does not?', 'load average only', 'a smaller process list', 'interactive scrolling, a tree view and mouse support', 'no color output', 'D', 'htop offers an interactive scrollable display, a hierarchical tree view, colors and mouse interaction.', 'ADVANCED', 3, 'MCQ', 1),
(3119, 89, 'What is SIGCHLD used for?', 'notifying a parent when one of its children has stopped or terminated', 'shutting down the machine', 'resuming a paused process', 'suspending a child', 'A', 'The kernel sends SIGCHLD to a parent when a child changes state so the parent can call wait() and reap it.', 'ADVANCED', 3, 'MCQ', 1),
(3120, 89, 'Which command shows the current status of a service managed by systemd?', 'systemctl status service', 'service --info', 'init status', 'ps service', 'B', 'systemctl status service reports whether the unit is active, its main PID and its recent logs.', 'ADVANCED', 3, 'MCQ', 1),
(3121, 90, 'Which command tests whether a remote host is reachable by sending ICMP echo packets?', 'ping', 'cat', 'ls', 'mkdir', 'A', 'ping sends ICMP echo requests and reports whether replies come back and how fast.', 'BEGINNER', 1, 'MCQ', 1),
(3122, 90, 'Which command displays the IP addresses assigned to the machine''s network interfaces?', 'ip addr', 'ls ip', 'chmod', 'hostname', 'B', 'ip addr, like ifconfig, lists each interface and the IPv4 and IPv6 addresses configured on it.', 'BEGINNER', 1, 'MCQ', 1),
(3123, 90, 'Which command downloads a file from the web using the HTTP protocol?', 'cp', 'mv', 'wget', 'tar', 'C', 'wget retrieves remote files over HTTP, HTTPS or FTP and saves them locally.', 'BEGINNER', 1, 'MCQ', 1),
(3124, 90, 'Which command shows the system''s IP routing table?', 'ip route', 'echo', 'lsmod', 'uptime', 'D', 'ip route, like the older route command, lists the network routes the kernel uses to forward packets.', 'BEGINNER', 1, 'MCQ', 1),
(3125, 90, 'Which command resolves a hostname into an IP address using DNS?', 'nslookup', 'ping only', 'ip addr', 'hostname', 'A', 'nslookup queries a DNS server to translate a domain name into its address records.', 'BEGINNER', 1, 'MCQ', 1),
(3126, 90, 'Which package manager is used by Debian and Ubuntu systems?', 'dnf', 'apt', 'pacman', 'zypper', 'B', 'apt (Advanced Package Tool) is the package manager used on Debian-derived distributions.', 'BEGINNER', 1, 'MCQ', 1),
(3127, 90, 'Which package manager is the default on modern Fedora and RHEL systems?', 'apt', 'dpkg', 'dnf', 'rpm-only', 'C', 'dnf is the default package manager on recent Fedora and RHEL releases, replacing yum.', 'BEGINNER', 1, 'MCQ', 1),
(3128, 90, 'Which command installs a new package such as curl on a Debian-based system?', 'apt install curl', 'pip install curl', 'dnf install curl', 'tar curl', 'D', 'apt install resolves dependencies and installs the named package from the configured repositories.', 'BEGINNER', 1, 'MCQ', 1),
(3129, 90, 'Which command refreshes the list of available packages and their versions?', 'apt update', 'apt upgrade', 'apt install', 'apt remove', 'A', 'apt update downloads the latest package index so apt knows which versions are available.', 'BEGINNER', 1, 'MCQ', 1),
(3130, 90, 'Which command upgrades all currently installed packages on a Debian system?', 'apt update', 'apt upgrade', 'apt search', 'apt list', 'B', 'apt upgrade installs newer versions of the installed packages using the refreshed index.', 'BEGINNER', 1, 'MCQ', 1),
(3131, 90, 'What does apt upgrade do compared with apt update?', 'installs newer versions of installed packages, while update only refreshes the index', 'is identical to update', 'removes old packages', 'reinstalls every package', 'A', 'apt update refreshes the package index, and apt upgrade then applies the available upgrades to installed packages.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3132, 90, 'What does ping -c 4 8.8.8.8 do?', 'pings forever', 'sends exactly four ICMP requests and then stops', 'sends four bytes of data', 'pings four packets per second', 'B', 'The -c option limits the number of echo requests, so ping stops after the four replies.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3133, 90, 'What does curl -O https://example.com/file.zip do?', 'prints headers only', 'uploads file.zip', 'downloads the file and saves it with its remote filename', 'opens an interactive shell', 'C', 'curl -O downloads the URL and writes it to a local file named after the remote file.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3134, 90, 'What does the command ip a summarize?', 'DNS settings', 'the routing table', 'active network sockets', 'all network interfaces and their addresses', 'D', 'ip a is shorthand for ip address and shows each interface with its configured addresses and state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3135, 90, 'What does ss -t list?', 'only TCP sockets', 'only UDP sockets', 'only DNS records', 'only routed interfaces', 'A', 'ss -t filters its socket listing to TCP connections.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3136, 90, 'What does apt remove do to an installed package?', 'deletes it and all its configuration files', 'removes it but keeps its configuration files', 'only disables it', 'downgrades it', 'B', 'apt remove uninstalls the package''s binaries while preserving its configuration files.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3137, 90, 'What does apt purge do that apt remove does not?', 'removes dependent packages', 'also deletes the package''s configuration files', 'keeps the log files', 'reinstalls the package', 'C', 'apt purge removes the package and additionally deletes its configuration files from the system.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3138, 90, 'What does wget -c do when a download is interrupted?', 'cancels the file', 'restarts from scratch', 'resumes the download from where it stopped', 'deletes the partial file', 'D', 'The -c (continue) option makes wget resume a partial download from the point where it stopped.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3139, 90, 'Which command queries the DNS records for a domain such as example.com?', 'nslookup example.com', 'ip example.com', 'route example.com', 'ping example.com', 'A', 'nslookup sends DNS queries and prints the returned address or MX records for the name.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3140, 90, 'Which command shows the ports a machine is currently listening on?', 'ss -l', 'ip -p', 'ls /dev', 'ping -l', 'B', 'ss -l, like netstat -l, lists sockets in the listening state, showing open ports and their services.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3141, 90, 'What does apt-get dist-upgrade do beyond a regular upgrade?', 'also installs or removes packages to satisfy changed dependencies', 'downgrades every package', 'only updates the kernel', 'removes all unused packages', 'A', 'dist-upgrade handles dependency changes intelligently, installing and removing packages as needed.', 'ADVANCED', 3, 'MCQ', 1),
(3142, 90, 'What is a package repository?', 'a local backup directory', 'a server or collection that provides packages and metadata for the package manager', 'a directory of system logs', 'a firewall rule', 'B', 'Repositories publish packages and index metadata so tools like apt can discover, download and update software.', 'ADVANCED', 3, 'MCQ', 1),
(3143, 90, 'What does dpkg -i package.deb do?', 'removes a package', 'searches for a package', 'installs a package directly from a .deb file without dependency resolution', 'downgrades a package', 'C', 'dpkg -i installs the given .deb file at the low level, applying dependencies only if they are already present.', 'ADVANCED', 3, 'MCQ', 1),
(3144, 90, 'What does rpm -ivh package.rpm do?', 'removes an rpm', 'queries an rpm', 'upgrades all rpms', 'installs the rpm with verbose and hash progress output', 'D', 'rpm -ivh installs the package verbosely with progress hashes, short for install verbose hash.', 'ADVANCED', 3, 'MCQ', 1),
(3145, 90, 'What does SSH local port forwarding achieve?', 'tunnels traffic from a local port through the SSH connection to a remote destination', 'blocks local ports', 'shares files between machines', 'copies SSH keys', 'A', 'Local forwarding binds a port on the local machine and relays its traffic through the encrypted SSH tunnel.', 'ADVANCED', 3, 'MCQ', 1),
(3146, 90, 'What is the purpose of the file /etc/resolv.conf?', 'to list network interfaces', 'to configure the DNS resolver with name servers and search domains', 'to set the hostname', 'to store firewall rules', 'B', 'resolv.conf tells the resolver which nameservers to query and which search domains to append.', 'ADVANCED', 3, 'MCQ', 1),
(3147, 90, 'What does the iptables tool manage?', 'DNS resolution', 'package downloads', 'the kernel''s firewall rules and packet filtering', 'process priorities', 'C', 'iptables configures the netfilter tables that filter, forward and translate packets in the kernel.', 'ADVANCED', 3, 'MCQ', 1),
(3148, 90, 'What does ss -tnlp display?', 'DNS servers', 'routing entries', 'ARP tables', 'listening TCP sockets together with the owning process', 'D', 'ss -tnlp shows TCP sockets in numeric form, including listening ports and the PID of each bound process.', 'ADVANCED', 3, 'MCQ', 1),
(3149, 90, 'What is the main difference between apt and dpkg?', 'dpkg is a low-level tool that does not resolve dependencies, while apt manages dependency resolution', 'apt is older than dpkg', 'dpkg only removes packages', 'they are identical', 'A', 'dpkg installs and removes individual .deb files, whereas apt consults repositories and resolves dependencies.', 'ADVANCED', 3, 'MCQ', 1),
(3150, 90, 'What does ufw provide to an administrator?', 'a graphical package browser', 'a simplified interface for configuring firewall rules', 'a DNS server', 'a load balancer', 'B', 'ufw (uncomplicated firewall) offers an easy front end over iptables for opening and closing ports.', 'ADVANCED', 3, 'MCQ', 1),
(3151, 91, 'Which mechanism allows a user program to request services from the operating system kernel?', 'a system call', 'a library function', 'a device driver', 'a shell script', 'A', 'A system call is the programmed interface through which a user process asks the kernel to perform privileged operations.', 'BEGINNER', 1, 'MCQ', 1),
(3152, 91, 'Which header file on Linux declares common POSIX system calls such as read and write?', 'unistd.h', 'stdio.h', 'stdlib.h', 'math.h', 'B', 'unistd.h declares POSIX system call prototypes such as read, write, open, close and fork.', 'BEGINNER', 1, 'MCQ', 1),
(3153, 91, 'What does the fork system call do?', 'terminates the current process', 'creates a new process as a copy of the calling process', 'loads a new program into the current process', 'changes the current working directory', 'C', 'fork creates a child process that is a near-identical copy of the calling parent process.', 'BEGINNER', 1, 'MCQ', 1),
(3154, 91, 'Which system call replaces the current process image with a new program?', 'fork', 'clone', 'execve', 'wait', 'D', 'execve loads a new executable into the current process, replacing its previous code and data.', 'BEGINNER', 1, 'MCQ', 1),
(3155, 91, 'What is a library in the context of system programming?', 'a set of precompiled routines that programs can link against', 'a hardware device for storage', 'a kernel module', 'a command-line utility', 'A', 'A library is a collection of precompiled functions that application programs can reuse by linking against it.', 'BEGINNER', 1, 'MCQ', 1),
(3156, 91, 'What does the open system call return on success?', 'a pointer', 'a file descriptor', 'a FILE structure', 'a device number', 'B', 'open returns a non-negative integer file descriptor that identifies the opened file to later calls.', 'BEGINNER', 1, 'MCQ', 1),
(3157, 91, 'Which library implements the standard C functions that wrap low-level system calls on Linux?', 'libc', 'libm', 'libpthread', 'libz', 'C', 'libc provides the standard C library functions, including wrappers around most Linux system calls.', 'BEGINNER', 1, 'MCQ', 1),
(3158, 91, 'What does the stat system call retrieve?', 'information about a file such as size and permissions', 'the contents of a file', 'the number of running processes', 'the kernel version', 'D', 'stat returns a struct with metadata about a file, including its size, owner and permissions.', 'BEGINNER', 1, 'MCQ', 1),
(3159, 91, 'What is errno in C system programming?', 'a global variable that records the error number of the last failed system call', 'a file containing error messages', 'a signal number', 'a return code from main', 'A', 'errno is set by system calls and library functions to an error number describing why the last operation failed.', 'BEGINNER', 1, 'MCQ', 1),
(3160, 91, 'Which tool can be used to trace which system calls a program makes?', 'strace', 'gcc', 'make', 'grep', 'B', 'strace intercepts and records the system calls and signals of a running process.', 'BEGINNER', 1, 'MCQ', 1),
(3161, 91, 'A program calls read with a buffer, count and file descriptor. What does read return when it reaches the end of the file?', '-1', '0', '1', 'the buffer address', 'C', 'A read that returns 0 indicates that end-of-file was reached and no more data is available.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3162, 91, 'A process calls fork and then prints its PID. How many times is the print statement executed?', 'once', 'twice', 'four times', 'zero times', 'D', 'After a successful fork both the parent and child continue execution, so the statement runs once in each process.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3163, 91, 'Why is the result of write sometimes less than the requested count?', 'the buffer was too small', 'write may be interrupted or the device may accept only part of the data', 'the file descriptor is invalid', 'the kernel always pads the output', 'A', 'write can perform a partial transfer, so robust programs must loop until the full count is written or an error occurs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3164, 91, 'A program opens a file, then calls close on its descriptor. What happens if it reads from the descriptor afterwards?', 'the read returns stale data', 'the read returns the cached contents', 'the read fails with EBADF', 'the read reopens the file', 'B', 'Using a closed file descriptor is invalid and the read fails with the EBADF error indicating a bad descriptor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3165, 91, 'Which flag combination passed to open creates the file if it does not exist?', 'O_RDONLY', 'O_CREAT', 'O_TRUNC', 'O_APPEND', 'C', 'O_CREAT tells open to create the file when it does not already exist.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3166, 91, 'What does the wait system call allow a parent process to do?', 'sleep until any child process terminates and obtain its status', 'pause all children', 'resume a stopped child', 'kill all children', 'D', 'wait blocks the parent until a child terminates and returns that child''s status for inspection.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3167, 91, 'How does a system call transfer control from user mode to kernel mode?', 'through a software trap instruction such as syscall', 'by calling a normal function', 'by raising a hardware interrupt to the CPU', 'through a device driver callback', 'A', 'A trap or syscall instruction switches the CPU into kernel mode and jumps to the kernel''s system call handler.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3168, 91, 'What is the main difference between a system call and a library function call?', 'library calls run in user mode while system calls enter the kernel', 'system calls run in user mode', 'library calls are always slower', 'there is no difference', 'B', 'A library function executes in user space, while a system call switches the processor into kernel mode.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3169, 91, 'A program wants the highest speed by avoiding per-call overhead. What buffering approach is most common in libc?', 'using buffered I/O via FILE* streams', 'calling read for every byte', 'using direct memory-mapped registers', 'opening the file many times', 'C', 'stdio functions such as fread buffer data internally, reducing the number of expensive system calls.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3170, 91, 'What happens if a process ignores the return value of a system call that can fail?', 'nothing, return values are optional', 'the failure goes unnoticed, potentially corrupting program logic', 'the kernel terminates the process', 'the compiler warns but it is always safe', 'D', 'System calls report errors through their return value and errno, so ignoring them can hide failures that later cause incorrect behavior.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3171, 91, 'Why must a multithreaded program use the per-thread variants of errno?', 'errno is a thread-local value so each thread sees its own error without interference', 'errno is shared to coordinate errors', 'errno is stored in the kernel', 'errno is disabled in threads', 'A', 'On Linux errno is thread-local, so concurrent threads do not clobber each other''s error codes.', 'ADVANCED', 3, 'MCQ', 1),
(3172, 91, 'A server wants to handle many concurrent clients without one thread per client. Which combination is most scalable?', 'blocking I/O with one thread per connection', 'nonblocking descriptors combined with poll or epoll', 'spawning a fork per client', 'sleeping between accept calls', 'B', 'Nonblocking descriptors with an event loop such as epoll allow a single thread to multiplex thousands of connections.', 'ADVANCED', 3, 'MCQ', 1),
(3173, 91, 'Why might a file write that succeeds not be durable across a sudden power loss?', 'the data may still be sitting in the kernel page cache', 'the file was opened read-only', 'write always writes to disk immediately', 'the data is lost because the buffer is in user space', 'C', 'The kernel buffers written data in the page cache and flushes it later, so fsync is needed to force it to disk.', 'ADVANCED', 3, 'MCQ', 1),
(3174, 91, 'A library must be used by many programs without copying its code into each executable. Which approach is most appropriate?', 'a static library', 'a shared library', 'a header-only library', 'a command-line script', 'D', 'A shared library is linked at runtime and shared in memory by many processes, saving disk and memory.', 'ADVANCED', 3, 'MCQ', 1),
(3175, 91, 'What is the purpose of the mmap system call in high-performance file I/O?', 'it maps a file directly into the process address space, letting reads and writes go through normal memory', 'it copies the file into the page cache', 'it locks the file against other processes', 'it increases the file descriptor limit', 'A', 'mmap places the file contents in the process''s virtual memory, so the kernel manages paging without explicit read and write calls.', 'ADVANCED', 3, 'MCQ', 1),
(3176, 91, 'Why is execve never expected to return on success?', 'the calling process image is replaced, so there is no code left to continue', 'the kernel queues the return', 'execve always fails', 'the process is automatically killed', 'B', 'On success execve replaces the entire process image, so the old program no longer exists and control never returns to it.', 'ADVANCED', 3, 'MCQ', 1),
(3177, 91, 'A system call is interrupted by a signal and returns -1 with errno set to EINTR. What should a robust program do?', 'retry the system call', 'treat it as a fatal error', 'ignore the return value', 'reboot the machine', 'C', 'EINTR means the call was interrupted before completing, so the correct response is usually to retry it.', 'ADVANCED', 3, 'MCQ', 1),
(3178, 91, 'What is the key advantage of system calls such as sendfile for network file transfer?', 'data is copied between file and socket in the kernel without user-space copying', 'it uses slower buffered I/O', 'it compresses data during transfer', 'it requires the CPU to copy every byte twice', 'D', 'sendfile copies data directly between file descriptors inside the kernel, avoiding the expensive round trip through user buffers.', 'ADVANCED', 3, 'MCQ', 1),
(3179, 91, 'Why does a setuid program need careful handling of environment variables?', 'an untrusted environment can be used to influence library loading or execution, leading to privilege escalation', 'environment variables speed up the program', 'the kernel requires environment variables', 'setuid programs cannot read the environment', 'A', 'A privileged process that loads libraries based on environment variables such as LD_PRELOAD can be exploited to run attacker code.', 'ADVANCED', 3, 'MCQ', 1),
(3180, 91, 'What does lseek allow a program to do on a file descriptor?', 'move the file offset to a given position for the next read or write', 'set the file permissions', 'truncate the file', 'change the file owner', 'B', 'lseek changes the current file offset, allowing random access to different positions within a file.', 'ADVANCED', 3, 'MCQ', 1),
(3181, 92, 'What is a signal in Unix system programming?', 'an asynchronous notification sent to a process', 'a hardware error', 'a library function', 'a file format', 'A', 'A signal is a software notification delivered asynchronously to a process to inform it of an event.', 'BEGINNER', 1, 'MCQ', 1),
(3182, 92, 'What happens to a process when it receives SIGINT from the terminal?', 'it is terminated by default', 'it continues running', 'it is paused', 'it ignores the signal', 'B', 'SIGINT, generated by pressing Ctrl-C, terminates the receiving process by default.', 'BEGINNER', 1, 'MCQ', 1),
(3183, 92, 'Which system call installs a custom signal handler in a C program?', 'signal', 'kill', 'raise', 'alarm', 'C', 'The signal function registers a handler function that will be invoked when the specified signal arrives.', 'BEGINNER', 1, 'MCQ', 1),
(3184, 92, 'What does SIGKILL do to a process?', 'it can be caught but ignored', 'it terminates the process and cannot be caught or ignored', 'it pauses the process', 'it prints a warning', 'D', 'SIGKILL forcibly terminates a process and cannot be caught, blocked or ignored by the process.', 'BEGINNER', 1, 'MCQ', 1),
(3185, 92, 'What is an IPC mechanism?', 'a way for processes to communicate and share data', 'a network protocol', 'a debugging tool', 'a scheduling algorithm', 'A', 'Inter-process communication (IPC) refers to the mechanisms by which processes exchange data and synchronize.', 'BEGINNER', 1, 'MCQ', 1),
(3186, 92, 'Which simple IPC mechanism transmits a stream of bytes between two processes?', 'a pipe', 'a register', 'a signal mask', 'a page table', 'B', 'A pipe provides a unidirectional byte stream connecting two processes.', 'BEGINNER', 1, 'MCQ', 1),
(3187, 92, 'What is a shared memory segment?', 'memory that multiple processes map and access concurrently', 'memory only the kernel uses', 'a file on disk', 'a network buffer', 'C', 'Shared memory is a region of memory mapped into the address space of multiple processes so they can share data.', 'BEGINNER', 1, 'MCQ', 1),
(3188, 92, 'Which function is used by a process to send a signal to another process?', 'kill', 'wait', 'exec', 'fork', 'D', 'The kill system call sends a specified signal to a process or process group.', 'BEGINNER', 1, 'MCQ', 1),
(3189, 92, 'What does a message queue provide?', 'a linked-list based mechanism to send structured messages between processes', 'a high-speed network', 'a shared register bank', 'a backup service', 'A', 'A message queue lets processes exchange discrete messages of data through kernel-managed queues.', 'BEGINNER', 1, 'MCQ', 1),
(3190, 92, 'What does SIGSEGV indicate?', 'an invalid memory access, typically a segfault', 'a normal program exit', 'a keyboard interrupt', 'an arithmetic error', 'B', 'SIGSEGV is sent when a process accesses memory it is not allowed to access, causing a segmentation fault.', 'BEGINNER', 1, 'MCQ', 1),
(3191, 92, 'A pipe is created between a parent and child. What must the parent do to write to the child?', 'close the read end and write to the write end', 'close the write end and read from the read end', 'fork again', 'open a new file', 'C', 'Each process closes the end it does not use; the parent closes the read end and writes to the write end.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3192, 92, 'A process installs a handler for SIGINT and then presses Ctrl-C. What runs?', 'the custom handler instead of the default action', 'the default handler', 'nothing', 'the shell''s handler', 'D', 'When a signal has a custom handler installed, that handler is invoked in place of the default action.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3193, 92, 'Why must a signal handler avoid calling most library functions?', 'signal handlers are restricted to async-signal-safe functions to avoid corrupting state', 'library functions are too slow', 'the kernel blocks all calls', 'handlers run in kernel mode', 'A', 'Only async-signal-safe functions may be called from a signal handler because the handler may interrupt any point of the program.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3194, 92, 'A process wants the kernel to send it SIGALRM after 5 seconds. Which system call does it use?', 'alarm', 'sleep', 'pause', 'timerfd', 'B', 'alarm arranges for the kernel to deliver SIGALRM to the process after the specified number of seconds.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3195, 92, 'Two processes share a memory segment but see inconsistent data. What is missing?', 'synchronization, such as a semaphore or mutex', 'larger memory', 'a faster CPU', 'more system calls', 'C', 'Without synchronization primitives, concurrent access to shared memory can produce race conditions and inconsistent data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3196, 92, 'What does SIGCHLD tell a parent process?', 'that a child process has terminated or stopped', 'that a child was created', 'that the parent has no children', 'that the disk is full', 'D', 'The kernel sends SIGCHLD to a parent when one of its children terminates, stops, or resumes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3197, 92, 'What is a named pipe, also called a FIFO?', 'a pipe that exists in the filesystem and can be opened by unrelated processes', 'a pipe only the kernel can use', 'a socket on a remote host', 'a special device for printing', 'A', 'A FIFO is a named pipe that appears as a file and allows communication between unrelated processes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3198, 92, 'How does a process temporarily prevent a signal from being delivered?', 'by blocking it with sigprocmask or sigaction mask', 'by changing its priority', 'by closing a file descriptor', 'by forking a child', 'B', 'A process can block selected signals so they are deferred until the mask is changed again.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3199, 92, 'What is a semaphore used for in IPC?', 'synchronizing access to a shared resource', 'storing large files', 'compressing data', 'naming processes', 'C', 'A semaphore is a counter used to control access to a shared resource and coordinate concurrent processes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3200, 92, 'A server wants to receive one of several signals and act on each appropriately. Which function lets it install distinct handlers?', 'sigaction', 'signal', 'sigprocmask', 'raise', 'D', 'sigaction gives detailed control, allowing a distinct handler to be installed for each signal.', 'INTERMEDIATE', 2, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(3201, 92, 'Why are condition variables superior to spin-waiting on a shared flag for thread synchronization?', 'they block the waiter and let the CPU do useful work instead of busy-waiting', 'they always run faster', 'they avoid the operating system entirely', 'they remove the need for locks', 'A', 'Condition variables park waiting threads, letting the scheduler run other work rather than burning CPU in a spin loop.', 'ADVANCED', 3, 'MCQ', 1),
(3202, 92, 'A process blocks SIGTERM, then unblocks it later. What happens to a SIGTERM that arrived while blocked?', 'it is delivered as soon as the signal is unblocked', 'it is lost permanently', 'it is ignored forever', 'it crashes the process immediately', 'B', 'Blocked signals are pending and are delivered once the process unblocks them.', 'ADVANCED', 3, 'MCQ', 1),
(3203, 92, 'Why is it dangerous to read errno inside a signal handler?', 'errno is not guaranteed to be async-signal-safe and may be overwritten by the interrupted code', 'errno is always zero in handlers', 'signals cannot access errno', 'errno lives in the kernel', 'C', 'A signal handler may interrupt code that just set errno, and the handler''s own calls could change it, so handlers should save and restore errno.', 'ADVANCED', 3, 'MCQ', 1),
(3204, 92, 'A real-time signal is preferable over SIGUSR1 when what property is needed?', 'real-time signals are queued and carry an integer value, so none are lost', 'real-time signals are faster', 'real-time signals require no handler', 'real-time signals only work for the root user', 'D', 'Standard signals can be coalesced and carry no data, whereas real-time signals are queued and deliver an attached value.', 'ADVANCED', 3, 'MCQ', 1),
(3205, 92, 'What is the primary risk when using a shared memory segment that is not protected by a mutex or semaphore?', 'data races that produce corrupted or inconsistent values', 'the segment fills the disk', 'the kernel panics', 'the network becomes congested', 'A', 'Unsynchronized concurrent access lets multiple processes race, corrupting shared data.', 'ADVANCED', 3, 'MCQ', 1),
(3206, 92, 'A child writes a large amount of data to a pipe while the parent sleeps. What happens when the pipe buffer fills?', 'the child''s write blocks until the parent reads', 'the child is killed', 'the data is dropped', 'the pipe grows unboundedly', 'B', 'Writes to a full pipe block, waiting until the reading process drains some data and makes space.', 'ADVANCED', 3, 'MCQ', 1),
(3207, 92, 'What is a deadlock in the context of IPC synchronization?', 'two or more processes each wait forever for a resource held by the other', 'a process that is too slow', 'a signal that is ignored', 'a message that is too large', 'C', 'Deadlock occurs when every participant holds a resource another needs, so all wait indefinitely.', 'ADVANCED', 3, 'MCQ', 1),
(3208, 92, 'Why might a programmer prefer mmap-based shared memory over System V shared memory?', 'POSIX shm is file-based, easier to manage, and integrates with standard file APIs', 'System V shm is faster', 'mmap cannot be shared', 'POSIX shm is always secure', 'D', 'POSIX shared memory uses named files, is simpler to control, and interoperates cleanly with ftruncate and mmap.', 'ADVANCED', 3, 'MCQ', 1),
(3209, 92, 'Which issue can arise when a handler is invoked from inside a library that is not reentrant?', 'the library''s internal state may be corrupted because the handler runs in the middle of its work', 'the library gains extra privileges', 'the library deletes the signal', 'the handler never executes', 'A', 'If a signal interrupts a non-reentrant library function and the handler calls it again, the internal state can be corrupted.', 'ADVANCED', 3, 'MCQ', 1),
(3210, 92, 'A system call returns -1 with errno EAGAIN while acquiring a System V semaphore. What does this mean?', 'the semaphore operation could not complete without blocking and nonblocking mode was requested', 'the semaphore is corrupt', 'the process has no memory', 'the kernel has crashed', 'B', 'EAGAIN indicates the operation could not proceed immediately and blocking was disabled via IPC_NOWAIT.', 'ADVANCED', 3, 'MCQ', 1),
(3211, 93, 'What is an interrupt?', 'an event that temporarily halts the CPU to handle a high-priority task', 'a compiler warning', 'a type of process', 'a network packet', 'A', 'An interrupt is a hardware or software event that causes the CPU to pause current work and run a handler.', 'BEGINNER', 1, 'MCQ', 1),
(3212, 93, 'What is an exception in the context of a CPU?', 'a synchronous event generated by the executing instruction, such as a fault or trap', 'a software bug that always crashes', 'a user-mode function call', 'a device malfunction', 'B', 'An exception is a synchronous event raised by the currently executing instruction, including faults, traps and aborts.', 'BEGINNER', 1, 'MCQ', 1),
(3213, 93, 'What does an interrupt handler do?', 'it services the interrupt and restores the interrupted context', 'it deletes the interrupted process', 'it compiles the program', 'it prints an error message', 'C', 'The interrupt handler deals with the cause of the interrupt, then returns control to the interrupted code.', 'BEGINNER', 1, 'MCQ', 1),
(3214, 93, 'What is the interrupt vector table?', 'a table mapping each interrupt or exception to the address of its handler', 'a table of running processes', 'a list of device drivers', 'a cache of files', 'D', 'The interrupt descriptor or vector table stores the entry point of the handler for every interrupt and exception.', 'BEGINNER', 1, 'MCQ', 1),
(3215, 93, 'Which of the following is an example of a synchronous exception?', 'a page fault', 'a keyboard press', 'a timer tick', 'a network packet arrival', 'A', 'A page fault is triggered synchronously by an instruction that references an unmapped page.', 'BEGINNER', 1, 'MCQ', 1),
(3216, 93, 'What is a trap instruction?', 'an instruction that deliberately transfers control to the operating system', 'an instruction that halts the CPU', 'an instruction that multiplies', 'an instruction that prints', 'B', 'A trap is an instruction that intentionally causes an exception so a program can request kernel services.', 'BEGINNER', 1, 'MCQ', 1),
(3217, 93, 'What is an interrupt latency?', 'the time between when an interrupt occurs and when its handler begins executing', 'the time a process spends sleeping', 'the size of an interrupt packet', 'the number of interrupts per second', 'C', 'Interrupt latency measures the delay from the interrupt request until the handler starts running.', 'BEGINNER', 1, 'MCQ', 1),
(3218, 93, 'What is a hardware interrupt driven by?', 'a physical device such as a keyboard, disk or timer', 'a software instruction', 'a process schedule', 'a compiler decision', 'D', 'Hardware interrupts are generated by devices to signal the CPU that they need attention.', 'BEGINNER', 1, 'MCQ', 1),
(3219, 93, 'What happens to the CPU when an interrupt fires?', 'it saves the current context and jumps to the handler', 'it reboots', 'it empties all registers', 'it stops forever', 'A', 'The CPU saves the interrupted state and transfers control to the appropriate interrupt handler.', 'BEGINNER', 1, 'MCQ', 1),
(3220, 93, 'What is a software interrupt?', 'an interrupt triggered by an instruction, such as a system call or breakpoint', 'an interrupt from the power supply', 'an interrupt that never runs', 'a type of virus', 'B', 'Software interrupts are raised programmatically by instructions like syscall or int to invoke kernel services.', 'BEGINNER', 1, 'MCQ', 1),
(3221, 93, 'Why is it important that interrupt handlers be fast?', 'long handlers delay other interrupts and increase system latency', 'handlers use the network', 'the CPU forgets the context', 'long handlers delete the process', 'C', 'A slow handler blocks the CPU from servicing other interrupts, hurting responsiveness and throughput.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3222, 93, 'A divide-by-zero operation causes which type of exception?', 'a fault', 'a nonmaskable interrupt', 'a device interrupt', 'a trap', 'D', 'Divide-by-zero is a synchronous fault generated by the arithmetic instruction that attempted the division.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3223, 93, 'When a page fault occurs, what does the handler usually do?', 'it loads the required page from disk and resumes the faulting instruction', 'it kills the process', 'it ignores the fault', 'it resets the CPU', 'A', 'The page fault handler brings the needed page into memory and lets the faulting instruction be retried.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3224, 93, 'Why do modern kernels split interrupt processing into top-half and bottom-half work?', 'to keep critical handler work short and defer heavy work to a safer context', 'to run handlers in parallel', 'to disable interrupts completely', 'to save memory', 'B', 'The top half performs minimal urgent work while the bottom half runs later with interrupts enabled to finish the task.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3225, 93, 'What is a maskable interrupt?', 'an interrupt that can be disabled by the CPU using a flag such as IF', 'an interrupt that always runs', 'an interrupt with no handler', 'an interrupt from the timer', 'C', 'A maskable interrupt can be temporarily disabled by clearing the interrupt flag so the CPU ignores it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3226, 93, 'What is a non-maskable interrupt (NMI) typically used for?', 'serious conditions like hardware failures that must be handled immediately', 'regular timer ticks', 'keyboard input', 'ordinary file I/O', 'D', 'NMIs cannot be blocked and are reserved for critical events such as memory errors and watchdogs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3227, 93, 'What is the difference between a fault and a trap?', 'a fault reports an error and re-executes the instruction, while a trap is a deliberate jump to the handler', 'a fault is always fatal', 'a trap cannot be handled', 'there is no difference', 'A', 'Faults are often recoverable and the instruction is retried, whereas traps transfer control intentionally for system calls.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3228, 93, 'Which mechanism delivers a device interrupt to the correct handler?', 'the interrupt vector table indexed by the interrupt number', 'a global variable', 'a scheduler', 'the file system', 'B', 'Each interrupt number points into the interrupt vector table to find the handler registered for that device.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3229, 93, 'Why must a kernel disable interrupts while updating critical structures?', 'to prevent concurrent modification by interrupt handlers', 'to increase speed', 'to allow more interrupts', 'to save disk space', 'C', 'Disabling interrupts stops handlers from running during the critical section, preventing races on shared kernel data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3230, 93, 'What is the purpose of an interrupt request (IRQ) line?', 'a hardware line a device uses to signal the CPU that it needs service', 'a line of source code', 'a kernel log', 'a network address', 'D', 'Devices assert IRQ lines to interrupt the CPU and request that their handler be invoked.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3231, 93, 'Why might nested interrupts be dangerous?', 'a second interrupt can re-enter a handler before the first finishes, corrupting stack and state', 'nested interrupts are always fatal', 'they run too slowly', 'they waste disk space', 'A', 'Nested interrupts re-enter the handler stack and risk corrupting shared state, so kernels often mask interrupts during handlers.', 'ADVANCED', 3, 'MCQ', 1),
(3232, 93, 'What is a spurious interrupt?', 'an interrupt with no real source, often due to electrical noise or line glitches', 'an interrupt that runs twice', 'a software trap', 'an interrupt with a high priority', 'B', 'A spurious interrupt is a stray signal with no actual device request, which the handler must acknowledge and ignore.', 'ADVANCED', 3, 'MCQ', 1),
(3233, 93, 'Why do operating systems use an interrupt priority scheme?', 'to let urgent devices preempt lower-priority handlers', 'to make all interrupts equal', 'to disable the timer', 'to save memory', 'C', 'Priority levels allow a higher-priority device interrupt to preempt a lower-priority handler in progress.', 'ADVANCED', 3, 'MCQ', 1),
(3234, 93, 'How does an edge-triggered interrupt differ from a level-triggered one?', 'edge-triggered responds to a change in signal level while level-triggered responds to the level being active', 'edge-triggered is slower', 'level-triggered cannot be handled', 'there is no difference', 'D', 'Edge triggering reacts on the signal transition, while level triggering reacts while the signal remains asserted.', 'ADVANCED', 3, 'MCQ', 1),
(3235, 93, 'What problem can occur if a shared interrupt line handler does not check which device asserted the interrupt?', 'it may service the wrong device or miss a device that needs service', 'the kernel crashes', 'the CPU overheats', 'the system reboots', 'A', 'On shared IRQ lines the handler must query each device to find the real source, otherwise requests can be mishandled.', 'ADVANCED', 3, 'MCQ', 1),
(3236, 93, 'What is the role of the interrupt controller (such as an APIC)?', 'it collects device interrupts and forwards them to the CPU with priority and routing information', 'it stores the file system', 'it schedules processes', 'it compiles the kernel', 'B', 'The interrupt controller aggregates, prioritizes and routes interrupts from many devices to the CPU.', 'ADVANCED', 3, 'MCQ', 1),
(3237, 93, 'Why should time-critical driver work avoid running in the top half?', 'the top half runs with interrupts disabled and must be minimal to keep latency low', 'the top half has too much memory', 'the top half is user mode', 'the top half cannot access registers', 'C', 'Top-half code runs with interrupts masked, so heavy work there blocks all other interrupts and raises system latency.', 'ADVANCED', 3, 'MCQ', 1),
(3238, 93, 'What is an exception frame?', 'the saved register context pushed when an exception occurs so the handler can restore it', 'a window on screen', 'a network packet', 'a data structure for files', 'D', 'The CPU pushes the exception frame containing the saved state, which the handler pops when returning.', 'ADVANCED', 3, 'MCQ', 1),
(3239, 93, 'A machine check exception (MCE) most commonly signals what?', 'a hardware error such as uncorrectable memory corruption', 'a normal system call', 'a keyboard event', 'a page allocation', 'A', 'A machine check exception indicates a detected hardware error, such as a memory or bus failure, that needs handling.', 'ADVANCED', 3, 'MCQ', 1),
(3240, 93, 'Why do real-time systems often require predictable interrupt latency?', 'tasks must respond to external events within hard deadlines, so worst-case latency must be bounded', 'to reduce electricity use', 'to make the GUI prettier', 'to store more data', 'B', 'Real-time workloads need guaranteed worst-case response times, making bounded and predictable interrupt latency essential.', 'ADVANCED', 3, 'MCQ', 1),
(3241, 94, 'What is a device driver?', 'a kernel module that controls a hardware device', 'a user application', 'a file format', 'a network protocol', 'A', 'A device driver is software that gives the kernel a uniform interface to a specific hardware device.', 'BEGINNER', 1, 'MCQ', 1),
(3242, 94, 'Which part of the operating system talks directly to hardware devices?', 'the kernel''s device drivers', 'the shell', 'the compiler', 'the assembler', 'B', 'Device drivers run in the kernel and communicate directly with the hardware they control.', 'BEGINNER', 1, 'MCQ', 1),
(3243, 94, 'What is an I/O port?', 'an address through which the CPU communicates with a device', 'a network socket', 'a serial port', 'a memory buffer', 'C', 'An I/O port is a numbered address used by the CPU to send commands and data to a device.', 'BEGINNER', 1, 'MCQ', 1),
(3244, 94, 'What is memory-mapped I/O?', 'a scheme where device registers appear as memory addresses accessed with normal loads and stores', 'I/O done by the GPU', 'I/O over the network', 'I/O that uses no CPU', 'D', 'In memory-mapped I/O, device control registers are assigned addresses in the memory space and accessed like ordinary memory.', 'BEGINNER', 1, 'MCQ', 1),
(3245, 94, 'What is the primary interface a driver provides to user-space applications?', 'special files under /dev plus ioctl, read and write calls', 'a web page', 'a GUI window', 'an email account', 'A', 'Drivers expose device files in /dev that applications access through standard file operations and ioctl.', 'BEGINNER', 1, 'MCQ', 1),
(3246, 94, 'What is a character device?', 'a device that transfers data one character or byte at a time', 'a device that stores blocks', 'a device with no output', 'a network device', 'B', 'Character devices handle data as a byte stream, such as keyboards, serial ports and terminals.', 'BEGINNER', 1, 'MCQ', 1),
(3247, 94, 'What is a block device?', 'a device that reads and writes data in fixed-size blocks, such as a disk', 'a device that prints text', 'a device with no storage', 'a sound card', 'C', 'Block devices transfer data in fixed-size blocks and are typically used for storage such as disks.', 'BEGINNER', 1, 'MCQ', 1),
(3248, 94, 'Which command lists the block devices attached to a Linux system?', 'lsblk', 'grep', 'make', 'top', 'D', 'lsblk lists information about all available block devices in a readable tree format.', 'BEGINNER', 1, 'MCQ', 1),
(3249, 94, 'What does the ioctl system call allow an application to do?', 'send device-specific control commands to a driver', 'compile a program', 'create a file', 'start a server', 'A', 'ioctl lets user programs issue device-specific operations that do not fit into standard read or write.', 'BEGINNER', 1, 'MCQ', 1),
(3250, 94, 'What is a kernel module?', 'a loadable unit of kernel code, such as a driver, that can be inserted at runtime', 'a user script', 'a configuration file', 'a shell command', 'B', 'A kernel module is a piece of kernel code that can be loaded and unloaded dynamically, commonly a device driver.', 'BEGINNER', 1, 'MCQ', 1),
(3251, 94, 'Why must device drivers be extra careful about memory safety?', 'a bug in a driver runs in kernel mode and can crash the whole system', 'drivers run in user mode', 'drivers are always safe', 'bugs only affect one process', 'C', 'Driver code executes with kernel privileges, so a single memory error can corrupt the kernel and crash the entire system.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3252, 94, 'What is a device tree?', 'a data structure describing the hardware attached to a system, used during boot', 'a folder of drivers', 'a scheduling queue', 'a file system index', 'D', 'The device tree describes hardware components and how they are connected, letting the kernel probe and configure devices.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3253, 94, 'Which method lets the CPU avoid repeatedly polling a device for completion?', 'interrupt-driven I/O', 'busy polling', 'sleeping forever', 'blocking the network', 'A', 'With interrupt-driven I/O the device interrupts the CPU when done, instead of the CPU constantly checking status.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3254, 94, 'What is DMA (direct memory access)?', 'a mechanism where hardware transfers data to memory without CPU involvement', 'a scheduling algorithm', 'a type of driver', 'a security protocol', 'B', 'DMA lets a device move data directly between itself and memory, freeing the CPU for other work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3255, 94, 'What is the major and minor number of a device file?', 'the major identifies the driver and the minor identifies the specific device instance', 'the size and speed', 'the owner and group', 'the read and write counts', 'C', 'The major number selects which driver handles the device, while the minor number identifies a particular instance.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3256, 94, 'A driver needs to handle high data throughput. Which transfer method is most efficient?', 'DMA with interrupts', 'polling one byte at a time', 'reading via a web server', 'using a shell script', 'D', 'DMA moves large blocks directly between device and memory, minimizing CPU involvement and yielding high throughput.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3257, 94, 'What is a driver''s probe function?', 'a routine that checks whether the device is present and initializes it', 'a routine that deletes the driver', 'a routine that compiles the kernel', 'a routine that prints logs', 'A', 'The probe function verifies a device exists at a given address and sets up the driver for it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3258, 94, 'Why might a driver register an interrupt handler?', 'to be notified asynchronously when the device completes an operation', 'to make the device faster', 'to log all reads', 'to disable the device', 'B', 'Registering an interrupt handler lets the kernel call the driver when the device signals completion.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3259, 94, 'What is the purpose of the open method in a character driver?', 'to set up per-open state when a user opens the device file', 'to start the computer', 'to load the kernel', 'to create a new device', 'C', 'The driver''s open callback runs when an application opens the device node, allowing it to initialize state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3260, 94, 'What typically happens when a driver performs a read the user did not expect?', 'the driver returns an error such as EINVAL or EFAULT', 'the kernel crashes', 'the device explodes', 'nothing, the call is ignored', 'D', 'A well-behaved driver validates requests and returns an appropriate error code when a request is invalid.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3261, 94, 'Why is it dangerous for a driver to trust pointers passed from user space?', 'it must validate them with copy_from_user and access_ok to avoid security holes', 'user pointers are always valid', 'it can ignore them', 'the kernel validates them automatically', 'A', 'User-space pointers may be invalid or malicious, so drivers must copy data through safe kernel APIs to avoid exploitation.', 'ADVANCED', 3, 'MCQ', 1),
(3262, 94, 'What is a race condition in a device driver?', 'concurrent access to shared driver state without locking, producing incorrect behavior', 'a fast device', 'a slow device', 'a driver with no bugs', 'B', 'Without proper locking, concurrent operations can interleave and corrupt driver state, causing bugs.', 'ADVANCED', 3, 'MCQ', 1),
(3263, 94, 'What is the purpose of a workqueue or tasklet in a driver?', 'to defer work that cannot be done in an interrupt context to a safer execution context', 'to speed up the disk', 'to replace the scheduler', 'to encrypt data', 'C', 'Deferred work mechanisms move non-urgent processing out of interrupt context where sleeping and most APIs are forbidden.', 'ADVANCED', 3, 'MCQ', 1),
(3264, 94, 'Why should a driver use a completion mechanism rather than a busy-wait loop?', 'it lets the waiting task sleep and the CPU do useful work until the device signals completion', 'it makes the code shorter', 'it avoids using memory', 'it is required by the compiler', 'D', 'Completions put the waiting thread to sleep, so CPU cycles are not wasted polling for device completion.', 'ADVANCED', 3, 'MCQ', 1),
(3265, 94, 'What is a common cause of driver-initiated system crashes?', 'dereferencing NULL or invalid pointers, or corrupting kernel memory', 'using too much RAM', 'printing logs', 'opening the device', 'A', 'Drivers run in kernel space, so invalid pointer dereferences corrupt the kernel and cause a panic.', 'ADVANCED', 3, 'MCQ', 1),
(3266, 94, 'Why might a driver need to map a device''s memory into the kernel address space?', 'to access memory-mapped device registers through normal pointers', 'to make the device invisible', 'to increase file size', 'to speed up the network', 'B', 'Mapping device memory lets the driver read and write device registers with ordinary load and store instructions.', 'ADVANCED', 3, 'MCQ', 1),
(3267, 94, 'What is the typical consequence of a driver calling a sleeping function from an interrupt handler?', 'undefined behavior and a likely kernel crash, since interrupt context cannot sleep', 'the function executes normally', 'the device resets', 'the interrupt is ignored', 'C', 'Interrupt context cannot block or sleep, so calling a sleeping API there corrupts the kernel and usually crashes it.', 'ADVANCED', 3, 'MCQ', 1),
(3268, 94, 'What is the purpose of a character device''s llseek method?', 'to change the file position used by subsequent reads and writes', 'to open the device', 'to release the device', 'to poll the device', 'D', 'The llseek method moves the file offset within the device so applications can access different positions.', 'ADVANCED', 3, 'MCQ', 1),
(3269, 94, 'What does it mean for a driver to be reentrant?', 'it can safely be called by multiple processes or interrupt contexts at the same time', 'it runs only once', 'it cannot be loaded', 'it ignores interrupts', 'A', 'A reentrant driver can have multiple active invocations, so it must protect shared state with appropriate locking.', 'ADVANCED', 3, 'MCQ', 1),
(3270, 94, 'Why do kernel drivers prefer the kernel''s allocation APIs over user-space style allocation?', 'they provide kernel-appropriate flags like GFP_KERNEL and interrupt-safe variants', 'they are faster', 'they never fail', 'they use less memory', 'B', 'Kernel allocation functions accept flags controlling behavior such as whether the caller may sleep, matching the execution context.', 'ADVANCED', 3, 'MCQ', 1),
(3271, 95, 'What is an assembler?', 'a program that translates assembly language into machine code', 'a compiler for high-level languages', 'a linker', 'a debugger', 'A', 'An assembler converts human-readable assembly language instructions into binary machine code.', 'BEGINNER', 1, 'MCQ', 1),
(3272, 95, 'What is a compiler?', 'a program that translates a high-level language into machine code or an intermediate representation', 'a program that runs assembly', 'a type of processor', 'a memory allocator', 'B', 'A compiler transforms a high-level source language into a lower-level form such as machine code.', 'BEGINNER', 1, 'MCQ', 1),
(3273, 95, 'What is an assembly language instruction such as MOV or ADD called in relation to the CPU?', 'a mnemonic', 'a constant', 'a variable', 'a label', 'C', 'Mnemonics are the short symbolic names used in assembly language for machine instructions.', 'BEGINNER', 1, 'MCQ', 1),
(3274, 95, 'What does a linker do?', 'it combines object files and libraries into a final executable', 'it translates source into assembly', 'it runs the program', 'it tests the program', 'D', 'The linker resolves references between object files and libraries, producing the final executable.', 'BEGINNER', 1, 'MCQ', 1),
(3275, 95, 'What is a lexer or scanner in a compiler?', 'the stage that breaks source text into tokens', 'the stage that optimizes code', 'the stage that runs the program', 'the stage that loads libraries', 'A', 'The lexical analyzer reads the source characters and groups them into meaningful tokens.', 'BEGINNER', 1, 'MCQ', 1),
(3276, 95, 'What is a parser in a compiler?', 'the stage that builds a syntax tree from the token stream', 'the stage that prints errors', 'the stage that links objects', 'the stage that executes code', 'B', 'The parser consumes the tokens and constructs a parse tree according to the grammar of the language.', 'BEGINNER', 1, 'MCQ', 1),
(3277, 95, 'What is a symbol table in an assembler or compiler?', 'a structure recording identifiers, labels and their attributes', 'a table of interrupts', 'a memory allocation table', 'a disk layout', 'C', 'A symbol table stores information about every identifier and label, such as its type and address.', 'BEGINNER', 1, 'MCQ', 1),
(3278, 95, 'What does the lex phase of a classic two-pass assembler do?', 'it assigns addresses to labels and expands instructions', 'it executes the program', 'it loads the program', 'it debugs the program', 'D', 'The first pass scans the source, computes the address of each label and fills in the symbol table.', 'BEGINNER', 1, 'MCQ', 1),
(3279, 95, 'What is an opcode?', 'The part of a machine instruction that specifies the operation to be performed', 'A high-level keyword', 'A data type', 'A linker option', 'A', 'The opcode is the field of a machine instruction that tells the CPU which operation, such as add or load, to execute.', 'BEGINNER', 1, 'MCQ', 1),
(3280, 95, 'Which phase of a compiler checks that variables are declared before use?', 'semantic analysis', 'lexing', 'linking', 'execution', 'B', 'Semantic analysis verifies that expressions and uses of identifiers are meaningful and type-correct.', 'BEGINNER', 1, 'MCQ', 1),
(3281, 95, 'Why does a classic assembler need two passes over the source?', 'labels can be used before they are defined, so addresses must be computed in a first pass', 'to make the code faster', 'to check spelling', 'to save memory', 'C', 'Since a label may be referenced before its definition, the first pass computes addresses and the second pass generates code.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3282, 95, 'What is a relocation entry in an object file?', 'information about addresses that must be adjusted when the file is linked at a different base address', 'a symbol table entry', 'an error message', 'a debug note', 'D', 'Relocations record where a link-time address fixup is required so the final executable can be placed in memory correctly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3283, 95, 'What is the difference between compilation and interpretation?', 'compilation translates the whole program ahead of time, while interpretation executes source statement by statement', 'compilation runs faster always', 'interpretation never errors', 'there is no difference', 'A', 'A compiler translates the full program into a native or intermediate form before execution, whereas an interpreter executes source directly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3284, 95, 'What is the purpose of intermediate code generation in a compiler?', 'to provide a language- and machine-independent representation that eases optimization and retargeting', 'to make the source unreadable', 'to run the program', 'to delete temporary files', 'B', 'A common intermediate representation lets optimizations be shared and lets the same front end target many back ends.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3285, 95, 'Which statement about labels in assembly is true?', 'a label is a symbolic name for an address, and forward references require a two-pass approach', 'labels cannot be referenced', 'labels are machine instructions', 'labels hold data', 'C', 'Labels name addresses, and because they may be referenced before definition, a two-pass process resolves them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3286, 95, 'What does the .text section of an object file contain?', 'the executable machine code', 'initialized data', 'the symbol table', 'the header', 'D', 'The .text section holds the program''s executable instructions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3287, 95, 'What is the main job of the code generator phase?', 'to translate the intermediate representation into target machine instructions', 'to tokenize the source', 'to link libraries', 'to test the program', 'A', 'The code generator maps the intermediate representation to actual instructions of the target processor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3288, 95, 'Why do assemblers convert labels into numeric addresses?', 'the CPU can only execute numeric addresses and opcodes', 'labels are easier for the CPU', 'the CPU ignores labels', 'labels are machine code', 'B', 'Machine instructions require numeric operands, so labels must be resolved to concrete addresses.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3289, 95, 'What is a macro in assembly language?', 'a named block of instructions that is expanded at each point of use during assembly', 'a system call', 'a data type', 'a memory address', 'C', 'A macro is expanded textually at each invocation, generating the same sequence of instructions each time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3290, 95, 'What happens during the linking phase when a symbol is undefined?', 'the linker reports an error and cannot produce the executable', 'the linker creates it', 'the program runs anyway', 'the symbol is ignored', 'D', 'If a referenced symbol has no definition, the linker fails with an undefined reference error.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3291, 95, 'What is the purpose of the register allocation phase in a compiler?', 'to map the many temporary values of a program onto the limited number of CPU registers', 'to delete registers', 'to slow the program', 'to add new instructions', 'A', 'Register allocation decides which values live in registers and which must be spilled to memory, greatly affecting speed.', 'ADVANCED', 3, 'MCQ', 1),
(3292, 95, 'What does an optimizing compiler do with a loop whose result is unused?', 'it may eliminate the loop entirely as dead code', 'it always keeps it', 'it doubles it', 'it converts it to a function', 'B', 'Dead code elimination removes computations whose results are never used, so the loop may vanish.', 'ADVANCED', 3, 'MCQ', 1),
(3293, 95, 'Why might a compiler reorder instructions that do not appear to be related?', 'to increase instruction-level parallelism and hide memory latency', 'to confuse readers', 'to reduce file size', 'to break the program', 'C', 'Instruction scheduling reorders independent operations to overlap latency and improve pipeline utilization.', 'ADVANCED', 3, 'MCQ', 1),
(3294, 95, 'What is an assembler directive?', 'an instruction to the assembler itself, such as reserving data or setting an origin, not executed by the CPU', 'a CPU instruction', 'a system call', 'an interrupt', 'D', 'Directives tell the assembler how to build output, such as reserving storage, without producing executable machine code.', 'ADVANCED', 3, 'MCQ', 1),
(3295, 95, 'What is the risk of relying on an uninitialized local variable in compiled code?', 'it holds an unpredictable value, making behavior undefined', 'it always holds zero', 'it holds the stack base', 'it cannot be read', 'A', 'Reading an uninitialized local is undefined, since it contains whatever garbage was on the stack.', 'ADVANCED', 3, 'MCQ', 1),
(3296, 95, 'How does a just-in-time (JIT) compiler differ from a traditional compiler?', 'it compiles code at runtime rather than ahead of execution, enabling profile-based optimization', 'it runs slower', 'it never optimizes', 'it produces only assembly', 'B', 'A JIT compiles methods when they are about to run, allowing it to optimize based on actual runtime behavior.', 'ADVANCED', 3, 'MCQ', 1),
(3297, 95, 'What does the -O2 flag typically tell a C compiler to do?', 'apply a standard set of optimizations that improve speed without breaking semantics', 'disable all checks', 'add debugging symbols only', 'compile without a linker', 'C', 'The -O2 level enables a well-tested optimization suite that speeds up the generated code.', 'ADVANCED', 3, 'MCQ', 1),
(3298, 95, 'Why is peephole optimization valuable?', 'it replaces short sequences of generated code with faster equivalents after code generation', 'it rewrites the parser', 'it speeds up the lexer', 'it removes the linker', 'D', 'Peephole optimization inspects small windows of generated instructions and substitutes better ones, improving efficiency cheaply.', 'ADVANCED', 3, 'MCQ', 1),
(3299, 95, 'What is the danger of signed integer overflow being treated as an optimization opportunity?', 'compilers may assume overflow never happens and transform code in ways that surprise developers', 'the program always works', 'overflow is always caught', 'the CPU handles it perfectly', 'A', 'Because overflow is undefined, compilers can assume it does not occur and may remove or alter code that relies on wrapping behavior.', 'ADVANCED', 3, 'MCQ', 1),
(3300, 95, 'What is a cross-compiler?', 'a compiler that runs on one platform but produces code for a different target platform', 'a compiler that runs only on Windows', 'a compiler with no optimizer', 'a compiler that interprets source', 'B', 'A cross-compiler builds binaries for a target machine that differs from the machine the compiler runs on.', 'ADVANCED', 3, 'MCQ', 1),
(3301, 96, 'Which component of Windows abstracts hardware differences so the OS runs on diverse hardware platforms?', 'Hardware Abstraction Layer (HAL)', 'Plug and Play Manager', 'Object Manager', 'Win32k.sys', 'A', 'The HAL hides hardware-specific details from the kernel so the same kernel code runs across many hardware platforms.', 'BEGINNER', 1, 'MCQ', 1),
(3302, 96, 'In which mode do the Windows kernel and its device drivers execute?', 'user mode', 'kernel mode', 'compatibility mode', 'protected mode', 'B', 'The kernel and drivers run in kernel mode, which gives direct access to hardware and privileged instructions.', 'BEGINNER', 1, 'MCQ', 1),
(3303, 96, 'What is the name of the executable image of the core Windows executive and kernel?', 'kernel32.dll', 'ntdll.dll', 'ntoskrnl.exe', 'winlogon.exe', 'C', 'ntoskrnl.exe is the main kernel image that provides the executive services and the kernel layer.', 'BEGINNER', 1, 'MCQ', 1),
(3304, 96, 'Which Windows environment subsystem provides the classic Win32 application programming interface?', 'WSL', 'POSIX', 'OS/2', 'Win32', 'D', 'The Win32 subsystem is the primary environment subsystem that Win32 applications are written against.', 'BEGINNER', 1, 'MCQ', 1),
(3305, 96, 'What does an application use to request services from the Windows kernel?', 'system calls', 'API drivers', 'shared memory only', 'COM objects', 'A', 'User-mode programs make system calls to request kernel services such as file I/O and process creation.', 'BEGINNER', 1, 'MCQ', 1),
(3306, 96, 'Which component implements the graphics and window management portion on the kernel-mode side of Windows?', 'GDI driver', 'win32k.sys', 'csrss.exe', 'explorer.exe', 'B', 'win32k.sys is the kernel-mode component that implements the window manager and graphics device interface.', 'BEGINNER', 1, 'MCQ', 1),
(3307, 96, 'Which of the following runs in user mode?', 'the HAL', 'the process manager', 'the Windows API DLLs', 'the I/O manager', 'C', 'API DLLs such as kernel32.dll execute in user mode while the HAL, process manager and I/O manager are kernel-mode.', 'BEGINNER', 1, 'MCQ', 1),
(3308, 96, 'What is the primary role of the Windows executive services layer?', 'providing the graphical interface', 'managing user passwords', 'providing high-level OS services built on the kernel', 'compiling user programs', 'D', 'The executive implements high-level services such as process, memory and I/O management on top of the kernel.', 'BEGINNER', 1, 'MCQ', 1),
(3309, 96, 'Which Windows process is the user-mode root of the Win32 subsystem and manages console windows?', 'csrss.exe', 'smss.exe', 'lsass.exe', 'services.exe', 'A', 'csrss.exe is the Client/Server Runtime Subsystem that handles console windows and Win32 base services.', 'BEGINNER', 1, 'MCQ', 1),
(3310, 96, 'What protects kernel-mode code from being modified by user-mode programs?', 'User Account Control', 'privilege separation between user and kernel mode', 'the registry', 'system restore', 'B', 'Separating user and kernel modes means user code cannot execute privileged instructions or touch kernel memory.', 'BEGINNER', 1, 'MCQ', 1),
(3311, 96, 'When a user-mode program needs hardware access, which order does the request typically follow?', 'directly to the hardware', 'through the registry then the CPU', 'user-mode API, system call, kernel executive, driver, and then the hardware', 'through explorer.exe then the HAL', 'C', 'Requests flow from a user API through a system call into the executive, which dispatches to the appropriate driver.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3312, 96, 'Why does Windows run most system-critical code in kernel mode?', 'it speeds up user interface rendering', 'it simplifies debugging', 'it reduces memory usage', 'kernel mode is needed for privileged operations such as direct hardware and memory control', 'D', 'Only kernel mode can execute privileged instructions and access protected memory needed to manage the system.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3313, 96, 'What happens when a user-mode thread executes a privileged instruction?', 'a processor exception or trap is raised, handled by the kernel', 'the instruction executes normally', 'the system reboots', 'the thread is silently ignored', 'A', 'The CPU raises a trap that transfers control to the kernel, which can then handle or reject the operation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3314, 96, 'Which of these components is part of the Windows executive layer?', 'thread scheduling', 'the process and thread manager', 'interrupt dispatch', 'exception dispatching', 'B', 'The process and thread manager is an executive component, while scheduling and interrupt handling live in the kernel.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3315, 96, 'What is the purpose of the Object Manager in Windows?', 'to draw windows on screen', 'to compress files', 'to manage named kernel objects and maintain a uniform namespace', 'to enforce file permissions only', 'C', 'The Object Manager tracks kernel objects such as processes, files and devices and gives them a common naming scheme.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3316, 96, 'A hardware device needs immediate attention; which mechanism lets the kernel respond quickly?', 'polling every second', 'the desktop heap', 'interrupt handling via the kernel''s interrupt dispatch', 'user-mode timers', 'D', 'Interrupts let devices signal the kernel immediately, and the kernel''s interrupt dispatch handles them promptly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3317, 96, 'Which layer translates processor-specific operations such as cache and interrupt management into generic routines?', 'the Hardware Abstraction Layer (HAL)', 'win32k.sys', 'the session manager', 'the security reference monitor', 'A', 'The HAL abstracts platform-specific CPU details so the kernel can use generic interfaces.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3318, 96, 'Which process is responsible for starting the Windows session and creating the subsystem processes at boot?', 'winlogon.exe', 'smss.exe (Session Manager)', 'svchost.exe', 'taskmgr.exe', 'B', 'smss.exe is the Session Manager that starts the Win32 subsystem and Winlogon during boot.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3319, 96, 'Why are most kernel-mode components compiled into a single file rather than spread across many DLLs?', 'because DLLs cannot be loaded in kernel mode', 'for faster startup of user programs', 'a monolithic kernel reduces inter-component call overhead and simplifies boot', 'because the filesystem requires it', 'C', 'Keeping core kernel components in ntoskrnl.exe avoids expensive cross-module calls and simplifies boot time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3320, 96, 'In modern Windows, what is the typical entry point for a user-mode system call?', 'a direct hardware instruction', 'the registry', 'a COM object', 'the system service dispatch table reached through ntdll', 'D', 'ntdll provides stubs that invoke the system service dispatch table in the kernel for each system call.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3321, 96, 'A driver must respond to a time-critical hardware event with minimal delay. What is the most appropriate mechanism?', 'polling in a user-mode loop', 'a background registry scan', 'an interrupt service routine or deferred procedure call at the appropriate IRQL', 'a Windows service timer', 'D', 'ISRs and DPCs give drivers the low-latency response hardware events require, unlike timers or polling.', 'ADVANCED', 3, 'MCQ', 1),
(3322, 96, 'Why can Win32 subsystem processes such as csrss.exe not be safely terminated at runtime?', 'it manages console handling and critical base API services used by many processes', 'it holds the registry hive', 'it is the only process with kernel access', 'it is protected by the file system', 'A', 'Terminating csrss.exe breaks the Win32 base services that the rest of the system depends on, destabilizing Windows.', 'ADVANCED', 3, 'MCQ', 1),
(3323, 96, 'During a Windows crash, what file captures kernel memory so the issue can be debugged?', 'pagefile.sys', 'MEMORY.DMP', 'winlogon.exe', 'ntuser.dat', 'B', 'A memory dump file such as MEMORY.DMP records the state of kernel memory at the time of the crash for analysis.', 'ADVANCED', 3, 'MCQ', 1),
(3324, 96, 'Which design change in modern Windows reduces the attack surface by isolating critical processes from each other?', 'enabling compatibility mode', 'running everything in kernel mode', 'process isolation and services running in separate sessions and containers', 'disabling the scheduler', 'C', 'Isolating processes and services limits what an attacker can reach if one component is compromised.', 'ADVANCED', 3, 'MCQ', 1),
(3325, 96, 'What is the primary function of the Session Manager (smss.exe) during boot?', 'rendering the login screen', 'managing paging files', 'running user applications', 'creating the initial session and starting the Win32 subsystem and Winlogon', 'D', 'smss.exe initializes the system session and launches the subsystem and login components during boot.', 'ADVANCED', 3, 'MCQ', 1),
(3326, 96, 'A developer loads a kernel driver and the machine bluescreens immediately. What is the most likely cause?', 'the driver ran in kernel mode and executed an invalid operation, crashing the whole system', 'the driver was compiled in user mode', 'the registry is corrupt', 'the HAL is missing', 'A', 'Kernel-mode faults are fatal, so an invalid driver operation brings down the entire system.', 'ADVANCED', 3, 'MCQ', 1),
(3327, 96, 'Which statement best describes how system calls are dispatched on modern x64 Windows?', 'each call is handled by a separate DLL', 'calls go through the kernel only at boot', 'the syscall instruction transfers control to the system service dispatch table in the kernel', 'calls are emulated by the CPU', 'B', 'On x64 the syscall instruction jumps directly into the kernel''s service dispatch table, avoiding an interrupt handler.', 'ADVANCED', 3, 'MCQ', 1),
(3328, 96, 'Why is the Hardware Abstraction Layer considered essential for server and OEM deployments?', 'it speeds up the GUI', 'it stores user passwords', 'it lets one binary of Windows run across CPUs with different timer and interrupt behavior', 'it handles networking', 'C', 'The HAL abstracts platform differences so a single Windows build works on a wide range of hardware.', 'ADVANCED', 3, 'MCQ', 1),
(3329, 96, 'In a system where a misbehaving driver corrupts memory, why does Windows generally crash rather than just failing that driver?', 'because drivers are optional', 'because kernel memory corruption can affect any process and the system cannot guarantee safe continuation', 'because the scheduler stops', 'because the registry is erased', 'D', 'Corrupted kernel memory makes further operation unreliable, so a bugcheck is the safe response.', 'ADVANCED', 3, 'MCQ', 1),
(3330, 96, 'What does the Memory Manager contribution to the executive provide that is essential for every process?', 'private virtual address spaces and paged virtual memory', 'the graphical desktop', 'kernel symbol files', 'the boot menu', 'A', 'The Memory Manager gives each process an isolated virtual address space backed by physical memory and the paging file.', 'ADVANCED', 3, 'MCQ', 1),
(3331, 97, 'What is the basic unit of execution scheduled by the Windows kernel?', 'thread', 'process', 'session', 'job', 'A', 'Threads are the schedulable units, while a process is a container for resources and threads.', 'BEGINNER', 1, 'MCQ', 1),
(3332, 97, 'Which term describes a container holding a virtual address space and the threads that run within it?', 'module', 'process', 'job object', 'file mapping', 'B', 'A process provides the virtual address space, resources and security context for its threads.', 'BEGINNER', 1, 'MCQ', 1),
(3333, 97, 'What does the Windows scheduler decide?', 'which colors to display', 'how to partition the disk', 'which thread runs next on a processor', 'which files to defragment', 'C', 'The scheduler selects which thread should execute next on each available processor.', 'BEGINNER', 1, 'MCQ', 1),
(3334, 97, 'What is a handle in Windows?', 'a kernel password', 'an opaque reference to a kernel object such as a process or file', 'a block of memory', 'a system call', 'D', 'A handle is an opaque value that lets a process reference a kernel object without direct pointer access.', 'BEGINNER', 1, 'MCQ', 1),
(3335, 97, 'Which API function creates a new process in the Win32 API?', 'CreateProcess', 'StartThread', 'NewProc', 'MakeProcess', 'A', 'CreateProcess is the Win32 function that creates a new process and its primary thread.', 'BEGINNER', 1, 'MCQ', 1),
(3336, 97, 'What is the primary difference between a stack and a heap?', 'stack is shared between threads', 'a stack is per-thread and automatic while the heap is shared memory that must be managed', 'they are identical', 'the heap is faster', 'B', 'Each thread has its own automatic stack, while the heap is shared and requires explicit allocation and freeing.', 'BEGINNER', 1, 'MCQ', 1),
(3337, 97, 'Which file extensions are used for a Windows executable or DLL?', 'EXE only', 'BIN', 'EXE and DLL', 'TMP', 'C', 'Both EXE and DLL files use the PE format and are the standard executable images on Windows.', 'BEGINNER', 1, 'MCQ', 1),
(3338, 97, 'What happens to a process when its last thread finishes?', 'it continues running', 'it becomes a zombie until reboot', 'the process terminates and its resources are released', 'it is suspended', 'D', 'When the final thread exits, the process terminates and its resources are reclaimed by the system.', 'BEGINNER', 1, 'MCQ', 1),
(3339, 97, 'Which Windows mechanism lets two processes share a region of memory efficiently?', 'memory-mapped files', 'the registry', 'the clipboard', 'environment variables', 'A', 'Memory-mapped files let multiple processes map the same region of memory into their address spaces.', 'BEGINNER', 1, 'MCQ', 1),
(3340, 97, 'What is the virtual address space of a process?', 'the amount of RAM installed', 'the range of addresses the process can reference, backed by RAM or paging storage', 'the hard disk space', 'the CPU cache', 'B', 'A process can reference addresses within its virtual address space, which is backed by physical memory and the paging file.', 'BEGINNER', 1, 'MCQ', 1),
(3341, 97, 'A program reserves a large region of virtual memory but has not yet used it. How does Windows avoid allocating physical memory immediately?', 'compress memory to disk', 'reserve memory only and commit pages on demand', 'allocate the full region as RAM', 'disable paging', 'C', 'Windows uses reserved-then-committed memory so physical pages are only allocated when first accessed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3342, 97, 'Which Windows component translates virtual addresses to physical addresses?', 'the scheduler', 'winlogon', 'the registry', 'the memory manager and page tables', 'D', 'The memory manager maintains page tables that map each process''s virtual pages to physical frames.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3343, 97, 'When physical RAM runs low, what does Windows typically do?', 'trim working sets and write pages to the paging file', 'shut down applications', 'reboot the machine', 'increase the processor speed', 'A', 'The memory manager trims process working sets and pages out less-used data to relieve memory pressure.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3344, 97, 'What is the paging file used for in Windows?', 'To store memory pages temporarily moved out of physical RAM', 'To hold user documents', 'To store device drivers', 'To keep the registry', 'A', 'The paging file backs virtual memory by holding pages that have been evicted from physical RAM, freeing memory for other uses.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3345, 97, 'Which structures describe a thread''s state, stack and context and are maintained by the system?', 'a TEB only', 'the PEB', 'a thread control block and the thread environment block (TEB)', 'a job object', 'C', 'The kernel tracks each thread with a control block and user-mode data in the TEB.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3346, 97, 'Which value determines how often a thread gets the CPU relative to others at the same base priority?', 'its token', 'its stack size', 'its handle', 'its dynamic priority, which the scheduler boosts based on activity', 'D', 'The scheduler adjusts dynamic priorities so interactive threads get CPU sooner than idle ones.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3347, 97, 'A process allocates a large buffer with VirtualAlloc but never touches most of it. What is the expected behavior?', 'only the touched pages are committed to physical memory', 'all of it is forced into RAM', 'the buffer is written to the registry', 'the system reserves extra RAM', 'A', 'Committed pages become resident only on first access, so untouched portions consume little physical memory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3348, 97, 'Which Windows feature randomizes where executables and DLLs load in memory to thwart attacks?', 'BitLocker', 'ASLR (Address Space Layout Randomization)', 'the paging file', 'NTFS', 'B', 'ASLR randomizes image base addresses so exploits cannot rely on fixed addresses.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3349, 97, 'What is the purpose of the Process Environment Block (PEB)?', 'storing kernel objects', 'scheduling threads', 'holding user-mode process data such as image path, environment and loader data', 'managing the registry', 'C', 'The PEB is a user-mode structure containing process-wide information such as the module list and environment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3350, 97, 'Which statement about threads sharing the same process is correct?', 'they each get a separate address space', 'they cannot run concurrently', 'they share the process address space but have their own stack and registers', 'they must run on different CPUs', 'D', 'Threads in one process share the address space and resources while keeping private stacks and register state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3351, 97, 'A server needs to run thousands of concurrent tasks cheaply. What is the most efficient Windows approach?', 'create a dedicated process per task', 'increase the pagefile', 'use the thread pool and I/O completion ports', 'disable memory-mapped files', 'D', 'A thread pool with I/O completion ports scales to many concurrent operations without a thread per task.', 'ADVANCED', 3, 'MCQ', 1),
(3352, 97, 'Why is a context switch more expensive than a simple function call?', 'the kernel must save registers, switch address spaces if needed, and update scheduler state', 'because the CPU reboots', 'because the registry is accessed', 'because the hard disk spins up', 'A', 'A context switch involves privileged work to save the outgoing thread''s state and restore the next thread''s state.', 'ADVANCED', 3, 'MCQ', 1),
(3353, 97, 'An application must pass a large data buffer between two processes without copying it twice. Which technique is best?', 'write it to a file and read it back', 'use a shared memory-mapped file region', 'send it through the clipboard', 'store it in the registry', 'B', 'A shared memory-mapped file lets both processes access the same pages, avoiding extra data copies.', 'ADVANCED', 3, 'MCQ', 1),
(3354, 97, 'What is the main risk of a process whose committed virtual memory grows without bound?', 'it gets faster', 'it becomes unkillable', 'the paging file and physical memory can be exhausted, causing system-wide slowdown or failure', 'its threads are suspended', 'C', 'Unbounded commits exhaust memory and paging space, which can destabilize the entire system.', 'ADVANCED', 3, 'MCQ', 1),
(3355, 97, 'Which mechanism prevents one process from corrupting another process''s address space?', 'software protection', 'per-process virtual address spaces enforced by page tables', 'the registry', 'the firewall', 'D', 'Each process has its own page tables, so its addresses do not map to another process''s physical memory.', 'ADVANCED', 3, 'MCQ', 1),
(3356, 97, 'A thread calls ExitThread; what immediately happens?', 'the thread terminates and its objects and stack are cleaned up when its handles close', 'the whole process exits', 'the system reboots', 'the thread sleeps forever', 'A', 'ExitThread ends the calling thread, and the kernel cleans up its resources once all handles are closed.', 'ADVANCED', 3, 'MCQ', 1),
(3357, 97, 'Which scenario best explains ''thrashing''?', 'a CPU overheating', 'heavy swapping in which the system spends more time moving pages than doing useful work', 'a network outage', 'a driver signing issue', 'B', 'Thrashing occurs when the working sets exceed physical memory and the system continuously pages data in and out.', 'ADVANCED', 3, 'MCQ', 1),
(3358, 97, 'To maximize throughput for a CPU-bound workload on a many-core machine, what does the scheduler try to maintain?', 'one thread per process', 'cache locality by keeping threads on the same processor when possible', 'equal CPU counts', 'a single queue', 'C', 'Keeping threads on the same processor preserves warm caches and reduces migration overhead.', 'ADVANCED', 3, 'MCQ', 1),
(3359, 97, 'A background process must do work every 30 minutes without keeping a thread always resident. What is the most efficient mechanism?', 'an infinite loop thread', 'a busy-wait timer', 'a dedicated GPU process', 'wait timers that wake only when needed', 'D', 'Waitable timers let the thread sleep and be woken by the kernel only when the work is due.', 'ADVANCED', 3, 'MCQ', 1),
(3360, 97, 'Which statement about the Thread Environment Block (TEB) is correct?', 'it stores per-thread user-mode data such as the stack base and thread-local storage', 'it is shared by all processes', 'it is stored on the heap', 'it contains the kernel scheduler queue', 'A', 'The TEB holds thread-local user-mode information like stack limits and the thread-local storage array.', 'ADVANCED', 3, 'MCQ', 1),
(3361, 98, 'Which registry hive contains settings specific to the current logged-in user?', 'HKEY_CURRENT_USER', 'HKEY_LOCAL_MACHINE', 'HKEY_CLASSES_ROOT', 'HKEY_DYN_DATA', 'A', 'HKEY_CURRENT_USER stores per-user configuration such as desktop settings and application preferences.', 'BEGINNER', 1, 'MCQ', 1),
(3362, 98, 'Which registry hive stores machine-wide configuration?', 'HKEY_CURRENT_USER', 'HKEY_LOCAL_MACHINE', 'HKEY_CURRENT_CONFIG', 'HKEY_USERS', 'B', 'HKEY_LOCAL_MACHINE holds settings that apply to the entire machine regardless of the logged-in user.', 'BEGINNER', 1, 'MCQ', 1),
(3363, 98, 'What is a registry hive?', 'a type of virus', 'a set of registry keys, subkeys and values backed by a file such as SAM or SOFTWARE', 'a user profile', 'a type of DLL', 'C', 'A hive is a logical group of registry data persisted to a backing file on disk.', 'BEGINNER', 1, 'MCQ', 1),
(3364, 98, 'Which tool is used to edit the registry on Windows?', 'explorer.exe', 'taskmgr.exe', 'cmd.exe', 'regedit.exe', 'D', 'regedit.exe is the registry editor that displays and modifies registry keys and values.', 'BEGINNER', 1, 'MCQ', 1),
(3365, 98, 'What is an Access Control List (ACL) used for?', 'granting or denying users access to objects such as files and registry keys', 'listing installed programs', 'storing passwords in plain text', 'managing IP addresses', 'A', 'ACLs define which users or groups may access an object and what operations they may perform.', 'BEGINNER', 1, 'MCQ', 1),
(3366, 98, 'Which account has the most privileges on a Windows machine by default?', 'Guest', 'Administrator', 'Standard User', 'Network Service', 'B', 'The Administrator account has the broadest privileges, including changing system-wide settings.', 'BEGINNER', 1, 'MCQ', 1),
(3367, 98, 'What is the purpose of User Account Control (UAC)?', 'to speed up login', 'to replace the firewall', 'to prompt for consent or credentials when a program needs administrator privileges', 'to manage updates', 'C', 'UAC asks for confirmation or credentials before allowing a process to run with elevated privileges.', 'BEGINNER', 1, 'MCQ', 1),
(3368, 98, 'Which Windows service authenticates users and grants them access tokens?', 'explorer', 'LSA (Local Security Authority)', 'spooler', 'search', 'D', 'The Local Security Authority authenticates users and creates the security tokens they use for access checks.', 'BEGINNER', 1, 'MCQ', 1),
(3369, 98, 'What is a security identifier (SID)?', 'a unique value that identifies a user, group or computer account', 'a password', 'a MAC address', 'a registry value', 'A', 'A SID uniquely identifies an account within a Windows domain or local machine.', 'BEGINNER', 1, 'MCQ', 1),
(3370, 98, 'Which statement about the SAM database is correct?', 'it stores the registry editor', 'it stores local user account and password hash information', 'it is a web browser', 'it manages GPU drivers', 'B', 'The Security Accounts Manager stores local user accounts, groups and password hashes.', 'BEGINNER', 1, 'MCQ', 1),
(3371, 98, 'A standard user needs to run an installer that requires elevation. What does UAC do?', 'blocks it forever', 'runs it without privileges', 'displays a consent prompt so an administrator can approve or credentials can be supplied', 'silently elevates every time', 'C', 'UAC shows a consent or credential prompt, and only then does the process run elevated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3372, 98, 'Which registry data type stores a 32-bit integer?', 'REG_SZ', 'REG_BINARY', 'REG_EXPAND_SZ', 'REG_DWORD', 'D', 'REG_DWORD is the registry type for a 32-bit integer value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3373, 98, 'What is the difference between a DACL and a SACL?', 'a DACL controls access permissions while a SACL controls auditing', 'they are identical', 'a SACL stores passwords', 'a DACL is only for the registry', 'A', 'A DACL grants or denies access, while a SACL specifies which accesses are audited in the security log.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3374, 98, 'Why should critical secrets such as passwords not be stored in the registry as plain text?', 'the registry is too slow', 'plain text secrets can be read by any process with read access, so they should be protected or stored elsewhere', 'the registry cannot store text', 'because regedit is slow', 'B', 'Storing secrets in plain text lets any process with registry read access exfiltrate them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3375, 98, 'Which mechanism does Windows use to grant a process the rights associated with its logged-in user?', 'the clipboard', 'environment variables', 'an access token that carries the user''s privileges and group memberships', 'the desktop wallpaper', 'C', 'Each process has an access token describing the user and groups, which the security subsystem checks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3376, 98, 'Which registry path is typically used by a Windows service to store its settings?', 'HKCR', 'HKCU Software only', 'HKLM Hardware', 'HKLM System CurrentControlSet Services', 'D', 'Service configuration lives under HKLM System CurrentControlSet Services on the local machine.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3377, 98, 'What is the primary purpose of combining a SACL with security event logging?', 'auditing who attempted to access an object and whether they succeeded', 'speeding up the hard drive', 'defragmenting keys', 'caching login passwords', 'A', 'SACL entries trigger audit events that record successful and failed access attempts for review.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3378, 98, 'Which feature signs kernel drivers to prevent untrusted code from loading?', 'UAC', 'driver signature enforcement and Secure Boot', 'the registry', 'Task Manager', 'B', 'Driver signature enforcement and Secure Boot require kernel drivers to be signed by a trusted publisher.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3379, 98, 'Why is it dangerous to grant a standard user membership in the Administrators group?', 'they cannot log in', 'their programs will not run', 'malware running as that user gains administrator-level control of the machine', 'the registry is deleted', 'C', 'Membership in Administrators gives any code running as that user full control over the machine.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3380, 98, 'What does the registry''s Last Known Good Configuration store?', 'the last password', 'the user''s last document', 'a backup of all files', 'the last successful boot configuration, used to recover from bad changes', 'D', 'The Last Known Good configuration captures the settings from the last successful boot for recovery.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3381, 98, 'Malware adds an autostart entry to persist after reboot. Which registry location is most likely used?', 'HKCR dot exe', 'HKEY_DYN_DATA', 'HKLM SAM', 'the Run and Services keys under the current user or machine hive', 'D', 'Run keys and service definitions are common persistence points that the system loads at login or boot.', 'ADVANCED', 3, 'MCQ', 1),
(3382, 98, 'When a process tries to open a file, in what order does the security check occur?', 'the reference monitor checks the requested access against the object''s DACL using the caller''s token', 'the file is opened then checked', 'the registry is consulted first', 'no check occurs', 'A', 'The Security Reference Monitor validates the caller''s token against the object''s DACL before access is granted.', 'ADVANCED', 3, 'MCQ', 1),
(3383, 98, 'Why is a token associated with a process rather than with the code that runs?', 'code is not secure', 'privileges must be tied to the user context that started the process, not to the code', 'because tokens are files', 'because the scheduler requires it', 'B', 'Access decisions are based on the user who launched the process, so the token reflects that user context.', 'ADVANCED', 3, 'MCQ', 1),
(3384, 98, 'Which approach best protects registry configuration for a critical service?', 'give Everyone full control', 'disable the service', 'restrict the ACL to the service account and administrators, and back up the hive', 'store passwords in the key', 'C', 'Restricting the ACL minimizes who can alter the service settings, and backups enable recovery.', 'ADVANCED', 3, 'MCQ', 1),
(3385, 98, 'What is the effect of marking an ordinary program to always ''Run as administrator''?', 'it weakens the program', 'it forces the program to always run elevated, increasing risk if the program is exploited', 'it deletes the registry', 'it blocks the program', 'D', 'Always running elevated means a compromise of that program immediately yields full system privileges.', 'ADVANCED', 3, 'MCQ', 1),
(3386, 98, 'During an investigation, where should an analyst look first to confirm which programs run at login?', 'Run keys, the Startup folder, and scheduled tasks', 'the Recycle Bin', 'the paging file only', 'the boot menu', 'A', 'Run registry keys, the Startup folder and scheduled tasks are the standard places autostart entries are registered.', 'ADVANCED', 3, 'MCQ', 1),
(3387, 98, 'Why does Windows restrict access to the SAM hive even to administrators?', 'to save disk space', 'to prevent offline password hash extraction by users who are not the system account', 'to speed up boot', 'to reduce CPU load', 'B', 'The SAM contains password hashes, so only the system account can read it to prevent credential theft.', 'ADVANCED', 3, 'MCQ', 1),
(3388, 98, 'A security engineer wants to know which user attempted to delete a sensitive registry key. What must be configured?', 'UAC', 'BitLocker', 'a SACL audit entry on the key plus the security audit policy', 'the paging file', 'C', 'Auditing the key with a SACL entry and enabling the audit policy records deletion attempts in the event log.', 'ADVANCED', 3, 'MCQ', 1),
(3389, 98, 'Which statement about the built-in local Administrator account is most accurate for hardened systems?', 'everyone should use the default Administrator always', 'it should be left unchanged', 'the built-in Administrator should be renamed and disabled, and local accounts limited', 'it is required for updates', 'D', 'Renaming and disabling the built-in Administrator reduces the risk of credential-based attacks against a known account.', 'ADVANCED', 3, 'MCQ', 1),
(3390, 98, 'How does the Security Reference Monitor relate to other components?', 'it centralizes access checks so all objects are validated against the caller''s token and the object''s ACL', 'it draws windows', 'it schedules threads', 'it compresses the registry', 'A', 'The reference monitor is the single point through which all object access checks pass, enforcing consistent security.', 'ADVANCED', 3, 'MCQ', 1),
(3391, 99, 'Which kernel forms the foundation of both iOS and macOS?', 'XNU', 'Linux', 'MS-DOS', 'FreeBSD userland only', 'A', 'XNU is Apple''s hybrid kernel derived from Mach and BSD that powers both iOS and macOS.', 'BEGINNER', 1, 'MCQ', 1),
(3392, 99, 'Which company develops the Android operating system?', 'Apple', 'Google', 'Microsoft', 'IBM', 'B', 'Android is developed by Google, built on a Linux kernel and a large app ecosystem.', 'BEGINNER', 1, 'MCQ', 1),
(3393, 99, 'What is the primary user interface framework for iOS apps?', 'UIKit', 'Win32', 'Cocoa', 'GTK', 'C', 'UIKit provides the views, controls and lifecycle support that iOS apps are built with.', 'BEGINNER', 1, 'MCQ', 1),
(3394, 99, 'What file format packages a macOS application so it can be moved as one unit?', 'APK', 'an app bundle', 'exe', 'deb', 'D', 'A macOS app is distributed as a .app bundle containing the executable, resources and metadata.', 'BEGINNER', 1, 'MCQ', 1),
(3395, 99, 'Which layer in iOS handles low-level networking and Unix services?', 'Darwin', 'Cocoa Touch', 'Media', 'Core Services', 'A', 'Darwin, the core OS layer, provides Unix services and networking underneath the higher iOS layers.', 'BEGINNER', 1, 'MCQ', 1),
(3396, 99, 'Which language is Apple''s recommended modern language for iOS and macOS development?', 'Swift', 'COBOL', 'JavaScript', 'PHP', 'B', 'Swift is Apple''s modern, type-safe language designed for building apps across its platforms.', 'BEGINNER', 1, 'MCQ', 1),
(3397, 99, 'What is an Android APK?', 'a backup', 'a theme', 'the package format containing an app''s code and resources', 'a virus', 'C', 'An APK is the installable package that bundles an Android app''s code, assets and manifest.', 'BEGINNER', 1, 'MCQ', 1),
(3398, 99, 'Which component of Android executes an app''s compiled code?', 'the HAL', 'the launcher', 'the notification bar', 'the ART (Android Runtime)', 'D', 'ART is the Android Runtime that compiles and executes the bytecode of installed apps.', 'BEGINNER', 1, 'MCQ', 1),
(3399, 99, 'What does app sandboxing do on iOS and macOS?', 'restricts each app to its own container and limited system resources', 'lets apps access everything', 'speeds up the GPU', 'removes security checks', 'A', 'Sandboxing confines each app to its own container so it cannot access other apps'' data.', 'BEGINNER', 1, 'MCQ', 1),
(3400, 99, 'Which type of memory management is used by Swift''s ARC?', 'manual memory allocation only', 'automatic reference counting that frees objects when their references drop to zero', 'garbage collection', 'no memory management', 'B', 'ARC inserts retain and release operations so objects are deallocated automatically when no references remain.', 'BEGINNER', 1, 'MCQ', 1),
(3401, 99, 'A developer wants to run native C code on Android for performance. Which toolchain is used?', 'Xcode', 'Visual Studio', 'the Android NDK (Native Development Kit)', 'Cocoa', 'C', 'The NDK lets developers compile native C and C++ libraries for use in Android apps.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3402, 99, 'What happens to an iOS app that enters the background for an extended period?', 'it keeps running forever', 'it is deleted', 'it slows down the device', 'it is suspended and may be terminated by the system to reclaim memory', 'D', 'iOS suspends background apps and terminates them under memory pressure to keep the device responsive.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3403, 99, 'Which Android component is an activity?', 'a single focused screen the user interacts with', 'a background service', 'a content provider', 'an intent filter', 'A', 'An activity represents one user-facing screen with its own layout and lifecycle.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3404, 99, 'What is the purpose of Android''s Binder IPC?', 'rendering graphics', 'enabling efficient inter-process communication between apps and system services', 'managing the battery', 'compiling apps', 'B', 'Binder provides the fast, kernel-mediated channel that apps and system services use to talk to each other.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3405, 99, 'Which macOS technology lets multiple tasks run concurrently with low overhead?', 'Grand Central Dispatch (GCD)', 'the Finder', 'Spotlight', 'Time Machine', 'C', 'GCD manages thread pools and dispatch queues so work can run concurrently with little overhead.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3406, 99, 'What is FileVault on macOS?', 'a file compression tool', 'a web browser', 'a developer framework', 'full-disk encryption for the startup volume', 'D', 'FileVault encrypts the startup volume so data is unreadable without the proper credentials.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3407, 99, 'Which component handles permission requests for sensitive resources on macOS?', 'the TCC (Transparency, Consent, and Control) framework', 'the Dock', 'Safari', 'the App Store', 'A', 'TCC prompts users and grants or denies apps access to resources like camera, microphone and files.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3408, 99, 'What is the primary role of an Android app''s manifest file?', 'styling the UI', 'declaring components, permissions, and features the app requires', 'storing user data', 'signing the app', 'B', 'The manifest declares the app''s components, required permissions and features to the system.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3409, 99, 'Which statement about the iOS app lifecycle is correct?', 'apps can run unlimited work in the background', 'apps receive events like launch, resign active, and terminate, and should save state at transitions', 'apps never terminate', 'apps control the kernel', 'C', 'Apps move through defined lifecycle states and must persist state because they can be suspended or terminated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3410, 99, 'Why does Android typically run each app in its own Linux process?', 'to reduce RAM', 'to speed up the UI', 'to save battery', 'isolation and security between apps', 'D', 'Separate processes keep apps isolated so one app cannot read another app''s memory or data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3411, 99, 'A messaging app needs to receive notifications while closed. What is the recommended mobile approach?', 'run a polling thread forever', 'keep the screen on', 'use the platform push service such as APNs or FCM rather than a persistent background socket', 'disable the radio', 'D', 'Platform push services deliver messages efficiently without a battery-draining persistent connection.', 'ADVANCED', 3, 'MCQ', 1),
(3412, 99, 'Why do iOS background tasks have strict time limits?', 'background execution drains battery and memory, so the OS bounds it to keep the device responsive', 'to increase CPU speed', 'to prevent file writes', 'to simplify code signing', 'A', 'Limiting background work preserves battery life and keeps the device responsive for the user.', 'ADVANCED', 3, 'MCQ', 1),
(3413, 99, 'Which strategy reduces an Android app''s memory footprint when the OS kills its process?', 'ignore it', 'save instance state and restore it on recreation', 'increase the heap', 'disable background data', 'B', 'Persisting instance state lets the app recreate its UI after the process is killed and restarted.', 'ADVANCED', 3, 'MCQ', 1),
(3414, 99, 'What is the key difference between a virtual machine and a container in backend deployments?', 'none', 'containers run without an OS', 'a VM virtualizes hardware with its own OS while a container shares the host kernel and isolates processes', 'a VM is always faster', 'C', 'VMs include a full guest OS, whereas containers share the host kernel and isolate processes and namespaces.', 'ADVANCED', 3, 'MCQ', 1),
(3415, 99, 'A macOS app must perform a long computation without freezing the UI. What is the appropriate pattern?', 'run it on the main thread', 'sleep the main thread', 'run it on the main thread after a delay', 'dispatch the work to a background queue via GCD and update the UI on the main queue', 'D', 'Moving heavy work off the main thread keeps the UI responsive, and UI updates must return to the main thread.', 'ADVANCED', 3, 'MCQ', 1),
(3416, 99, 'Which statement best describes iOS app memory management with ARC?', 'ARC inserts retain and release calls at compile time, so objects are freed when no strong references remain', 'ARC runs a garbage collector at runtime', 'ARC disables memory management', 'ARC is only for games', 'A', 'ARC adds automatic retain and release at compile time so memory is reclaimed based on reference counts.', 'ADVANCED', 3, 'MCQ', 1),
(3417, 99, 'Why does Android require apps to declare permissions in the manifest?', 'to increase app size', 'so users can review and grant access to sensitive resources at install or runtime', 'to improve compile speed', 'to satisfy app store screenshots', 'B', 'Declaring permissions lets users make informed decisions about the sensitive data an app may access.', 'ADVANCED', 3, 'MCQ', 1),
(3418, 99, 'Which is the main reason a sandboxed iOS app cannot modify another app''s container?', 'the container is read-only', 'filesystem access is limited by the kernel to the app''s own sandbox', 'apps are too small', 'the App Store blocks it', 'C', 'The kernel enforces each app''s sandbox, restricting filesystem access to the app''s own container.', 'ADVANCED', 3, 'MCQ', 1),
(3419, 99, 'For a crash reporter, why is symbolication necessary?', 'to encrypt logs', 'to compress reports', 'to hide internal names', 'to map crash stack addresses back to readable function names in the app binary', 'D', 'Symbolication converts raw memory addresses in a crash log into readable function and line information.', 'ADVANCED', 3, 'MCQ', 1),
(3420, 99, 'Which approach best manages the interaction between a UI thread and a slow network call in Android?', 'perform the call off the main thread, such as with a coroutine or async task, and post results back to the main thread', 'block the main thread', 'call twice', 'use a broadcast', 'A', 'Offloading network work avoids blocking the UI, and posting results back to the main thread updates the UI safely.', 'ADVANCED', 3, 'MCQ', 1),
(3421, 100, 'What is a hypervisor?', 'software that creates and runs virtual machines', 'a web server', 'a firewall', 'a database', 'A', 'A hypervisor is the software layer that creates and manages virtual machines on a host.', 'BEGINNER', 1, 'MCQ', 1),
(3422, 100, 'Which type of hypervisor runs directly on the hardware?', 'Type 2', 'Type 1 (bare-metal)', 'Type 3', 'hosted', 'B', 'A Type 1 hypervisor runs directly on the hardware without a host operating system.', 'BEGINNER', 1, 'MCQ', 1),
(3423, 100, 'Which product is a Type 1 hypervisor?', 'VirtualBox', 'VMware ESXi', 'Wine', 'Docker Desktop only', 'C', 'VMware ESXi is a bare-metal Type 1 hypervisor, while VirtualBox is a hosted Type 2 hypervisor.', 'BEGINNER', 1, 'MCQ', 1),
(3424, 100, 'What is the main benefit of virtualization?', 'faster networks', 'running multiple isolated operating systems on one physical host', 'free RAM', 'better graphics', 'D', 'Virtualization lets many isolated guest OSes share a single physical server.', 'BEGINNER', 1, 'MCQ', 1),
(3425, 100, 'What is a container?', 'a lightweight, isolated environment that shares the host OS kernel', 'a physical server', 'a virtual machine', 'a hard drive', 'A', 'Containers package an application with its dependencies and share the host kernel for isolation.', 'BEGINNER', 1, 'MCQ', 1),
(3426, 100, 'Which tool is the most common container runtime?', 'MySQL', 'Docker', 'Apache', 'Nginx', 'B', 'Docker is the most widely used container runtime and image tooling ecosystem.', 'BEGINNER', 1, 'MCQ', 1),
(3427, 100, 'What is the difference between a Docker image and a running container?', 'An image is a read-only template while a container is a live, writable instance created from it', 'An image is a running process', 'A container is stored only on the registry', 'There is no difference', 'A', 'A Docker image is an immutable template of layers, and a running container is a writable instance that executes from that template.', 'BEGINNER', 1, 'MCQ', 1),
(3428, 100, 'What is a virtual machine''s disk file often called?', 'a container layer', 'an image tag', 'a registry', 'a virtual disk, such as VMDK, VHDX or VDI', 'D', 'A VM stores its virtual hard drive in a file format like VMDK, VHDX or VDI.', 'BEGINNER', 1, 'MCQ', 1),
(3429, 100, 'Which file describes how to build a Docker image?', 'Dockerfile', 'Docker.conf', 'docker.ini', 'Docker.ps1', 'A', 'A Dockerfile contains the instructions that build and configure a Docker image.', 'BEGINNER', 1, 'MCQ', 1),
(3430, 100, 'What is a container image layer?', 'a kind of network', 'a read-only filesystem layer that builds on previous layers', 'a VM snapshot', 'a load balancer', 'B', 'Images are built from stacked read-only layers, each representing a step in the build process.', 'BEGINNER', 1, 'MCQ', 1),
(3431, 100, 'Which Linux kernel feature isolates and limits resources such as CPU, memory and devices for containers?', 'SELinux only', 'AppArmor', 'cgroups', 'systemd', 'C', 'Control groups (cgroups) allocate and limit CPU, memory and device resources for container processes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3432, 100, 'Which Linux feature gives a container its own view of processes and network?', 'namespaces', 'the scheduler', 'iptables', 'the page cache', 'D', 'Namespaces isolate process, network, mount and other views so containers appear to have their own system.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3433, 100, 'What is the difference between a virtual machine and a container?', 'a VM has its own OS and kernel while a container shares the host kernel', 'containers are slower', 'VMs are lighter', 'there is no difference', 'A', 'VMs each run a full guest OS, while containers share the host kernel and isolate only the application environment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3434, 100, 'What does it mean to horizontally scale a containerized application?', 'Increasing the number of running instances to handle more load', 'Increasing the memory of a single instance', 'Shrinking the image size', 'Moving the app to a bigger node', 'A', 'Horizontal scaling adds more replicas of an application to spread load across nodes, whereas vertical scaling enlarges one instance.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3435, 100, 'Which feature lets you move a VM''s state to another host with little downtime?', 'a container image', 'live migration or a snapshot', 'a Dockerfile', 'a registry push', 'C', 'Live migration transfers a running VM to another host with minimal interruption, and snapshots capture state for rollback.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3436, 100, 'What is Docker Hub?', 'a hypervisor', 'a container runtime', 'a VPN', 'a public registry where container images are stored and shared', 'D', 'Docker Hub is a hosted registry service for publishing and pulling public container images.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3437, 100, 'Why are containers generally more efficient than VMs at running many instances?', 'containers share the host kernel and start faster with less overhead', 'containers use more RAM', 'VMs have no kernel', 'containers cannot run Linux', 'A', 'Sharing the host kernel removes the per-instance OS overhead, so containers start quickly and use fewer resources.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3438, 100, 'What is a Docker volume?', 'a temporary directory', 'persistent storage that survives container recreation', 'a network interface', 'a CPU allocation', 'B', 'Volumes provide durable storage that remains available even after a container is recreated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3439, 100, 'Which of the following is a Type 2 hypervisor?', 'Xen', 'KVM', 'VirtualBox', 'Nutanix AHV', 'C', 'VirtualBox runs as a hosted application on top of an existing operating system, making it a Type 2 hypervisor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3440, 100, 'What is a snapshot of a VM?', 'a backup of a single file', 'a saved state of the VM''s disks and memory that can be reverted to', 'a compressed image', 'a network rule', 'D', 'A snapshot captures the VM''s disk and optionally memory state so it can be restored later.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3441, 100, 'A cloud provider wants strong isolation between many containers sharing one kernel. Which feature is critical?', 'the Dockerfile', 'image tagging', 'port forwarding', 'user namespaces and seccomp to limit the blast radius', 'D', 'User namespaces and seccomp reduce kernel attack surface, limiting damage if one container is compromised.', 'ADVANCED', 3, 'MCQ', 1),
(3442, 100, 'Which mechanism lets a hypervisor overcommit memory safely?', 'ballooning and page sharing, where guests return unused pages', 'disabling swap', 'increasing vCPU count', 'using more NICs', 'A', 'Balloon drivers reclaim unused guest memory and page sharing deduplicates identical pages to enable overcommit.', 'ADVANCED', 3, 'MCQ', 1),
(3443, 100, 'What is a nested virtualization concern for security teams?', 'it is always safe', 'a guest hypervisor requires host CPU virtualization extensions and adds complexity and risk', 'it doubles the kernel', 'it is illegal', 'B', 'Nesting depends on virtualization extensions and adds another layer whose escaping could compromise the host.', 'ADVANCED', 3, 'MCQ', 1),
(3444, 100, 'Why is a stateless container preferable for horizontal scaling?', 'it is smaller', 'it is faster', 'state in ephemeral layers is lost on restart, so scaling adds replicas and stores data externally', 'it uses more memory', 'C', 'Stateless containers are interchangeable, so replicas can be added and removed without data loss.', 'ADVANCED', 3, 'MCQ', 1),
(3445, 100, 'Which practice best describes immutable infrastructure?', 'updating servers in place', 'patching live VMs', 'restarting services nightly', 'never modifying running instances and replacing them with new images', 'D', 'Immutable infrastructure treats servers as disposable, replacing them with freshly built images instead of patching.', 'ADVANCED', 3, 'MCQ', 1),
(3446, 100, 'An administrator runs a privileged container. What is the security implication?', 'the container escapes many restrictions and can access host kernel resources, so it must be trusted', 'it is perfectly safe', 'it gets a new kernel', 'it cannot access the network', 'A', 'Privileged mode disables many container isolation barriers, granting the container deep host access.', 'ADVANCED', 3, 'MCQ', 1),
(3447, 100, 'Which approach reduces VM image sprawl and speeds up provisioning?', 'copying full VMDKs each time', 'using templates, thin provisioning, and a shared image library', 'increasing RAM', 'using more vCPUs', 'B', 'Templates and thin provisioning reuse a shared base and allocate space only as needed, cutting sprawl.', 'ADVANCED', 3, 'MCQ', 1),
(3448, 100, 'When a Dockerfile uses several layers and you change only the final RUN line, what happens on rebuild?', 'all layers rebuild', 'cached earlier layers are reused and only the changed layer is rebuilt', 'the image is deleted', 'the container restarts', 'C', 'Docker caches unchanged layers and rebuilds only from the first changed instruction onward.', 'ADVANCED', 3, 'MCQ', 1),
(3449, 100, 'Which Kubernetes object defines the desired number of identical container replicas?', 'a Service', 'a ConfigMap', 'a Volume', 'a Deployment', 'D', 'A Deployment manages a replica set that keeps the specified number of identical pods running.', 'ADVANCED', 3, 'MCQ', 1),
(3450, 100, 'What is the primary reason to combine VMs and containers in one architecture?', 'VMs provide strong isolation and hardware abstraction while containers add density and fast scaling', 'containers cannot run Linux', 'VMs are cheaper', 'containers provide isolation from the host', 'A', 'Using both layers lets teams get VM-grade isolation where needed and container density and speed elsewhere.', 'ADVANCED', 3, 'MCQ', 1);
